mod common;

use serde_json::{json, Value};
use std::fs;
use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};
use soul2d_core::Session;

#[test]
fn render_refuses_to_overwrite_the_open_document() {
    let directory = temp_dir();
    for native in [false, true] {
        let source = directory.join(if native { "source.cmo3" } else { "source.inx" });
        let mut session = Session::new();
        if native {
            fs::write(&source, native_artmesh_bytes("<f xs.n='opacity'>0.75</f>")).unwrap();
            result(&request(&mut session, json!({"op":"open","path":source})));
        } else {
            result(&request(&mut session, json!({"op":"save","path":source})));
        }
        let bytes = fs::read(&source).unwrap();
        let before = session.snapshot();
        let response = request(&mut session, json!({"op":"render","width":4,"height":4,
            "bounds":[0,0,10,10],"path":source}));
        assert_eq!(response["succeeded"], false, "render must protect the open document: {response}");
        assert!(response["message"].as_str().unwrap().contains("would overwrite the open document"), "{native}: {response}");
        assert_eq!(fs::read(&source).unwrap(), bytes);
        assert_eq!(session.snapshot(), before);
        #[cfg(unix)]
        {
            let alias = directory.join(if native { "native-alias.png" } else { "inx-alias.png" });
            std::os::unix::fs::symlink(&source, &alias).unwrap();
            let response = request(&mut session, json!({"op":"render","width":4,"height":4,
                "bounds":[0,0,10,10],"path":alias}));
            assert_eq!(response["succeeded"], false, "{response}");
            assert_eq!(fs::read(&source).unwrap(), bytes);
        }
        for path in [None, Some(Value::Null), Some(json!(directory.join(if native { "native.png" } else { "inx.png" })))] {
            let mut call = json!({"op":"render","width":4,"height":4,"bounds":[0,0,10,10]});
            if let Some(path) = path { call["path"] = path; }
            let response = request(&mut session, call);
            assert!(result(&response)["png"].is_string());
            assert_eq!(fs::read(&source).unwrap(), bytes);
            assert_eq!(session.snapshot(), before);
        }
    }
}

#[test]
fn runtime_and_motion_exports_do_not_recreate_a_removed_open_document_as_json() {
    let directory = temp_dir();
    for native in [false, true] {
        let source = directory.join(if native { "source.cmo3" } else { "source.inx" });
        let mut session = Session::new();
        let call = if native {
            let xml = native_artmesh_xml("")
                .replace("<CParameterId xs.n='id' idstr='ParamTest'/>", "<CParameterId xs.n='id' idstr='ParamTest'/>\
                    <s xs.n='name'>Angle</s><CParameterGroupGuid xs.n='parentGroupGuid' uuid='group-guid'/>")
                .replace("<CDrawableSourceSet", "<CParameterGroupSet xs.n='parameterGroupSet'><carray_list xs.n='_groups' count='1'>\
                    <CParameterGroup><CParameterGroupGuid xs.n='guid' uuid='group-guid'/><null xs.n='parentGroupGuid'/>\
                    <carray_list xs.n='_childGuids' count='1'><CParameterGuid uuid='parameter-guid'/></carray_list></CParameterGroup>\
                    </carray_list></CParameterGroupSet><CDrawableSourceSet")
                .replace("<CPartId xs.n='id' idstr='root'/>", "<CPartId xs.n='id' idstr='root'/><carray_list xs.n='_childGuids' count='0'/>");
            fs::write(&source, authoring_bytes(&xml)).unwrap();
            result(&request(&mut session, json!({"op":"open","path":source})));
            result(&request(&mut session, json!({"op":"live2d.cdi3.export"})));
            json!({"op":"live2d.cdi3.export","path":source})
        } else {
            let motion = directory.join("motion.json");
            fs::write(&motion, serde_json::to_vec(&motion3_fixture()).unwrap()).unwrap();
            result(&request(&mut session, json!({"op":"motion3.import","name":"Motion","path":motion})));
            result(&request(&mut session, json!({"op":"save","path":source})));
            json!({"op":"motion3.export","name":"Motion","path":source})
        };
        fs::remove_file(&source).unwrap();
        let before = session.snapshot();
        let response = request(&mut session, call);
        assert_eq!(response["succeeded"], false, "{response}");
        assert!(response["message"].as_str().unwrap().contains("would overwrite the open document"), "{native}: {response}");
        assert!(!source.exists());
        assert_eq!(session.snapshot(), before);
    }
}

#[test]
fn document_format_comes_from_storage_not_unknown_model_fields() {
    let mut session = Session::new();
    let mut model = session.snapshot()["model"].clone();
    model["format"] = json!("live2d.authoring.source.v1");
    let response = session.handle_request(&json!({"op":"new", "model":model}));
    assert_eq!(response["succeeded"], true);
    assert_eq!(response["result"]["documentFormat"], "inx");
    assert_eq!(session.snapshot()["model"]["format"], "live2d.authoring.source.v1");
    let before = session.snapshot();
    let rejected = session.handle_request(&json!({"op":"live2d.form.set_vertex",
        "sourceGuid":"mesh", "formGuid":"form", "coordinateType":"Canvas",
        "vertexIndex":0, "position":[1,2], "expectedRevision":before["revision"]}));
    assert_eq!(rejected["succeeded"], false);
    assert_eq!(session.snapshot(), before);
}

/// Issue #149: a synthetic CMO3 at Cubism Pro sizes (a 100x100 warp, 2,000 ArtMeshes, 1,000 parameters) opens,
/// takes an edit, saves and reopens. The timings and sizes are printed for the record; the caps that matter are
/// the 64 MiB expanded-XML and 100,000-entry container limits and the 1,000,000-node XML limit of the writer.
#[test]
fn a_pro_size_cmo3_opens_edits_saves_and_reopens() {
    const MESHES: usize = 2000;
    const PARAMETERS: usize = 1000;
    const GRID: usize = 100;
    let mesh = |i: usize| format!(
        "<CArtMeshSource xs.id='mesh{i}'><ACDrawableSource xs.n='super'><CArtMeshGuid xs.n='guid' uuid='mesh-guid-{i}'/>\
         <CArtMeshId xs.n='id' idstr='ArtMesh{i}'/><CPartGuid xs.n='parentGuid' uuid='part-guid'/></ACDrawableSource>\
         <KeyformGridSource xs.n='keyformGridSource'><array_list xs.n='keyformBindings' count='0'/><array_list xs.n='keyformsOnGrid' count='1'>\
         <KeyformOnGrid><KeyformGridAccessKey xs.n='accessKey'><array_list xs.n='_keyOnParameterList' count='0'/></KeyformGridAccessKey>\
         <CFormGuid xs.n='keyformGuid' uuid='form-guid-{i}'/></KeyformOnGrid></array_list></KeyformGridSource>\
         <float-array xs.n='positions' count='6'>0 0 1 0 1 1</float-array><float-array xs.n='uvs' count='6'>0 0 1 0 1 1</float-array>\
         <int-array xs.n='indices' count='3'>0 1 2</int-array><GTexture2D xs.n='texture' xs.ref='texture'/>\
         <carray_list xs.n='keyforms' count='1'><CArtMeshForm><ACDrawableForm xs.n='super'><ACForm xs.n='super'>\
         <CFormGuid xs.n='guid' uuid='form-guid-{i}'/><CArtMeshSource xs.n='_source' xs.ref='mesh{i}'/></ACForm>\
         <CoordType xs.n='coordType'><s xs.n='coordName'>Canvas</s></CoordType><f xs.n='opacity'>1</f></ACDrawableForm>\
         <float-array xs.n='positions' count='6'>{i} 0 {i} 1 1 1</float-array></CArtMeshForm></carray_list></CArtMeshSource>");
    let parameter = |i: usize| format!(
        "<CParameterSource><CParameterGuid xs.n='guid' uuid='parameter-guid-{i}'/><CParameterId xs.n='id' idstr='Param{i}'/>\
         <f xs.n='minValue'>-1</f><f xs.n='maxValue'>1</f><f xs.n='defaultValue'>0</f></CParameterSource>");
    let points: Vec<String> = (0..=GRID).flat_map(|row| (0..=GRID).map(move |column| format!("{column} {row}"))).collect();
    let warp = format!(
        "<CWarpDeformerSource xs.id='warp'><CWarpGuid xs.n='guid' uuid='warp-guid'/><CWarpId xs.n='id' idstr='Warp'/>\
         <CPartGuid xs.n='parentGuid' uuid='part-guid'/><i xs.n='col'>{GRID}</i><i xs.n='row'>{GRID}</i>\
         <KeyformGridSource xs.n='keyformGridSource'><array_list xs.n='keyformBindings' count='0'/><array_list xs.n='keyformsOnGrid' count='1'>\
         <KeyformOnGrid><KeyformGridAccessKey xs.n='accessKey'><array_list xs.n='_keyOnParameterList' count='0'/></KeyformGridAccessKey>\
         <CFormGuid xs.n='keyformGuid' uuid='warp-form'/></KeyformOnGrid></array_list></KeyformGridSource>\
         <carray_list xs.n='keyforms' count='1'><CWarpDeformerForm><CFormGuid xs.n='guid' uuid='warp-form'/>\
         <CWarpDeformerSource xs.n='_source' xs.ref='warp'/><CoordType xs.n='coordType'><s xs.n='coordName'>Canvas</s></CoordType>\
         <float-array xs.n='positions' count='{}'>{}</float-array></CWarpDeformerForm></carray_list></CWarpDeformerSource>",
        points.len() * 2, points.join(" "));
    let base = native_artmesh_xml("<f xs.n='opacity'>1</f>");
    let xml = base
        .replace("count='1'><CParameterSource>", &format!("count='{}'><CParameterSource>", PARAMETERS + 1))
        .replace("</CParameterSource></carray_list>", &format!("</CParameterSource>{}</carray_list>",
            (0..PARAMETERS).map(parameter).collect::<String>()))
        .replace("count='1'><CArtMeshSource xs.ref='mesh'/>", &format!("count='{}'><CArtMeshSource xs.ref='mesh'/>{}",
            MESHES + 1, (0..MESHES).map(|i| format!("<CArtMeshSource xs.ref='mesh{i}'/>")).collect::<String>()))
        .replace("<carray_list xs.n='_sources' count='0'/></CDeformerSourceSet>",
            "<carray_list xs.n='_sources' count='1'><CWarpDeformerSource xs.ref='warp'/></carray_list></CDeformerSourceSet>")
        .replace("<GTexture2D xs.id='texture'>", &format!("{warp}{}<GTexture2D xs.id='texture'>",
            (0..MESHES).map(mesh).collect::<String>()));
    let directory = temp_dir();
    let source = directory.join("pro.cmo3");
    let saved = directory.join("pro-saved.cmo3");
    fs::write(&source, authoring_bytes(&xml)).unwrap();
    let mut session = Session::new();
    let clock = std::time::Instant::now();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    let open_time = clock.elapsed();
    assert_eq!(opened["model"]["sources"].as_array().unwrap().len(), MESHES + 3);
    assert_eq!(opened["model"]["parameters"].as_array().unwrap().len(), PARAMETERS + 1);
    let clock = std::time::Instant::now();
    let edited = result(&request(&mut session, json!({"op":"live2d.form.set_vertex","sourceGuid":"warp-guid",
        "formGuid":"warp-form","coordinateType":"Canvas","vertexIndex":5050,"position":[50.5,50.25],
        "expectedRevision":opened["revision"]}))).clone();
    let edit_time = clock.elapsed();
    let clock = std::time::Instant::now();
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let save_time = clock.elapsed();
    let reopened = result(&request(&mut session, json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], edited["model"]);
    eprintln!("pro-size CMO3: {} bytes of XML, {} XML nodes; open {open_time:?}, vertex edit {edit_time:?}, save {save_time:?}",
        xml.len(), roxmltree::Document::parse(&xml).unwrap().descendants().count());
}

/// Issue #149: a synthetic CMO3 with 1,000 textures (a GTexture2D and a CAFF image entry each, on 1,000 ArtMeshes)
/// and 1,000 deformers (500 warps of 10x10 and 500 rotation deformers) opens, takes a warp and a rotation edit,
/// saves and reopens. Counts and timings are printed for the record.
#[test]
fn a_pro_size_cmo3_with_many_textures_and_deformers_opens_edits_saves_and_reopens() {
    const TEXTURES: usize = 1000;
    const WARPS: usize = 500;
    const ROTATIONS: usize = 500;
    const GRID: usize = 10;
    let mesh = |i: usize| format!(
        "<CArtMeshSource xs.id='mesh{i}'><ACDrawableSource xs.n='super'><CArtMeshGuid xs.n='guid' uuid='mesh-guid-{i}'/>\
         <CArtMeshId xs.n='id' idstr='ArtMesh{i}'/><CPartGuid xs.n='parentGuid' uuid='part-guid'/></ACDrawableSource>\
         <KeyformGridSource xs.n='keyformGridSource'><array_list xs.n='keyformBindings' count='0'/><array_list xs.n='keyformsOnGrid' count='1'>\
         <KeyformOnGrid><KeyformGridAccessKey xs.n='accessKey'><array_list xs.n='_keyOnParameterList' count='0'/></KeyformGridAccessKey>\
         <CFormGuid xs.n='keyformGuid' uuid='form-guid-{i}'/></KeyformOnGrid></array_list></KeyformGridSource>\
         <float-array xs.n='positions' count='6'>0 0 1 0 1 1</float-array><float-array xs.n='uvs' count='6'>0 0 1 0 1 1</float-array>\
         <int-array xs.n='indices' count='3'>0 1 2</int-array><GTexture2D xs.n='texture' xs.ref='texture{i}'/>\
         <carray_list xs.n='keyforms' count='1'><CArtMeshForm><ACDrawableForm xs.n='super'><ACForm xs.n='super'>\
         <CFormGuid xs.n='guid' uuid='form-guid-{i}'/><CArtMeshSource xs.n='_source' xs.ref='mesh{i}'/></ACForm>\
         <CoordType xs.n='coordType'><s xs.n='coordName'>Canvas</s></CoordType><f xs.n='opacity'>1</f></ACDrawableForm>\
         <float-array xs.n='positions' count='6'>{i} 0 {i} 1 1 1</float-array></CArtMeshForm></carray_list></CArtMeshSource>");
    let texture = |i: usize| format!(
        "<GTexture2D xs.id='texture{i}'><GTexture xs.n='super'><GTextureGuid xs.n='guid' uuid='texture-guid-{i}'/>\
         <FilterMode xs.n='filterMode'><MinFilter xs.n='minFilter' v='LINEAR'/><MagFilter xs.n='magFilter' v='LINEAR'/></FilterMode></GTexture>\
         <CImageResource xs.n='srcImageResource' width='2' height='3'><file xs.n='imageFileBuf' path='tex{i}.png'/></CImageResource>\
         <null xs.n='transformImageResource01toLogical01'/></GTexture2D>");
    let points: Vec<String> = (0..=GRID).flat_map(|row| (0..=GRID).map(move |column| format!("{column} {row}"))).collect();
    let warp = |i: usize| format!(
        "<CWarpDeformerSource xs.id='warp{i}'><CWarpGuid xs.n='guid' uuid='warp-guid-{i}'/><CWarpId xs.n='id' idstr='Warp{i}'/>\
         <CPartGuid xs.n='parentGuid' uuid='part-guid'/><i xs.n='col'>{GRID}</i><i xs.n='row'>{GRID}</i>\
         <KeyformGridSource xs.n='keyformGridSource'><array_list xs.n='keyformBindings' count='0'/><array_list xs.n='keyformsOnGrid' count='1'>\
         <KeyformOnGrid><KeyformGridAccessKey xs.n='accessKey'><array_list xs.n='_keyOnParameterList' count='0'/></KeyformGridAccessKey>\
         <CFormGuid xs.n='keyformGuid' uuid='warp-form-{i}'/></KeyformOnGrid></array_list></KeyformGridSource>\
         <carray_list xs.n='keyforms' count='1'><CWarpDeformerForm><CFormGuid xs.n='guid' uuid='warp-form-{i}'/>\
         <CWarpDeformerSource xs.n='_source' xs.ref='warp{i}'/><CoordType xs.n='coordType'><s xs.n='coordName'>Canvas</s></CoordType>\
         <float-array xs.n='positions' count='{}'>{}</float-array></CWarpDeformerForm></carray_list></CWarpDeformerSource>",
        points.len() * 2, points.join(" "));
    let rotation = |i: usize| format!(
        "<CRotationDeformerSource xs.id='rotation{i}'><ACDeformerSource xs.n='super'><CRotationDeformerGuid xs.n='guid' uuid='rotation-guid-{i}'/>\
         <CDeformerId xs.n='id' idstr='Rotation{i}'/><CPartGuid xs.n='parentGuid' uuid='part-guid'/></ACDeformerSource>\
         <carray_list xs.n='keyforms' count='1'><CRotationDeformerForm angle='15' originX='10' originY='20' scale='1' isReflectX='false' isReflectY='false'>\
         <ACDeformerForm xs.n='super'><ACForm xs.n='super'><CFormGuid xs.n='guid' uuid='rotation-form-{i}'/>\
         <CRotationDeformerSource xs.n='_source' xs.ref='rotation{i}'/></ACForm>\
         <CoordType xs.n='coordType'><s xs.n='coordName'>Canvas</s></CoordType></ACDeformerForm></CRotationDeformerForm></carray_list>\
         </CRotationDeformerSource>");
    let xml = native_artmesh_xml("<f xs.n='opacity'>1</f>")
        .replace("count='1'><CArtMeshSource xs.ref='mesh'/>", &format!("count='{}'><CArtMeshSource xs.ref='mesh'/>{}",
            TEXTURES + 1, (0..TEXTURES).map(|i| format!("<CArtMeshSource xs.ref='mesh{i}'/>")).collect::<String>()))
        .replace("<carray_list xs.n='_sources' count='0'/></CDeformerSourceSet>", &format!(
            "<carray_list xs.n='_sources' count='{}'>{}{}</carray_list></CDeformerSourceSet>", WARPS + ROTATIONS,
            (0..WARPS).map(|i| format!("<CWarpDeformerSource xs.ref='warp{i}'/>")).collect::<String>(),
            (0..ROTATIONS).map(|i| format!("<CRotationDeformerSource xs.ref='rotation{i}'/>")).collect::<String>()))
        .replace("<GTexture2D xs.id='texture'>", &format!("{}{}{}{}<GTexture2D xs.id='texture'>",
            (0..WARPS).map(warp).collect::<String>(), (0..ROTATIONS).map(rotation).collect::<String>(),
            (0..TEXTURES).map(mesh).collect::<String>(), (0..TEXTURES).map(texture).collect::<String>()));
    let directory = temp_dir();
    let source = directory.join("textures.cmo3");
    let saved = directory.join("textures-saved.cmo3");
    fs::write(&source, authoring_bytes_with_images(&xml, TEXTURES)).unwrap();
    let count = |model: &Value, kind: &str| model["sources"].as_array().unwrap().iter()
        .filter(|source| source["data"]["type"] == kind).count();
    let mut session = Session::new();
    let clock = std::time::Instant::now();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    let open_time = clock.elapsed();
    assert_eq!(opened["model"]["textures"].as_array().unwrap().len(), TEXTURES + 1);
    assert_eq!(count(&opened["model"], "ArtMesh"), TEXTURES + 1);
    assert_eq!(count(&opened["model"], "Warp"), WARPS);
    assert_eq!(count(&opened["model"], "Rotation"), ROTATIONS);
    let clock = std::time::Instant::now();
    let warped = result(&request(&mut session, json!({"op":"live2d.form.set_vertex","sourceGuid":"warp-guid-7",
        "formGuid":"warp-form-7","coordinateType":"Canvas","vertexIndex":60,"position":[5.5,5.25],
        "expectedRevision":opened["revision"]}))).clone();
    let warp_time = clock.elapsed();
    let clock = std::time::Instant::now();
    let edited = result(&request(&mut session, json!({"op":"live2d.form.set","sourceGuid":"rotation-guid-9",
        "formGuid":"rotation-form-9","coordinateType":"Canvas","angle":-30.5,"expectedRevision":warped["revision"]}))).clone();
    let rotation_time = clock.elapsed();
    let angle = edited["model"]["sources"].as_array().unwrap().iter()
        .find(|source| source["guid"] == "rotation-guid-9").unwrap()["forms"][0]["data"]["angle"].clone();
    assert_eq!(angle, json!(-30.5));
    let clock = std::time::Instant::now();
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let save_time = clock.elapsed();
    let reopened = result(&request(&mut session, json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], edited["model"]);
    eprintln!("pro-size CMO3 textures and deformers: {} textures, {WARPS} warps, {ROTATIONS} rotations, {} bytes of XML, \
        {} XML nodes; open {open_time:?}, warp edit {warp_time:?}, rotation edit {rotation_time:?}, save {save_time:?}",
        TEXTURES + 1, xml.len(), roxmltree::Document::parse(&xml).unwrap().descendants().count());
}

/// Issue #149, CAN3 side: one parameter curve with 20,000 keys opens, takes a key edit, saves and reopens.
#[test]
fn a_pro_size_can3_curve_opens_edits_saves_and_reopens() {
    const KEYS: usize = 20_000;
    let point = |frame: usize| format!(
        r#"<CBezierPt><CSeqPt xs.n="anchor"><i xs.n="pos">{frame}</i><d xs.n="doubleValue">{}</d><b xs.n="isCorner">false</b></CSeqPt>"#,
        (frame % 3) as f64 / 2.0)
        + &format!(r#"<CBezierCtrlPt xs.n="prev"><i xs.n="pos">{frame}</i><d xs.n="posF">{frame}</d><d xs.n="doubleValue">0</d><b xs.n="isPosOptimized">false</b></CBezierCtrlPt>"#)
        + &format!(r#"<CBezierCtrlPt xs.n="next"><i xs.n="pos">{frame}</i><d xs.n="posF">{frame}</d><d xs.n="doubleValue">0</d><b xs.n="isPosOptimized">false</b></CBezierCtrlPt></CBezierPt>"#);
    let curve = format!(r#"<carray_list xs.n="points" count="{KEYS}">{}</carray_list><carray_list xs.n="curveTypes" count="{KEYS}">{}</carray_list><d xs.n="curMin">0</d><d xs.n="curMax">1</d>"#,
        (0..KEYS).map(point).collect::<String>(), r#"<CCurveType v="LINEAR"/>"#.repeat(KEYS));
    let xml = BINDING_CAN3_XML.replace(r#"<carray_list xs.n="points" count="0"/><carray_list xs.n="curveTypes" count="0"/>"#, &curve);
    let directory = temp_dir();
    let (source, saved) = (directory.join("long.can3"), directory.join("long-saved.can3"));
    fs::write(&source, authoring_bytes(&xml)).unwrap();
    let mut session = Session::new();
    let clock = std::time::Instant::now();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    let open_time = clock.elapsed();
    let points = &opened["model"]["scenes"][0]["tracks"][0]["parameterCurves"][0]["points"];
    assert_eq!(points.as_array().map(Vec::len), Some(KEYS), "{}", opened["model"]["scenes"][0]["tracks"][0]);
    let clock = std::time::Instant::now();
    let edited = result(&request(&mut session, json!({"op":"live2d.animation.key.set","sceneGuid":"scene-guid",
        "trackGuid":"track-guid","curveId":"live2dParam_ParamTest","anchorFrame":KEYS / 2,"value":0.25,
        "expectedRevision":opened["revision"]}))).clone();
    let edit_time = clock.elapsed();
    let clock = std::time::Instant::now();
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let save_time = clock.elapsed();
    let reopened = result(&request(&mut session, json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], edited["model"]);
    eprintln!("pro-size CAN3: {} bytes of XML, {} XML nodes; open {open_time:?}, key edit {edit_time:?}, save {save_time:?}",
        xml.len(), roxmltree::Document::parse(&xml).unwrap().descendants().count());
}

#[test]
#[ignore = "large decoded-texture workload runs sequentially in capacity CI"]
fn a_pro_size_cmo3_large_textures_render_and_roundtrip() {
    const SIZE: u32 = 2048;
    let colors = [[220, 40, 20, 255], [20, 190, 40, 255], [30, 50, 210, 255], [190, 40, 180, 255]];
    let pngs: Vec<Vec<u8>> = colors.iter().map(|color| {
        let mut out = std::io::Cursor::new(Vec::new());
        image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(SIZE, SIZE, image::Rgba(*color)))
            .write_to(&mut out, image::ImageFormat::Png).unwrap();
        out.into_inner()
    }).collect();
    let base = native_artmesh_xml("<f xs.n='opacity'>1</f>");
    let parsed = roxmltree::Document::parse(&base).unwrap();
    let source = &base[parsed.descendants().find(|node| node.attribute("xs.id") == Some("mesh")).unwrap().range()];
    let texture = &base[parsed.descendants().find(|node| node.attribute("xs.id") == Some("texture")).unwrap().range()];
    let sources: String = (0..4).map(|i| {
        let (x, y) = ((i % 2) * 2, (i / 2) * 2);
        source.replace("'mesh'", &format!("'mesh{i}'")).replace("mesh-guid", &format!("mesh-guid-{i}"))
            .replace("form-guid", &format!("form-guid-{i}"))
            .replace("xs.ref='texture'", &format!("xs.ref='texture{i}'"))
            .replace("1 2 3 4 5 6", &format!("{x} {y} {} {y} {x} {}", x + 2, y + 2))
    }).collect();
    let textures: String = (0..4).map(|i| texture.replace("'texture'", &format!("'texture{i}'"))
        .replace("texture-guid", &format!("texture-guid-{i}"))
        .replace("width='2' height='3'", &format!("width='{SIZE}' height='{SIZE}'"))
        .replace("mesh.png", &if i == 0 { "mesh.png".into() } else { format!("tex{}.png", i - 1) })).collect();
    let xml = base.replace(source, &sources).replace(texture, &textures)
        .replace("count='1'><CArtMeshSource xs.ref='mesh'/>", &format!("count='4'>{}",
            (0..4).map(|i| format!("<CArtMeshSource xs.ref='mesh{i}'/>")).collect::<String>()));
    let bytes = authoring_bytes_with_pngs(&xml, &pngs);
    let directory = temp_dir();
    let (original, saved) = (directory.join("large-textures.cmo3"), directory.join("large-textures-saved.cmo3"));
    fs::write(&original, &bytes).unwrap();
    let mut session = Session::new();
    let clock = std::time::Instant::now();
    let opened = result(&request(&mut session, json!({"op":"open","path":original}))).clone();
    let render = |session: &mut Session| {
        let response = request(session, json!({"op":"render","width":32,"height":32,"bounds":[0,0,4,4]}));
        let png = result(&response)["png"].as_str().unwrap();
        image::load_from_memory(&base64::Engine::decode(&base64::engine::general_purpose::STANDARD, png).unwrap())
            .unwrap().into_rgba8()
    };
    let before = render(&mut session);
    for (i, color) in colors.iter().enumerate() {
        let (x, y) = ((i as u32 % 2) * 16 + 4, (i as u32 / 2) * 16 + 4);
        assert_eq!(before.get_pixel(x, y).0, *color, "texture {i} must be decoded and drawn");
    }
    let edited = result(&request(&mut session, json!({"op":"live2d.form.set_opacity",
        "sourceGuid":"mesh-guid-0","formGuid":"form-guid-0","coordinateType":"Canvas","opacity":0.5,
        "expectedRevision":opened["revision"]}))).clone();
    assert_ne!(render(&mut session), before);
    result(&request(&mut session, json!({"op":"undo"})));
    assert_eq!(render(&mut session), before);
    result(&request(&mut session, json!({"op":"redo"})));
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let reopened = result(&request(&mut session, json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], edited["model"]);
    assert_ne!(render(&mut session), before);
    let container = soul2d_core::caff::CaffDocument::parse(&fs::read(saved).unwrap()).unwrap();
    for (i, png) in pngs.iter().enumerate() {
        let name = if i == 0 { "mesh.png".into() } else { format!("tex{}.png", i - 1) };
        assert_eq!(container.entry_data(&name).unwrap(), *png);
    }
    assert_eq!(fs::read(original).unwrap(), bytes);
    eprintln!("large-texture CMO3: 4 textures, {SIZE}x{SIZE} RGBA, {} decoded bytes, {} container bytes, {} XML bytes; open/render/edit/undo/redo/save/reopen {:?}",
        4u64 * SIZE as u64 * SIZE as u64 * 4, bytes.len(), xml.len(), clock.elapsed());
    fs::remove_dir_all(directory).unwrap();
}

#[test]
#[ignore = "keyed-parameter and dense-form workload runs sequentially in capacity CI"]
fn a_pro_size_cmo3_keyed_parameters_and_dense_forms_roundtrip() {
    const WIDE_MESHES: usize = 512;
    let base = native_artmesh_xml("<f xs.n='opacity'>1</f>");
    let parsed = roxmltree::Document::parse(&base).unwrap();
    let mesh = parsed.descendants().find(|node| node.attribute("xs.id") == Some("mesh")).unwrap();
    let mesh_text = &base[mesh.range()];
    let grid = mesh.children().find(|node| node.has_tag_name("KeyformGridSource")).unwrap();
    let form = mesh.descendants().find(|node| node.has_tag_name("CArtMeshForm")).unwrap();
    let forms = mesh.children().find(|node| node.attribute("xs.n") == Some("keyforms")).unwrap();
    let parameter = parsed.descendants().find(|node| node.has_tag_name("CParameterSource")).unwrap();
    let parameter_list = parameter.parent().unwrap();
    let donor = native_morph_artmesh_xml("", "");
    let donor_tree = roxmltree::Document::parse(&donor).unwrap();
    let binding = donor_tree.descendants().find(|node| node.attribute("xs.id") == Some("binding")).unwrap();
    let binding_text = &donor[binding.range()];
    let mut parameters = String::new();
    let mut bindings = String::new();
    let mut meshes = String::new();
    let mut values = serde_json::Map::new();
    for group in 0..=WIDE_MESHES {
        let (axes, keys): (usize, usize) = if group == WIDE_MESHES { (3, 9) } else { (2, 3) };
        let key_values: Vec<f64> = (0..keys).map(|key| -1.0 + key as f64 * 2.0 / (keys - 1) as f64).collect();
        let mut binding_refs = String::new();
        for axis in 0..axes {
            let id = format!("Param{group}_{axis}");
            let guid = format!("parameter-guid-{group}-{axis}");
            let binding_id = format!("binding-{group}-{axis}");
            parameters.push_str(&base[parameter.range()].replace("parameter-guid", &guid).replace("ParamTest", &id));
            bindings.push_str(&binding_text.replace("xs.id='binding'", &format!("xs.id='{binding_id}'"))
                .replace("parameter-guid", &guid)
                .replace("<array_list xs.n='keys' count='2'><f>-1</f><f>1</f></array_list>",
                    &format!("<array_list xs.n='keys' count='{keys}'>{}</array_list>",
                        key_values.iter().map(|value| format!("<f>{value}</f>")).collect::<String>())));
            binding_refs.push_str(&format!("<KeyformBindingSource xs.ref='{binding_id}'/>"));
            let sample = if group == WIDE_MESHES { [0.125, 0.375, -0.625][axis] }
                else { [if group & 1 == 0 { 0.5 } else { -0.5 }, if group & 2 == 0 { -0.5 } else { 0.5 }][axis] };
            values.insert(id, json!(sample));
        }
        let cells = keys.pow(axes as u32);
        let mut cell_text = String::new();
        let mut form_text = String::new();
        for cell in 0..cells {
            let indices: Vec<usize> = (0..axes).map(|axis| cell / keys.pow(axis as u32) % keys).collect();
            let coordinates: Vec<f64> = indices.iter().map(|index| key_values[*index]).collect();
            let (a, b, c) = (coordinates[0], coordinates[1], coordinates.get(2).copied().unwrap_or(0.0));
            let (x, y) = (a + 2.0 * b + 4.0 * c, 3.0 * a - b + 2.0 * c);
            let guid = format!("keyed-form-{group}-{cell}");
            cell_text.push_str(&format!("<KeyformOnGrid><KeyformGridAccessKey xs.n='accessKey'>\
                <array_list xs.n='_keyOnParameterList' count='{axes}'>{}</array_list></KeyformGridAccessKey>\
                <CFormGuid xs.n='keyformGuid' uuid='{guid}'/></KeyformOnGrid>",
                indices.iter().enumerate().map(|(axis, index)| format!("<KeyOnParameter>\
                    <KeyformBindingSource xs.n='binding' xs.ref='binding-{group}-{axis}'/>\
                    <i xs.n='keyIndex'>{index}</i></KeyOnParameter>")).collect::<String>()));
            form_text.push_str(&base[form.range()].replace("form-guid", &guid)
                .replace("xs.ref='mesh'", &format!("xs.ref='keyed-mesh-{group}'"))
                .replace("1 2 3 4 5 6", &format!("{x} {y} 3 4 5 6")));
        }
        meshes.push_str(&mesh_text.replace(&base[grid.range()], &format!("<KeyformGridSource xs.n='keyformGridSource'>\
            <array_list xs.n='keyformBindings' count='{axes}'>{binding_refs}</array_list>\
            <array_list xs.n='keyformsOnGrid' count='{cells}'>{cell_text}</array_list></KeyformGridSource>"))
            .replace(&base[forms.range()], &format!("<carray_list xs.n='keyforms' count='{cells}'>{form_text}</carray_list>"))
            .replace("'mesh'", &format!("'keyed-mesh-{group}'")).replace("mesh-guid", &format!("keyed-mesh-guid-{group}")));
    }
    let xml = base.replace(&base[parameter_list.range()], &format!("<carray_list xs.n='_sources' count='1027'>{parameters}</carray_list>"))
        .replace(mesh_text, &meshes)
        .replace("count='1'><CArtMeshSource xs.ref='mesh'/>", &format!("count='513'>{}",
            (0..=WIDE_MESHES).map(|group| format!("<CArtMeshSource xs.ref='keyed-mesh-{group}'/>")).collect::<String>()))
        .replace("<CPartSource xs.id='part'>", &format!("{bindings}<CPartSource xs.id='part'>"));
    let nodes = roxmltree::Document::parse(&xml).unwrap().descendants().count();
    assert!(xml.len() < 64 * 1024 * 1024 && nodes < 1_000_000);
    assert_eq!(values.len(), 1027);
    let bytes = authoring_bytes(&xml);
    let directory = temp_dir();
    let (source, saved) = (directory.join("keyed.cmo3"), directory.join("keyed-saved.cmo3"));
    fs::write(&source, &bytes).unwrap();
    let mut session = Session::new();
    let clock = std::time::Instant::now();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    assert_eq!(opened["model"]["parameters"].as_array().unwrap().len(), 1027);
    assert_eq!(opened["model"]["sources"].as_array().unwrap().iter()
        .map(|source| source["forms"].as_array().unwrap().len()).sum::<usize>(), 5337);
    let evaluate = |session: &mut Session, edited: usize| {
        let response = request(session, json!({"op":"live2d.authoring.primary_forms","parameterValues":values}));
        let meshes: Vec<_> = result(&response)["sources"].as_array().unwrap().iter()
            .filter(|source| source["guid"].as_str().unwrap().starts_with("keyed-mesh-guid-")).collect();
        assert_eq!(meshes.len(), 513);
        for mesh in meshes {
            let group: usize = mesh["guid"].as_str().unwrap().strip_prefix("keyed-mesh-guid-").unwrap().parse().unwrap();
            let dense = group == WIDE_MESHES;
            let (a, b) = (if group & 1 == 0 { 0.5 } else { -0.5 }, if group & 2 == 0 { -0.5 } else { 0.5 });
            assert_eq!(mesh["axisValues"], if dense { json!([0.125,0.375,-0.625]) } else { json!([a,b]) });
            let weights = mesh["weights"].as_array().unwrap();
            assert_eq!(weights.len(), if dense { 8 } else { 4 });
            assert!(weights.iter().all(|weight| weight["weight"] == if dense { 0.125 } else { 0.25 }));
            let changed = (edited >= 1 && mesh["guid"] == "keyed-mesh-guid-0") || (edited == 2 && dense);
            let (x, y) = if dense { (-1.625, -1.25) } else { (a + 2.0 * b, 3.0 * a - b) };
            assert_eq!(mesh["evaluatedForms"][0]["data"]["positions"],
                json!([x + if changed { 1.0 } else { 0.0 }, y + if changed { 2.0 } else { 0.0 },3.0,4.0,5.0,6.0]));
        }
    };
    evaluate(&mut session, 0);
    let mut models = vec![opened["model"].clone()];
    for (group, cell, position) in [(0, 1, [2.0,9.0]), (WIDE_MESHES, 130, [5.5,14.25])] {
        let revision = session.snapshot()["revision"].clone();
        let edited = result(&request(&mut session, json!({"op":"live2d.form.set_vertex",
            "sourceGuid":format!("keyed-mesh-guid-{group}"),"formGuid":format!("keyed-form-{group}-{cell}"),
            "coordinateType":"Canvas","vertexIndex":0,"position":position,"expectedRevision":revision}))).clone();
        models.push(edited["model"].clone());
        evaluate(&mut session, models.len() - 1);
    }
    for (op, state) in [("undo",1), ("undo",0), ("redo",1), ("redo",2)] {
        assert_eq!(result(&request(&mut session, json!({"op":op})))["model"], models[state]);
        evaluate(&mut session, state);
    }
    let before = session.snapshot();
    let stale = request(&mut session, json!({"op":"live2d.form.set_vertex","sourceGuid":"keyed-mesh-guid-0",
        "formGuid":"keyed-form-0-1","coordinateType":"Canvas","vertexIndex":0,"position":[0,0],
        "expectedRevision":opened["revision"]}));
    assert_eq!(stale["succeeded"], false);
    assert_eq!(session.snapshot(), before);
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let mut reopened = Session::new();
    assert_eq!(result(&request(&mut reopened, json!({"op":"open","path":saved})))["model"], models[2]);
    evaluate(&mut reopened, 2);
    let container = soul2d_core::caff::CaffDocument::parse(&fs::read(saved).unwrap()).unwrap();
    let original = soul2d_core::caff::CaffDocument::parse(&bytes).unwrap();
    for name in ["mesh.png", "opaque.bin"] { assert_eq!(container.entry_data(name), original.entry_data(name)); }
    assert!(String::from_utf8(container.main_xml()).unwrap().contains("<Opaque xs.id='future-data'>keep-this-xml</Opaque>"));
    assert_eq!(fs::read(source).unwrap(), bytes);
    eprintln!("keyed CMO3: 1027 parameters, 512 two-axis 3-key meshes plus one three-axis 9-key mesh, 5337 forms; \
        {} XML bytes, {nodes} XML nodes; open/evaluate/edit/history/save/reopen {:?}", xml.len(), clock.elapsed());
    fs::remove_dir_all(directory).unwrap();
}

#[test]
#[ignore = "decoder allocation boundary runs sequentially in capacity CI"]
fn a_capacity_native_texture_limits_refuse_without_state_changes() {
    let directory = temp_dir();
    for (width, height) in [(8193, 1), (4097, 4096)] {
        let mut png = std::io::Cursor::new(Vec::new());
        image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(width, height, image::Rgba([30, 90, 60, 255])))
            .write_to(&mut png, image::ImageFormat::Png).unwrap();
        let xml = native_artmesh_xml("").replace("width='2' height='3'", &format!("width='{width}' height='{height}'"));
        let bytes = authoring_bytes_with_pngs(&xml, &[png.into_inner()]);
        let source = directory.join(format!("limit-{width}-{height}.cmo3"));
        fs::write(&source, &bytes).unwrap();
        let mut session = Session::new();
        result(&request(&mut session, json!({"op":"open","path":source})));
        let before = session.snapshot();
        let response = request(&mut session, json!({"op":"render","width":32,"height":32,"bounds":[0,0,10,10]}));
        assert_eq!(response["succeeded"], false, "{response}");
        assert!(response["message"].as_str().unwrap().contains("could not decode unpremultiplied native texture"), "{response}");
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&source).unwrap(), bytes);
        fs::write(&source, native_artmesh_bytes("")).unwrap();
        result(&request(&mut session, json!({"op":"open","path":source})));
        result(&request(&mut session, json!({"op":"render","width":32,"height":32,"bounds":[0,0,10,10]})));
        eprintln!("native texture refusal: {width}x{height}, valid PNG; document/history/source unchanged, normal rendering recovered");
    }
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn native_form_settings_save_reopen_and_undo() {
    let directory = temp_dir();
    let source = directory.join("source.cmo3");
    let saved = directory.join("settings.cmo3");
    fs::write(&source, native_artmesh_bytes("<i xs.n='drawOrder'>500</i><f xs.n='opacity'>0.75</f>")).unwrap();
    let mut session = Session::new();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    let revision = opened["revision"].as_u64().unwrap();
    let form = json!({"op":"live2d.form.set","sourceGuid":"mesh-guid","formGuid":"form-guid","coordinateType":"Canvas"});
    let mut absent = form.clone();
    absent["screenColor"] = json!([0.5, 0.5, 0.5]);
    absent["expectedRevision"] = json!(revision);
    let refused = request(&mut session, absent);
    assert!(refused["message"].as_str().unwrap().contains("stores no screenColor"), "{refused}");
    assert_eq!(session.snapshot(), opened);
    let mut order = form.clone();
    order["drawOrder"] = json!(620);
    order["expectedRevision"] = json!(revision);
    let edited = result(&request(&mut session, order)).clone();
    assert_eq!(edited["model"]["sources"][0]["forms"][0]["drawOrder"], 620);
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let reopened = result(&request(&mut session, json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"]["sources"][0]["forms"][0]["drawOrder"], 620);
    let again = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    let mut order = form.clone();
    order["drawOrder"] = json!(10);
    order["expectedRevision"] = again["revision"].clone();
    result(&request(&mut session, order));
    let undone = result(&request(&mut session, json!({"op":"undo"}))).clone();
    assert_eq!(undone["model"]["sources"][0]["forms"][0]["drawOrder"], 500);
}

#[test]
fn native_copy_saves_reopens_and_undoes() {
    let directory = temp_dir();
    let source = directory.join("source.cmo3");
    let saved = directory.join("copied.cmo3");
    let xml = native_artmesh_xml("<f xs.n='opacity'>0.75</f>").replace(
        "<CPartId xs.n='id' idstr='root'/>",
        "<CPartId xs.n='id' idstr='root'/><carray_list xs.n='_childGuids' count='1'><CArtMeshGuid uuid='mesh-guid'/></carray_list>");
    fs::write(&source, authoring_bytes(&xml)).unwrap();
    let mut session = Session::new();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    let copied = result(&request(&mut session, json!({"op":"live2d.duplicate","guid":"mesh-guid","id":"MeshCopy",
        "expectedRevision":opened["revision"]}))).clone();
    let guid = copied["guid"].as_str().unwrap().to_owned();
    assert_eq!(copied["model"]["sources"][1]["guid"], guid.as_str());
    assert_eq!(copied["model"]["sources"][1]["id"], "MeshCopy");
    let form = copied["model"]["sources"][1]["forms"][0]["guid"].clone();
    let moved = result(&request(&mut session, json!({"op":"live2d.form.set_vertex","sourceGuid":guid,"formGuid":form,
        "coordinateType":"Canvas","vertexIndex":2,"position":[50.0,60.0],"expectedRevision":copied["revision"]}))).clone();
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let reopened = result(&request(&mut Session::new(), json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], moved["model"]);
    result(&request(&mut session, json!({"op":"undo"})));
    let undone = result(&request(&mut session, json!({"op":"undo"}))).clone();
    assert_eq!(undone["model"], opened["model"]);
}

#[test]
fn native_delete_composes_with_an_unsaved_copy_and_reparent() {
    let directory = temp_dir();
    let source = directory.join("source.cmo3");
    let saved = directory.join("composed.cmo3");
    let part = |id: &str| format!("<CPartSource xs.id='{id}'><CPartGuid xs.n='guid' uuid='{id}-guid'/><CPartId xs.n='id' idstr='{id}'/>\
        <CPartGuid xs.n='parentGuid' uuid='part-guid'/><carray_list xs.n='_childGuids' count='0'/>\
        <carray_list xs.n='keyforms' count='0'/></CPartSource>");
    let xml = native_artmesh_xml("<f xs.n='opacity'>1</f>")
        .replace("<CPartId xs.n='id' idstr='root'/>", "<CPartId xs.n='id' idstr='root'/><carray_list xs.n='_childGuids' count='3'>\
            <CArtMeshGuid uuid='mesh-guid'/><CPartGuid uuid='arm-guid'/><CPartGuid uuid='leg-guid'/></carray_list>")
        .replace("<CPartSourceSet xs.n='partSourceSet'><carray_list xs.n='_sources' count='1'><CPartSource xs.ref='part'/>",
            "<CPartSourceSet xs.n='partSourceSet'><carray_list xs.n='_sources' count='3'><CPartSource xs.ref='part'/>\
            <CPartSource xs.ref='arm'/><CPartSource xs.ref='leg'/>")
        .replace("<GTexture2D xs.id='texture'>", &format!("{}{}<GTexture2D xs.id='texture'>", part("arm"), part("leg")));
    fs::write(&source, authoring_bytes(&xml)).unwrap();
    let mut session = Session::new();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    let copied = result(&request(&mut session, json!({"op":"live2d.duplicate","guid":"mesh-guid","id":"MeshCopy",
        "expectedRevision":opened["revision"]}))).clone();
    let copy = copied["guid"].as_str().unwrap().to_owned();
    let moved = result(&request(&mut session, json!({"op":"live2d.reparent","guid":"mesh-guid","parent":"arm-guid",
        "expectedRevision":copied["revision"]}))).clone();
    // Both the copy and the move are unsaved; deleting the other Part must not wait for a save.
    let deleted = result(&request(&mut session, json!({"op":"live2d.delete","guid":"leg-guid",
        "expectedRevision":moved["revision"]}))).clone();
    let sources = deleted["model"]["sources"].as_array().unwrap();
    assert!(sources.iter().all(|source| source["guid"] != "leg-guid"));
    let root = sources.iter().find(|source| source["guid"] == "part-guid").unwrap();
    assert_eq!(root["data"]["childGuids"], json!(["arm-guid", copy]));
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let reopened = result(&request(&mut Session::new(), json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], deleted["model"]);
    result(&request(&mut session, json!({"op":"undo"})));
    result(&request(&mut session, json!({"op":"undo"})));
    let undone = result(&request(&mut session, json!({"op":"undo"}))).clone();
    assert_eq!(undone["model"], opened["model"]);
}

#[test]
fn native_keys_are_added_and_deleted_saved_reopened_and_undone() {
    let directory = temp_dir();
    let source = directory.join("source.cmo3");
    let saved = directory.join("keyed.cmo3");
    fs::write(&source, native_morph_artmesh_bytes()).unwrap();
    let mut session = Session::new();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    let key = |op: &str, key: f64, revision: &Value| json!({"op":op,"sourceGuid":"mesh-guid",
        "parameterGuid":"parameter-guid","key":key,"expectedRevision":revision});
    for (bad, why) in [(2.0, "range"), (1.0, "already")] {
        let refused = request(&mut session, key("live2d.keyform.add", bad, &opened["revision"]));
        assert!(refused["message"].as_str().unwrap().contains(why), "{refused}");
    }
    let added = result(&request(&mut session, key("live2d.keyform.add", 0.0, &opened["revision"]))).clone();
    let mesh = &added["model"]["sources"][0];
    assert_eq!(mesh["grid"]["axes"][0]["keys"], json!([-1.0, 0.0, 1.0]));
    let cells = mesh["grid"]["cells"].as_array().unwrap();
    assert_eq!(cells.iter().map(|cell| cell["indices"][0].clone()).collect::<Vec<_>>(), [json!(0), json!(2), json!(1)]);
    let middle = mesh["forms"].as_array().unwrap().iter().find(|form| form["guid"] == cells[2]["formGuid"]).unwrap();
    assert_eq!(middle["data"]["positions"], json!([1.0, 2.0, 16.5, 22.0, 5.0, 6.0]), "halfway between the neighbours");
    let deleted = result(&request(&mut session, key("live2d.keyform.delete", -1.0, &added["revision"]))).clone();
    assert_eq!(deleted["model"]["sources"][0]["grid"]["axes"][0]["keys"], json!([0.0, 1.0]));
    assert_eq!(deleted["model"]["sources"][0]["forms"].as_array().unwrap().len(), 2);
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let reopened = result(&request(&mut Session::new(), json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], deleted["model"]);
    result(&request(&mut session, json!({"op":"undo"})));
    let undone = result(&request(&mut session, json!({"op":"undo"}))).clone();
    assert_eq!(undone["model"], opened["model"]);
}

fn art_path_point(guid: &str, x: f64) -> String {
    format!("<CArtPathPoint><CArtPathPointGuid xs.n='ctrlPtId' uuid='{guid}'/>\
        <CSplineCurvePoint xs.n='curvePointPosition'>\
        <GVector2 xs.n='point'><f xs.n='x'>{x}</f><f xs.n='y'>2</f></GVector2>\
        <GVector2 xs.n='startVelocity'><f xs.n='x'>0.5</f><f xs.n='y'>-0.5</f></GVector2>\
        <GVector2 xs.n='endVelocity'><f xs.n='x'>0.25</f><f xs.n='y'>0.75</f></GVector2></CSplineCurvePoint>\
        <b xs.n='isCorner'>false</b><f xs.n='colorRed'>1</f><f xs.n='colorGreen'>0.5</f><f xs.n='colorBlue'>0.25</f>\
        <f xs.n='colorAlpha'>1</f><f xs.n='opacity'>0.8</f><f xs.n='width'>3</f></CArtPathPoint>")
}

/// The native ArtMesh fixture with an ArtPath of two control points, point-a and point-b, in one keyform.
fn native_art_path_xml() -> String {
    let path = format!("<CArtPathSource xs.id='path'><ACDrawableSource xs.n='super'>\
        <CDrawableGuid xs.n='guid' uuid='path-guid'/>\
        <CDrawableId xs.n='id' idstr='path'/><CPartGuid xs.n='parentGuid' uuid='part-guid'/></ACDrawableSource>\
        <CArtPathBrushGuid xs.n='brushGuid' uuid='brush-guid'/><LineAlgorithm xs.n='lineAlgorithm' v='LCNS'/>\
        <LineAlignment xs.n='lineAlignment' v='CENTER'/><b xs.n='isClosed'>false</b><i xs.n='divNum'>20</i>\
        <carray_list xs.n='keyforms' count='1'><CArtPathForm><ACDrawableForm xs.n='super'><ACForm xs.n='super'>\
        <CFormGuid xs.n='guid' uuid='path-form'/><CArtPathSource xs.n='_source' xs.ref='path'/></ACForm>\
        <CoordType xs.n='coordType'><s xs.n='coordName'>Canvas</s></CoordType></ACDrawableForm>\
        <carray_list xs.n='positions' count='2'>{}{}</carray_list></CArtPathForm></carray_list></CArtPathSource>",
        art_path_point("point-a", 1.0), art_path_point("point-b", 5.0));
    native_artmesh_xml("<f xs.n='opacity'>0.75</f>")
        .replace("<carray_list xs.n='_sources' count='1'><CArtMeshSource xs.ref='mesh'/></carray_list>",
            "<carray_list xs.n='_sources' count='2'><CArtMeshSource xs.ref='mesh'/>\
            <CArtPathSource xs.ref='path'/></carray_list>")
        .replace("</CArtMeshSource><CPartSource xs.id='part'>",
            &format!("</CArtMeshSource>{path}<CPartSource xs.id='part'>"))
}

#[test]
fn native_artpath_order_mcp_history_and_unsaved_edits_compose() {
    let directory = temp_dir();
    let source = directory.join("source.cmo3");
    let saved = directory.join("order.cmo3");
    let undone_file = directory.join("undone.cmo3");
    let bytes = authoring_bytes(&native_artpath_order_xml());
    fs::write(&source, &bytes).unwrap();
    let mut session = Session::new();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    session.handle_mcp(&json!({"jsonrpc":"2.0","id":1,"method":"initialize"})).unwrap();
    let reply = session.handle_mcp(&json!({"jsonrpc":"2.0","id":2,"method":"tools/call",
        "params":{"name":"live2d_form_set","arguments":{"sourceGuid":"path-guid","formGuid":"path-form",
            "coordinateType":"Canvas","drawOrder":951,"screenColor":null,"unknown":17,
            "expectedRevision":opened["revision"]}}})).unwrap();
    assert_eq!(reply["result"]["isError"], false, "{reply}");
    let changed = session.snapshot();
    let mut expected = opened["model"].clone();
    expected["sources"].as_array_mut().unwrap().iter_mut().find(|source| source["guid"] == "path-guid")
        .unwrap()["forms"][0]["drawOrder"] = json!(951);
    assert_eq!(changed["model"], expected);
    assert_eq!(changed["revision"].as_u64().unwrap(), opened["revision"].as_u64().unwrap() + 1);
    assert_eq!(changed["history"]["count"].as_u64().unwrap(), opened["history"]["count"].as_u64().unwrap() + 1);
    result(&request(&mut session, json!({"op":"live2d.form.set","sourceGuid":"path-guid","formGuid":"path-form",
        "coordinateType":"Canvas","drawOrder":951,"expectedRevision":changed["revision"]})));
    assert_eq!(session.snapshot(), changed);
    let resource = session.handle_mcp(&json!({"jsonrpc":"2.0","id":3,"method":"resources/read",
        "params":{"uri":"resource://vsoul/snapshot"}})).unwrap();
    assert_eq!(serde_json::from_str::<Value>(resource["result"]["contents"][0]["text"].as_str().unwrap()).unwrap(), changed);
    let undone = result(&request(&mut session, json!({"op":"undo"}))).clone();
    assert_eq!(undone["model"], opened["model"]);
    for mut args in [json!({"drawOrder":-1}), json!({"drawOrder":1001}), json!({"drawOrder":1.0}),
        json!({"drawOrder":"951"}), json!({"drawOrder":null}), json!({"drawOrder":true}),
        json!({"formGuid":"missing","drawOrder":951}), json!({"coordinateType":"DeformerLocal","drawOrder":951}),
        json!({"sourceGuid":"missing","drawOrder":951}), json!({"drawOrder":951,"multiplyColor":[0.5,1,1,1]}),
        json!({"drawOrder":951,"expectedRevision":opened["revision"]})] {
        args["op"] = json!("live2d.form.set");
        if args.get("sourceGuid").is_none() { args["sourceGuid"] = json!("path-guid"); }
        if args.get("formGuid").is_none() { args["formGuid"] = json!("path-form"); }
        if args.get("coordinateType").is_none() { args["coordinateType"] = json!("Canvas"); }
        if args.get("expectedRevision").is_none() { args["expectedRevision"] = undone["revision"].clone(); }
        let refused = request(&mut session, args);
        assert_eq!(refused["succeeded"], false, "{refused}");
        assert_eq!(session.snapshot(), undone);
    }
    result(&request(&mut session, json!({"op":"save","path":undone_file})));
    assert_eq!(fs::read(&undone_file).unwrap(), bytes);
    let redone = result(&request(&mut session, json!({"op":"redo"}))).clone();
    assert_eq!(redone["model"], changed["model"]);
    let point = result(&request(&mut session, json!({"op":"live2d.artpath.point.set","sourceGuid":"path-guid",
        "formGuid":"path-form","coordinateType":"Canvas","index":0,"width":4,
        "expectedRevision":redone["revision"]}))).clone();
    let added = result(&request(&mut session, json!({"op":"live2d.artpath.point.add","sourceGuid":"path-guid",
        "index":0,"position":[9,8],"expectedRevision":point["revision"]}))).clone();
    let settings = result(&request(&mut session, json!({"op":"live2d.source.set","guid":"path-guid","closed":true,
        "divisionCount":21,"expectedRevision":added["revision"]}))).clone();
    let copied = result(&request(&mut session, json!({"op":"live2d.duplicate","guid":"path-guid","id":"OrderCopy",
        "expectedRevision":settings["revision"]}))).clone();
    let copy = copied["model"]["sources"].as_array().unwrap().iter().find(|source| source["guid"] == copied["guid"]).unwrap();
    result(&request(&mut session, json!({"op":"live2d.form.set","sourceGuid":copy["guid"],"formGuid":copy["forms"][0]["guid"],
        "coordinateType":"Canvas","drawOrder":1000,"expectedRevision":copied["revision"]})));
    let final_state = session.snapshot();
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let reopened = result(&request(&mut Session::new(), json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], final_state["model"]);
    assert_eq!(fs::read(&source).unwrap(), bytes);
}

fn native_artpath_order_xml() -> String {
    native_art_path_xml().replace("<CArtPathForm><ACDrawableForm xs.n='super'>",
        "<CArtPathForm><ACDrawableForm xs.n='super'><i xs.n='drawOrder'>950</i>")
        .replace("<CPartId xs.n='id' idstr='root'/>",
            "<CPartId xs.n='id' idstr='root'/><carray_list xs.n='_childGuids' count='2'>\
            <CArtMeshGuid uuid='mesh-guid'/><CDrawableGuid uuid='path-guid'/></carray_list>")
}

fn native_artpath_opacity_xml() -> String {
    native_artpath_order_xml().replace("<i xs.n='drawOrder'>950</i>",
        "<i xs.n='drawOrder'>950</i><f xs.n='opacity'>1.0</f>")
}

fn native_artpath_inversion_xml() -> String {
    native_artpath_opacity_xml().replace("<CArtPathSource xs.id='path'><ACDrawableSource xs.n='super'>",
        "<CArtPathSource xs.id='path'><ACDrawableSource xs.n='super'>\
        <carray_list xs.n='clipGuidList' count='0'/><b xs.n='invertClippingMask'>true</b>")
}

#[test]
fn native_artpath_inversion_mcp_is_atomic_and_composes_with_unsaved_edits() {
    let directory = temp_dir();
    let source = directory.join("source.cmo3");
    let bytes = authoring_bytes(&native_artpath_inversion_xml());
    fs::write(&source, &bytes).unwrap();
    let mut session = Session::new();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    session.handle_mcp(&json!({"jsonrpc":"2.0","id":1,"method":"initialize"})).unwrap();
    let reply = session.handle_mcp(&json!({"jsonrpc":"2.0","id":2,"method":"tools/call",
        "params":{"name":"live2d_source_set","arguments":{"guid":"path-guid","invertClippingMask":false,
            "unknown":17,"expectedRevision":opened["revision"]}}})).unwrap();
    assert_eq!(reply["result"]["isError"], false, "{reply}");
    let changed = session.snapshot();
    let mut expected = opened["model"].clone();
    expected["sources"].as_array_mut().unwrap().iter_mut().find(|s| s["guid"] == "path-guid")
        .unwrap()["data"]["invertClippingMask"] = json!(false);
    assert_eq!(changed["model"], expected);
    assert_eq!(changed["revision"].as_u64().unwrap(), opened["revision"].as_u64().unwrap() + 1);
    assert_eq!(changed["history"]["count"].as_u64().unwrap(), opened["history"]["count"].as_u64().unwrap() + 1);
    result(&request(&mut session, json!({"op":"live2d.source.set","guid":"path-guid","invertClippingMask":false,
        "expectedRevision":changed["revision"]})));
    assert_eq!(session.snapshot(), changed);
    let resource = session.handle_mcp(&json!({"jsonrpc":"2.0","id":3,"method":"resources/read",
        "params":{"uri":"resource://vsoul/snapshot"}})).unwrap();
    assert_eq!(serde_json::from_str::<Value>(resource["result"]["contents"][0]["text"].as_str().unwrap()).unwrap(), changed);
    result(&request(&mut session, json!({"op":"undo"})));
    let undone = session.snapshot();
    for extra in [json!({"invertClippingMask":"false"}), json!({"invertClippingMask":null}),
        json!({"invertClippingMask":false,"divisionCount":-1}),
        json!({"invertClippingMask":false,"expectedRevision":opened["revision"]}),
        json!({"guid":"missing","invertClippingMask":false})] {
        let mut args = json!({"op":"live2d.source.set","guid":"path-guid","expectedRevision":undone["revision"]});
        args.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
        assert_eq!(request(&mut session,args)["succeeded"], false);
        assert_eq!(session.snapshot(),undone);
    }
    let undo_file = directory.join("undone.cmo3");
    result(&request(&mut session,json!({"op":"save","path":undo_file})));
    assert_eq!(fs::read(undo_file).unwrap(),bytes);
    assert_eq!(result(&request(&mut session,json!({"op":"redo"})))["model"],changed["model"]);
    let state = session.snapshot();
    let mixed = result(&request(&mut session,json!({"op":"live2d.source.set","guid":"path-guid",
        "invertClippingMask":true,"closed":true,"divisionCount":21,"clipGuids":["mesh-guid"],
        "expectedRevision":state["revision"]}))).clone();
    assert_eq!(mixed["history"]["count"].as_u64().unwrap(),state["history"]["count"].as_u64().unwrap()+1);
    let copied = result(&request(&mut session,json!({"op":"live2d.duplicate","guid":"path-guid","id":"InversionCopy",
        "expectedRevision":mixed["revision"]}))).clone();
    let state = result(&request(&mut session,json!({"op":"live2d.source.set","guid":copied["guid"],
        "invertClippingMask":false,"expectedRevision":copied["revision"]}))).clone();
    let saved = directory.join("composed.cmo3");
    result(&request(&mut session,json!({"op":"save","path":saved})));
    let reopened = result(&request(&mut Session::new(),json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"],state["model"]);
    assert_eq!(fs::read(source).unwrap(),bytes);
}

#[test]
fn native_artpath_inversion_storage_refusal_preserves_redo() {
    for stored in ["true<![CDATA[]]>","&#116;rue","true<!--keep-->"] {
        let source = temp_dir().join("source.cmo3");
        fs::write(&source,authoring_bytes(&native_artpath_inversion_xml().replace(
            "<b xs.n='invertClippingMask'>true</b>",&format!("<b xs.n='invertClippingMask'>{stored}</b>")))).unwrap();
        let mut session = Session::new();
        let opened = result(&request(&mut session,json!({"op":"open","path":source}))).clone();
        let changed = result(&request(&mut session,json!({"op":"live2d.source.set","guid":"path-guid","closed":true,
            "expectedRevision":opened["revision"]}))).clone();
        result(&request(&mut session,json!({"op":"undo"})));
        let before = session.snapshot();
        assert_eq!(request(&mut session,json!({"op":"live2d.source.set","guid":"path-guid","invertClippingMask":false,
            "closed":true,"expectedRevision":before["revision"]}))["succeeded"],false);
        assert_eq!(session.snapshot(),before);
        assert_eq!(result(&request(&mut session,json!({"op":"redo"})))["model"],changed["model"]);
    }
}

#[test]
fn native_artpath_opacity_mcp_history_and_unsaved_edits_compose() {
    let directory = temp_dir();
    let source = directory.join("source.cmo3");
    let saved = directory.join("opacity.cmo3");
    let undone_file = directory.join("undone.cmo3");
    let bytes = authoring_bytes(&native_artpath_opacity_xml());
    fs::write(&source, &bytes).unwrap();
    let mut session = Session::new();
    let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
    session.handle_mcp(&json!({"jsonrpc":"2.0","id":1,"method":"initialize"})).unwrap();
    let reply = session.handle_mcp(&json!({"jsonrpc":"2.0","id":2,"method":"tools/call",
        "params":{"name":"live2d_form_set_opacity","arguments":{"sourceGuid":"path-guid","formGuid":"path-form",
            "coordinateType":"Canvas","opacity":0.5,"unknown":17,"expectedRevision":opened["revision"]}}})).unwrap();
    assert_eq!(reply["result"]["isError"], false, "{reply}");
    let changed = session.snapshot();
    let mut expected = opened["model"].clone();
    expected["sources"].as_array_mut().unwrap().iter_mut().find(|source| source["guid"] == "path-guid")
        .unwrap()["forms"][0]["opacity"] = json!(0.5);
    assert_eq!(changed["model"], expected);
    assert_eq!(changed["revision"].as_u64().unwrap(), opened["revision"].as_u64().unwrap() + 1);
    assert_eq!(changed["history"]["count"].as_u64().unwrap(), opened["history"]["count"].as_u64().unwrap() + 1);
    result(&request(&mut session, json!({"op":"live2d.form.set_opacity","sourceGuid":"path-guid","formGuid":"path-form",
        "coordinateType":"Canvas","opacity":0.5,"expectedRevision":changed["revision"]})));
    assert_eq!(session.snapshot(), changed);
    let resource = session.handle_mcp(&json!({"jsonrpc":"2.0","id":3,"method":"resources/read",
        "params":{"uri":"resource://vsoul/snapshot"}})).unwrap();
    assert_eq!(serde_json::from_str::<Value>(resource["result"]["contents"][0]["text"].as_str().unwrap()).unwrap(), changed);
    let undone = result(&request(&mut session, json!({"op":"undo"}))).clone();
    for mut args in [json!({"opacity":1e300}), json!({"opacity":"0.5"}), json!({"opacity":null}), json!({"opacity":true}),
        json!({"formGuid":"missing","opacity":0.5}), json!({"coordinateType":"DeformerLocal","opacity":0.5}),
        json!({"sourceGuid":"missing","opacity":0.5}), json!({"opacity":0.5,"expectedRevision":opened["revision"]})] {
        args["op"] = json!("live2d.form.set_opacity");
        if args.get("sourceGuid").is_none() { args["sourceGuid"] = json!("path-guid"); }
        if args.get("formGuid").is_none() { args["formGuid"] = json!("path-form"); }
        if args.get("coordinateType").is_none() { args["coordinateType"] = json!("Canvas"); }
        if args.get("expectedRevision").is_none() { args["expectedRevision"] = undone["revision"].clone(); }
        assert_eq!(request(&mut session, args)["succeeded"], false);
        assert_eq!(session.snapshot(), undone);
    }
    result(&request(&mut session, json!({"op":"save","path":undone_file})));
    assert_eq!(fs::read(&undone_file).unwrap(), bytes);
    let redone = result(&request(&mut session, json!({"op":"redo"}))).clone();
    assert_eq!(redone["model"], changed["model"]);
    let mesh_opacity = result(&request(&mut session, json!({"op":"live2d.form.set_opacity","sourceGuid":"mesh-guid",
        "formGuid":"form-guid","coordinateType":"Canvas","opacity":0.25,
        "expectedRevision":redone["revision"]}))).clone();
    let mesh = result(&request(&mut session, json!({"op":"live2d.form.set_vertex","sourceGuid":"mesh-guid",
        "formGuid":"form-guid","coordinateType":"Canvas","vertexIndex":0,"position":[3,4],
        "expectedRevision":mesh_opacity["revision"]}))).clone();
    let point = result(&request(&mut session, json!({"op":"live2d.artpath.point.set","sourceGuid":"path-guid",
        "formGuid":"path-form","coordinateType":"Canvas","index":0,"width":4,
        "expectedRevision":mesh["revision"]}))).clone();
    let added = result(&request(&mut session, json!({"op":"live2d.artpath.point.add","sourceGuid":"path-guid",
        "index":0,"position":[9,8],"expectedRevision":point["revision"]}))).clone();
    let settings = result(&request(&mut session, json!({"op":"live2d.source.set","guid":"path-guid","closed":true,
        "divisionCount":21,"expectedRevision":added["revision"]}))).clone();
    let copied = result(&request(&mut session, json!({"op":"live2d.duplicate","guid":"path-guid","id":"OpacityCopy",
        "expectedRevision":settings["revision"]}))).clone();
    let copy = copied["model"]["sources"].as_array().unwrap().iter().find(|source| source["guid"] == copied["guid"]).unwrap();
    let copy_opacity = result(&request(&mut session, json!({"op":"live2d.form.set_opacity","sourceGuid":copy["guid"],
        "formGuid":copy["forms"][0]["guid"],"coordinateType":"Canvas","opacity":-0.25,
        "expectedRevision":copied["revision"]}))).clone();
    result(&request(&mut session, json!({"op":"live2d.form.set","sourceGuid":"path-guid","formGuid":"path-form",
        "coordinateType":"Canvas","drawOrder":951,"expectedRevision":copy_opacity["revision"]})));
    let final_state = session.snapshot();
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let reopened = result(&request(&mut Session::new(), json!({"op":"open","path":saved}))).clone();
    assert_eq!(reopened["model"], final_state["model"]);
    assert_eq!(fs::read(&source).unwrap(), bytes);
}

#[test]
fn native_artpath_opacity_batches_keep_one_undo_noops_and_atomic_refusals() {
    for (method, value, expected) in [("overwrite", 0.5, 0.5), ("overwrite", -1.25, -1.25),
        ("add", -0.2, 0.6000000000000001), ("add", 0.2, 1.0), ("add", 1e300, 1.0), ("add", -1e300, 0.0)] {
        let directory = temp_dir();
        let source = directory.join("source.cmo3");
        fs::write(&source, authoring_bytes(&native_artpath_opacity_xml())).unwrap();
        let mut session = Session::new();
        let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
        let path = json!({"sourceGuid":"path-guid","formGuid":"path-form","coordinateType":"Canvas"});
        let mesh = json!({"sourceGuid":"mesh-guid","formGuid":"form-guid","coordinateType":"Canvas"});
        let changed = result(&request(&mut session, json!({"op":"live2d.form.set_opacities","forms":[path,mesh,path],
            "opacity":value,"method":method,"expectedRevision":opened["revision"]}))).clone();
        let path_source = changed["model"]["sources"].as_array().unwrap().iter().find(|source| source["guid"] == "path-guid").unwrap();
        assert_eq!(path_source["forms"][0]["opacity"], json!(expected));
        assert_eq!(changed["history"]["count"].as_u64().unwrap(), opened["history"]["count"].as_u64().unwrap() + 1);
        if method == "overwrite" {
            result(&request(&mut session, json!({"op":"live2d.form.set_opacities","forms":[path,mesh,path],
                "opacity":value,"expectedRevision":changed["revision"]})));
            assert_eq!(session.snapshot(), changed);
        }
        let undone = result(&request(&mut session, json!({"op":"undo"}))).clone();
        assert_eq!(undone["model"], opened["model"]);
        for bad in [json!({"sourceGuid":"missing","formGuid":"path-form","coordinateType":"Canvas"}),
            json!({"sourceGuid":"path-guid","formGuid":"path-form","coordinateType":"Other"})] {
            assert_eq!(request(&mut session, json!({"op":"live2d.form.set_opacities","forms":[path,bad],
                "opacity":0.5,"expectedRevision":undone["revision"]}))["succeeded"], false);
            assert_eq!(session.snapshot(), undone);
        }
        let redone = result(&request(&mut session, json!({"op":"redo"}))).clone();
        assert_eq!(redone["model"], changed["model"]);
    }
}

#[test]
fn native_artpath_opacity_storage_refusals_preserve_single_and_batch_redo() {
    for stored in ["", "<f xs.n='opacity' xs.id='shared'>1.0</f>", "<f xs.n='opacity'>&#49;.0</f>",
        "<f xs.n='opacity'>1.0<![CDATA[]]></f>", "<f xs.n='opacity'>1.0<!--keep--></f>"] {
        let directory = temp_dir();
        let source = directory.join("source.cmo3");
        let bytes = authoring_bytes(&native_artpath_opacity_xml().replace("<f xs.n='opacity'>1.0</f>", stored));
        fs::write(&source, &bytes).unwrap();
        let mut session = Session::new();
        let opened = result(&request(&mut session, json!({"op":"open","path":source}))).clone();
        let edited = result(&request(&mut session, json!({"op":"live2d.artpath.point.set","sourceGuid":"path-guid",
            "formGuid":"path-form","coordinateType":"Canvas","index":0,"width":4,
            "expectedRevision":opened["revision"]}))).clone();
        result(&request(&mut session, json!({"op":"undo"})));
        let before = session.snapshot();
        for edit in [json!({"op":"live2d.form.set_opacity","sourceGuid":"path-guid","formGuid":"path-form",
            "coordinateType":"Canvas","opacity":0.5,"expectedRevision":before["revision"]}),
            json!({"op":"live2d.form.set_opacities","forms":[
                {"sourceGuid":"mesh-guid","formGuid":"form-guid","coordinateType":"Canvas"},
                {"sourceGuid":"path-guid","formGuid":"path-form","coordinateType":"Canvas"}],
                "opacity":0.5,"expectedRevision":before["revision"]})] {
            assert_eq!(request(&mut session, edit)["succeeded"], false);
            assert_eq!(session.snapshot(), before);
        }
        let redone = result(&request(&mut session, json!({"op":"redo"}))).clone();
        assert_eq!(redone["model"], edited["model"]);
        assert_eq!(fs::read(&source).unwrap(), bytes);
    }
}

