fn near(actual: &Value, expected: f64) -> bool {
    actual.as_f64().is_some_and(|actual| (actual - expected).abs() < 1e-9)
}

/// A 2 s linear curve from 2 to 6 bound to the X axis of parameter 17 (range 0..6, held at 0 without the motion).
fn faded_session(dir: &std::path::Path) -> Session {
    let source = dir.join("faded.inx");
    let mut model = model_with_unknown_data();
    model["param"][0]["min"] = json!([0,-1]);
    model["param"][0]["max"] = json!([6,1]);
    let motion = json!({"Version":3,"Meta":{"Duration":2,"Fps":30,"Loop":true,"CurveCount":1,"TotalSegmentCount":1,"TotalPointCount":2,"FadeInTime":1.0},
        "Curves":[{"Target":"Parameter","Id":"Linear","Segments":[0,2,0,2,6]}]});
    model["live2d"] = json!({"motions":{"Fade":motion}});
    fs::write(&source, inp(&model, &texture_extension_tail())).unwrap();
    let mut session = Session::new();
    result(&request(&mut session, json!({"op":"open","path":source})));
    result(&request(&mut session, json!({"op":"value.set","id":17,"value":[0,0.25]})));
    let bindings = json!([{"id":"Linear","parameter":17,"axis":0}]);
    result(&request(&mut session, json!({"op":"motion3.bind","name":"Fade","bindings":bindings})));
    session
}

fn x17(session: &Session) -> Value {
    session.snapshot()["values"]["17"][0].clone()
}

#[test]
fn motion3_fades_weight_parameter_curves_only_when_playback_asks_for_them() {
    let dir = temp_dir();
    let mut session = faded_session(&dir);
    // Without fades the curve applies in full, as before.
    result(&request(&mut session, json!({"op":"motion3.seek","name":"Fade","time":0.5})));
    assert_eq!(x17(&session), 3.0);
    assert!(session.snapshot()["motion3"].get("fade").is_none());
    // With fades playback starts at the seek: weight 0, so the value without the motion.
    result(&request(&mut session, json!({"op":"motion3.seek","name":"Fade","time":0.5,"fades":true})));
    assert_eq!(x17(&session), 0.0);
    // A quarter of the 1 s fade-in played: the sine ease, not a linear ramp (raw 3.5 at t=0.75).
    result(&request(&mut session, json!({"op":"motion3.advance","dt":0.25})));
    let quarter = 0.5 - 0.5 * (std::f64::consts::PI / 4.0).cos();
    assert!(near(&x17(&session), 3.5 * quarter), "{}", x17(&session));
    // Half the fade-in played: the ease is at one half (raw 4 at t=1).
    result(&request(&mut session, json!({"op":"motion3.advance","dt":0.25})));
    assert!(near(&x17(&session), 2.0), "{}", x17(&session));
    assert_eq!(session.snapshot()["motion3"]["fade"], json!({"elapsed":0.5,"looping":false}));
    assert!(near(&session.snapshot()["motion3"]["applied"][0]["weight"], 0.5), "{}", session.snapshot()["motion3"]);
    // A curve's fade overrides the motion's: 0.25 s are played after 0.25 s.
    result(&request(&mut session, json!({"op":"motion3.fade.set","name":"Fade","curve":0,"fadeIn":0.25})));
    result(&request(&mut session, json!({"op":"motion3.seek","name":"Fade","time":1.0,"fades":true})));
    result(&request(&mut session, json!({"op":"motion3.advance","dt":0.25})));
    assert_eq!(x17(&session), 4.5);
    // A curve fade of zero is an instant change, not the motion's fade.
    result(&request(&mut session, json!({"op":"motion3.fade.set","name":"Fade","curve":0,"fadeIn":0})));
    result(&request(&mut session, json!({"op":"motion3.seek","name":"Fade","time":1.0,"fades":true})));
    assert_eq!(x17(&session), 4.0);
    // The motion's fade-out: 0.5 s before the end of a 1 s fade-out, half the curve (raw 5 at t=1.5).
    result(&request(&mut session, json!({"op":"motion3.fade.set","name":"Fade","fadeOut":1.0})));
    result(&request(&mut session, json!({"op":"motion3.seek","name":"Fade","time":0.75,"fades":true})));
    result(&request(&mut session, json!({"op":"motion3.advance","dt":0.75})));
    assert!(near(&x17(&session), 2.5), "{}", x17(&session));
    // A curve's fade-out overrides the motion's too: the last 0.5 s are a whole 0.5 s fade-out.
    result(&request(&mut session, json!({"op":"motion3.fade.set","name":"Fade","curve":0,"fadeOut":0.5})));
    result(&request(&mut session, json!({"op":"motion3.seek","name":"Fade","time":1.5,"fades":true})));
    assert_eq!(x17(&session), 5.0);
    // A looping clip never fades out (0.25 s before the end of a 0.5 s fade-out would halve the raw 5.5)...
    result(&request(&mut session, json!({"op":"motion3.fade.set","name":"Fade","curve":0,"fadeIn":null})));
    result(&request(&mut session, json!({"op":"motion3.seek","name":"Fade","time":0.75,"fades":true})));
    result(&request(&mut session, json!({"op":"motion3.advance","dt":1.0,"loop":true})));
    assert_eq!(x17(&session), 5.5);
    assert_eq!(session.snapshot()["motion3"]["fade"], json!({"elapsed":1.0,"looping":true}));
    // ...and the motion's 1 s fade-in does not start again at the wrap (raw 2.5 at t=0.25).
    result(&request(&mut session, json!({"op":"motion3.advance","dt":0.5,"loop":true})));
    assert_eq!(session.snapshot()["motion3"]["time"], 0.25);
    assert_eq!(x17(&session), 2.5);
    // motion3.pose stays raw.
    let pose = result(&request(&mut session, json!({"op":"motion3.pose","name":"Fade","time":1.5}))).clone();
    assert_eq!(pose["values"]["17"][0], 5.0);
    // The fade starts from the value the parameter holds, not from zero.
    result(&request(&mut session, json!({"op":"motion3.fade.set","name":"Fade","curve":0,"fadeIn":null,"fadeOut":null})));
    result(&request(&mut session, json!({"op":"value.set","id":17,"value":[2,0.25]})));
    result(&request(&mut session, json!({"op":"motion3.seek","name":"Fade","time":0.5,"fades":true})));
    assert_eq!(x17(&session), 2.0);
    result(&request(&mut session, json!({"op":"motion3.advance","dt":0.5})));
    assert!(near(&x17(&session), 3.0), "{}", x17(&session));
    fs::remove_dir_all(dir).unwrap();
}

#[test]
fn motion3_fade_set_edits_the_file_in_one_undo_step_and_refuses_bad_values() {
    let dir = temp_dir();
    let mut session = faded_session(&dir);
    let read = |session: &mut Session| result(&request(session, json!({"op":"motion3.read","name":"Fade"}))).clone();
    let before = read(&mut session);
    result(&request(&mut session, json!({"op":"motion3.fade.set","name":"Fade","fadeIn":null,"fadeOut":0.5})));
    let meta = read(&mut session)["Meta"].clone();
    assert!(meta.get("FadeInTime").is_none(), "{meta}");
    assert_eq!(meta["FadeOutTime"], 0.5);
    result(&request(&mut session, json!({"op":"motion3.fade.set","name":"Fade","curve":0,"fadeIn":0})));
    assert_eq!(read(&mut session)["Curves"][0]["FadeInTime"], 0.0);
    result(&request(&mut session, json!({"op":"undo"})));
    let undone = read(&mut session);
    assert!(undone["Curves"][0].get("FadeInTime").is_none(), "{undone}");
    assert_eq!(undone["Meta"]["FadeOutTime"], 0.5);
    result(&request(&mut session, json!({"op":"undo"})));
    assert_eq!(read(&mut session), before);
    for (body, message) in [
        (json!({"name":"Fade"}), "give fadeIn or fadeOut"),
        (json!({"name":"Fade","fadeIn":-1}), "fadeIn must be a nonnegative number"),
        (json!({"name":"Fade","fadeOut":"1"}), "fadeOut must be a nonnegative number"),
        (json!({"name":"Fade","curve":1,"fadeIn":1}), "curve must be the index of a curve"),
        (json!({"name":"Nope","fadeIn":1}), "was not found"),
    ] {
        let mut body = body;
        body["op"] = json!("motion3.fade.set");
        let response = request(&mut session, body.clone());
        assert_eq!(response["succeeded"], false, "{body}");
        assert!(response["message"].as_str().unwrap().contains(message), "{body}: {response}");
    }
    assert_eq!(read(&mut session), before);
    fs::remove_dir_all(dir).unwrap();
}

#[test]
fn native_motion3_fades_blend_from_the_runtime_value() {
    let directory = temp_dir();
    let source = directory.join("motion.cmo3");
    let motion_path = directory.join("fade.motion3.json");
    fs::write(&source, native_artmesh_bytes("<f xs.n='opacity'>0.75</f>")).unwrap();
    let motion = json!({"Version":3,"Meta":{"Duration":1,"Fps":30,"Loop":true,"CurveCount":1,"TotalSegmentCount":1,"TotalPointCount":2},
        "Curves":[{"Target":"Parameter","Id":"ParamTest","Segments":[0,-0.5,0,1,0.5]}]});
    fs::write(&motion_path, serde_json::to_vec(&motion).unwrap()).unwrap();
    let mut session = Session::new();
    result(&request(&mut session, json!({"op":"open", "path":source})));
    result(&request(&mut session, json!({"op":"live2d.parameter.set", "parameterId":"ParamTest", "value":0.25})));
    result(&request(&mut session, json!({"op":"motion3.import", "name":"clip", "path":motion_path})));
    let revision = session.snapshot()["revision"].clone();
    result(&request(&mut session, json!({"op":"motion3.fade.set", "name":"clip", "fadeIn":1.0})));
    assert_eq!(session.snapshot()["motion3Library"]["clip"]["Meta"]["FadeInTime"], 1.0);
    assert_eq!(session.snapshot()["revision"], revision, "a motion on a CMO3 lives in the session");
    result(&request(&mut session, json!({"op":"motion3.seek", "name":"clip", "time":0, "fades":true})));
    assert_eq!(session.snapshot()["values"]["ParamTest"], 0.25);
    // Half the fade-in: halfway from 0.25 to the raw 0 at t=0.5.
    result(&request(&mut session, json!({"op":"motion3.advance", "dt":0.5})));
    assert!(near(&session.snapshot()["values"]["ParamTest"], 0.125), "{}", session.snapshot()["values"]);
    assert!(near(&session.snapshot()["motion3"]["applied"][0]["weight"], 0.5), "{}", session.snapshot()["motion3"]);
    // An edit, its undo and a redo seek the preview again, on the same fade clock.
    let revision = session.snapshot()["revision"].clone();
    result(&request(&mut session, json!({"op":"live2d.form.set_opacity", "sourceGuid":"mesh-guid",
        "formGuid":"form-guid", "coordinateType":"Canvas", "opacity":0.25, "expectedRevision":revision})));
    for op in [None, Some("undo"), Some("redo")] {
        if let Some(op) = op {
            result(&request(&mut session, json!({"op":op})));
        }
        assert!(near(&session.snapshot()["values"]["ParamTest"], 0.125), "{op:?}: {}", session.snapshot()["values"]);
        assert_eq!(session.snapshot()["motion3"]["fade"], json!({"elapsed":0.5,"looping":false}), "{op:?}");
    }
    result(&request(&mut session, json!({"op":"motion3.seek", "name":"clip", "time":0.5})));
    assert_eq!(session.snapshot()["values"]["ParamTest"], 0.0);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn native_motion3_fade_seek_warms_physics_as_if_the_motion_starts_at_the_seek() {
    let directory = temp_dir();
    let source = directory.join("physics.cmo3");
    let physics_path = directory.join("hair.physics3.json");
    fs::write(&source, native_morph_artmesh_bytes()).unwrap();
    fs::write(&physics_path, serde_json::to_vec(&native_physics_fixture()).unwrap()).unwrap();
    let values = |segments: Value, fades: bool| {
        let motion_path = directory.join("clip.motion3.json");
        let motion = json!({"Version":3,"Meta":{"Duration":1,"Fps":30,"Loop":true,
            "CurveCount":1,"TotalSegmentCount":1,"TotalPointCount":2,"FadeInTime":0.5},
            "Curves":[{"Target":"Parameter","Id":"ParamTest","Segments":segments}]});
        fs::write(&motion_path, serde_json::to_vec(&motion).unwrap()).unwrap();
        let mut session = Session::new();
        result(&request(&mut session, json!({"op":"open","path":source})));
        result(&request(&mut session, json!({"op":"live2d.parameter.set","parameterId":"ParamTest","value":0.25})));
        result(&request(&mut session, json!({"op":"live2d.physics.attach","path":physics_path})));
        result(&request(&mut session, json!({"op":"motion3.import","name":"clip","path":motion_path})));
        result(&request(&mut session, json!({"op":"motion3.seek","name":"clip","time":0.75,"fades":fades})));
        session.snapshot()["values"].clone()
    };
    // Before the seek the fade-in holds the motion at zero, so physics sees only the value the parameter holds.
    let faded = values(json!([0,-1,0,1,1]), true);
    assert_eq!(faded, values(json!([0,0.25,0,1,0.25]), false));
    assert_ne!(faded, values(json!([0,-1,0,1,1]), false));
    // Attaching physics later replays the clip on the clock the preview had, so the fade-in of the last 0.5 s counts.
    let attached_late = |segments: Value, fades: bool| {
        let motion_path = directory.join("late.motion3.json");
        let motion = json!({"Version":3,"Meta":{"Duration":1,"Fps":30,"Loop":true,
            "CurveCount":1,"TotalSegmentCount":1,"TotalPointCount":2,"FadeInTime":0.5},
            "Curves":[{"Target":"Parameter","Id":"ParamTest","Segments":segments}]});
        fs::write(&motion_path, serde_json::to_vec(&motion).unwrap()).unwrap();
        let mut session = Session::new();
        result(&request(&mut session, json!({"op":"open","path":source})));
        result(&request(&mut session, json!({"op":"live2d.parameter.set","parameterId":"ParamTest","value":0.25})));
        result(&request(&mut session, json!({"op":"motion3.import","name":"clip","path":motion_path})));
        result(&request(&mut session, json!({"op":"motion3.seek","name":"clip","time":0.25,"fades":fades})));
        result(&request(&mut session, json!({"op":"motion3.advance","dt":0.5})));
        result(&request(&mut session, json!({"op":"live2d.physics.attach","path":physics_path})));
        let fade = session.snapshot()["motion3"]["fade"].clone();
        assert_eq!(fade, if fades { json!({"elapsed":0.5,"looping":false}) } else { Value::Null });
        session.snapshot()["values"].clone()
    };
    // The last 0.5 s ramp in from the base value: neither the base alone nor the clip at full weight.
    let late = attached_late(json!([0,-1,0,1,1]), true);
    assert_ne!(late, attached_late(json!([0,0.25,0,1,0.25]), true));
    assert_ne!(late, attached_late(json!([0,-1,0,1,1]), false));
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn native_expression_fades_in_as_playback_advances() {
    let directory = temp_dir();
    let source = directory.join("expression.cmo3");
    let motion_path = directory.join("hold.motion3.json");
    let physics_path = directory.join("hair.physics3.json");
    fs::write(&source, native_artmesh_bytes("<f xs.n='opacity'>0.75</f>")).unwrap();
    fs::write(&physics_path, serde_json::to_vec(&native_physics_fixture()).unwrap()).unwrap();
    let motion = json!({"Version":3,"Meta":{"Duration":10,"Fps":30,"Loop":true,
        "CurveCount":1,"TotalSegmentCount":1,"TotalPointCount":2},
        "Curves":[{"Target":"Parameter","Id":"ParamTest","Segments":[0,0.2,0,10,0.2]}]});
    fs::write(&motion_path, serde_json::to_vec(&motion).unwrap()).unwrap();
    let mut session = Session::new();
    result(&request(&mut session, json!({"op":"open","path":source})));
    result(&request(&mut session, json!({"op":"motion3.import","name":"hold","path":motion_path})));
    for (name, value, blend) in [("add", 0.5, "Add"), ("overwrite", 0.6, "Overwrite"), ("multiply", 3.0, "Multiply"),
        ("exact-overwrite", 0.9, "Overwrite"), ("exact-multiply", 0.1, "Multiply")] {
        let path = directory.join(format!("{name}.exp3.json"));
        fs::write(&path, serde_json::to_vec(&json!({"Type":"Live2D Expression","FadeInTime":1.0,
            "Parameters":[{"Id":"ParamTest","Value":value,"Blend":blend}]})).unwrap()).unwrap();
        result(&request(&mut session, json!({"op":"live2d.expression.import","name":name,"path":path})));
    }
    let value = |session: &Session| session.snapshot()["values"]["ParamTest"].as_f64().unwrap();
    let weight = |session: &Session| session.snapshot()["nativePlayback"]["expressionWeight"].clone();
    let halfway = |session: &mut Session, name: &str| {
        result(&request(session, json!({"op":"live2d.expression.apply","name":name,"fades":true})));
        result(&request(session, json!({"op":"motion3.seek","name":"hold","time":0})));
        result(&request(session, json!({"op":"motion3.advance","dt":0.5})));
        assert!((weight(session).as_f64().unwrap() - 0.5).abs() < 1e-9, "{name}");
        value(session)
    };
    // Applied with fades the expression starts at weight 0, then follows the sine ease.
    result(&request(&mut session, json!({"op":"live2d.expression.apply","name":"add","fades":true})));
    result(&request(&mut session, json!({"op":"motion3.seek","name":"hold","time":0})));
    assert_eq!(weight(&session), 0.0);
    assert!((value(&session) - 0.2).abs() < 1e-9, "{}", value(&session));
    result(&request(&mut session, json!({"op":"motion3.advance","dt":0.25})));
    assert!((value(&session) - 0.273223304703363).abs() < 1e-9, "{}", value(&session));
    let listed = result(&request(&mut session, json!({"op":"live2d.expression.list"}))).clone();
    assert_eq!(listed["expressions"][0], json!({"name":"add","fadeIn":1.0}));
    assert!((listed["weight"].as_f64().unwrap() - 0.146446609406726).abs() < 1e-9, "{listed}");
    result(&request(&mut session, json!({"op":"motion3.advance","dt":1.0})));
    assert_eq!(weight(&session), 1.0);
    assert!((value(&session) - 0.7).abs() < 1e-9, "{}", value(&session));
    // Each blend at half weight: Add 0.2+0.25, Overwrite halfway to 0.6, Multiply by 1+(3-1)/2.
    for (name, expected) in [("add", 0.45), ("overwrite", 0.4), ("multiply", 0.4)] {
        let actual = halfway(&mut session, name);
        assert!((actual - expected).abs() < 1e-9, "{name}: {actual}");
    }
    // Physics playback advances the fade too, and a zero step leaves it.
    result(&request(&mut session, json!({"op":"live2d.physics.attach","path":physics_path})));
    result(&request(&mut session, json!({"op":"live2d.expression.apply","name":"add","fades":true})));
    result(&request(&mut session, json!({"op":"live2d.physics.step","dt":0.0})));
    assert_eq!(request(&mut session, json!({"op":"live2d.physics.step","dt":-0.5}))["succeeded"], false);
    assert_eq!(weight(&session), 0.0);
    result(&request(&mut session, json!({"op":"live2d.physics.step","dt":0.5})));
    assert!((weight(&session).as_f64().unwrap() - 0.5).abs() < 1e-9, "{}", weight(&session));
    // Without fades it applies at full weight, and reset clears the weight.
    result(&request(&mut session, json!({"op":"live2d.expression.apply","name":"add"})));
    assert_eq!(weight(&session), 1.0);
    result(&request(&mut session, json!({"op":"live2d.expression.reset"})));
    assert_eq!(weight(&session), Value::Null);
    // At full weight the values are exactly those of the blend without fades.
    for (name, expected) in [("exact-overwrite", 0.9), ("exact-multiply", 0.2 * 0.1)] {
        result(&request(&mut session, json!({"op":"live2d.expression.apply","name":name})));
        result(&request(&mut session, json!({"op":"motion3.seek","name":"hold","time":0})));
        assert_eq!(value(&session), expected, "{name}");
    }
    let bad = directory.join("bad.exp3.json");
    fs::write(&bad, br#"{"Type":"Live2D Expression","FadeInTime":"1","Parameters":[]}"#).unwrap();
    let refused = request(&mut session, json!({"op":"live2d.expression.import","name":"bad","path":bad}));
    assert!(refused["message"].as_str().unwrap().contains("FadeInTime must be a number"), "{refused}");
    let refused = request(&mut session, json!({"op":"live2d.expression.apply","name":"add","fades":1}));
    assert!(refused["message"].as_str().unwrap().contains("fades must be a boolean"), "{refused}");
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn native_physics_steps_on_the_expression_weight_after_the_step() {
    let directory = temp_dir();
    let source = directory.join("expression.cmo3");
    let motion_path = directory.join("hold.motion3.json");
    let physics_path = directory.join("hair.physics3.json");
    let expression = directory.join("add.exp3.json");
    fs::write(&source, native_artmesh_bytes("<f xs.n='opacity'>0.75</f>")).unwrap();
    fs::write(&physics_path, serde_json::to_vec(&native_physics_fixture()).unwrap()).unwrap();
    fs::write(&motion_path, serde_json::to_vec(&json!({"Version":3,"Meta":{"Duration":10,"Fps":30,"Loop":true,
        "CurveCount":1,"TotalSegmentCount":1,"TotalPointCount":2},
        "Curves":[{"Target":"Parameter","Id":"ParamTest","Segments":[0,0.2,0,10,0.2]}]})).unwrap()).unwrap();
    fs::write(&expression, br#"{"Type":"Live2D Expression","FadeInTime":1.0,
        "Parameters":[{"Id":"ParamTest","Value":0.5}]}"#).unwrap();
    // A fade that ends within the step steps physics as the expression at full weight does.
    let physics = |fades: bool, step: &Value| {
        let mut session = Session::new();
        result(&request(&mut session, json!({"op":"open","path":source})));
        result(&request(&mut session, json!({"op":"motion3.import","name":"hold","path":motion_path})));
        result(&request(&mut session, json!({"op":"live2d.expression.import","name":"add","path":expression})));
        result(&request(&mut session, json!({"op":"live2d.physics.attach","path":physics_path})));
        result(&request(&mut session, json!({"op":"motion3.seek","name":"hold","time":0})));
        result(&request(&mut session, json!({"op":"live2d.expression.apply","name":"add","fades":fades})));
        result(&request(&mut session, step.clone()));
        session.snapshot()["nativePhysics"].clone()
    };
    for step in [json!({"op":"motion3.advance","dt":1.0}), json!({"op":"live2d.physics.step","dt":1.0})] {
        assert_eq!(physics(true, &step), physics(false, &step), "{step}");
    }
    fs::remove_dir_all(directory).unwrap();
}

const CAN3_KEY_EDITOR_XML: &str = include_str!("fixtures/can3-key-editor.xml");

fn can3_key_edit(session: &Session, op: &str, fields: Value) -> Value {
    let mut call = json!({"op":op, "sceneGuid":"scene-guid", "trackGuid":"track-guid",
        "curveId":"live2dParam_ParamTest",
        "expectedRevision":session.snapshot()["revision"]});
    for (key, value) in fields.as_object().unwrap() {
        call[key] = value.clone();
    }
    call
}

fn can3_curve(session: &Session) -> Value {
    session.snapshot()["model"]["scenes"][0]["tracks"][0]["parameterCurves"][0].clone()
}

fn can3_frames(session: &Session) -> Vec<i64> {
    can3_curve(session)["points"]
        .as_array()
        .unwrap()
        .iter()
        .map(|point| point["anchor"]["frame"].as_i64().unwrap())
        .collect()
}

const CAN3_CURVE_EDITOR_XML: &str = include_str!("fixtures/can3-curve-editor.xml");

fn curve_cmo3(directory: &PathBuf) -> PathBuf {
    let cmo3 = directory.join("source.cmo3");
    let xml = native_artmesh_xml("").replace(
        "<carray_list xs.n='_sources' count='1'><CParameterSource>",
        "<carray_list xs.n='_sources' count='2'><CParameterSource>\
         <CParameterGuid xs.n='guid' uuid='new-parameter-guid'/><CParameterId xs.n='id' idstr='ParamNew'/>\
         <f xs.n='minValue'>-2</f><f xs.n='maxValue'>2</f><f xs.n='defaultValue'>0.25</f></CParameterSource>\
         <CParameterSource>",
    );
    fs::write(&cmo3, authoring_bytes(&xml)).unwrap();
    cmo3
}

fn curve_add(session: &Session, cmo3: &PathBuf, parameter_id: &str, track_guid: &str) -> Value {
    json!({"op":"live2d.animation.curve.add","sceneGuid":"scene-guid","trackGuid":track_guid,
        "modelPath":cmo3,"parameterId":parameter_id,
        "expectedRevision":session.snapshot()["revision"]})
}

fn curve_delete(session: &Session, curve_id: &str, track_guid: &str) -> Value {
    json!({"op":"live2d.animation.curve.delete","sceneGuid":"scene-guid","trackGuid":track_guid,
        "curveId":curve_id,"expectedRevision":session.snapshot()["revision"]})
}

fn curve_ids(session: &Session, track: usize) -> Vec<String> {
    session.snapshot()["model"]["scenes"][0]["tracks"][track]["parameterCurves"]
        .as_array().unwrap().iter().map(|c| c["id"].as_str().unwrap().to_owned()).collect()
}

fn can3_key_fixture_session(directory: &PathBuf, xml: &str) -> (Session, PathBuf) {
    let source = directory.join("keys.can3");
    fs::write(&source, authoring_bytes(xml)).unwrap();
    let mut session = Session::new();
    result(&request(&mut session, json!({"op":"open","path":source})));
    (session, source)
}

fn can3_broken_gap_xml() -> String {
    CAN3_KEY_EDITOR_XML
        .replacen(r#"<CCurveType v="LINEAR"/>"#, r#"<CCurveType v="SMOOTH"/>"#, 1)
        .replace(r#"<d xs.n="posF">3</d>"#, r#"<d xs.n="posF">11</d>"#)
}

const CAN3_PART_OPACITY_XML: &str = include_str!("fixtures/can3-part-opacity.xml");

fn can3_grouped_native_track_xml() -> String {
    let mut xml = CAN3_PART_OPACITY_XML.to_owned();
    let start = xml.find(r#"<CMvTrack_Live2DModel_Source xs.id="track">"#).unwrap();
    let end = start + xml[start..].find("</CMvTrack_Live2DModel_Source>").unwrap()
        + "</CMvTrack_Live2DModel_Source>".len();
    xml.replace_range(start..end, r#"<CMvTrack_Live2DModel_Source xs.id="track">
      <ICMvTrack_Linked xs.n="super"><ICMvTrack_Source xs.n="super">
        <CTrackGuid xs.n="guid" xs.ref="track-guid-storage"/><s xs.n="name">Track</s>
        <i xs.n="start">0</i><i xs.n="internalOffset">0</i><i xs.n="duration">120</i>
        <CSceneSource xs.n="_sceneSource" xs.ref="scene"/>
        <CTrackGuid xs.n="parentGuid" xs.ref="group-guid-storage"/>
        <CVisualHandler xs.n="visualHandler"><CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/></CVisualHandler>
        <CSoundHandler xs.n="soundHandler"><CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/></CSoundHandler>
        <CMvEffect_VisualDefault xs.n="visualEffect" xs.ref="visual-effect"/>
        <CMvEffectManager xs.n="effectManager"><array xs.n="effectList" count="5" type="ICMvEffect">
          <CMvEffect_VisualDefault xs.ref="visual-effect"/><CMvEffect_Live2DParameter xs.ref="parameter-effect"/>
          <CMvEffect_Live2DPartsVisible xs.ref="parts-effect"/><CMvEffect_LipSync xs.ref="lip-effect"/>
          <CMvEffect_EyeBlink xs.ref="eye-effect"/>
        </array></CMvEffectManager>
      </ICMvTrack_Source><CResourceGuid xs.n="_resourceGuid" xs.ref="resource-guid-storage"/></ICMvTrack_Linked>
      <CMvEffect_Live2DParameter xs.n="keyParamEffect" xs.ref="parameter-effect"/>
      <CMvEffect_Live2DPartsVisible xs.n="partsVisibleEffect" xs.ref="parts-effect"/>
      <CMvEffect_LipSync xs.n="lipSyncEffect" xs.ref="lip-effect"/>
      <CMvEffect_EyeBlink xs.n="eyeBlinkEffect" xs.ref="eye-effect"/>
      <FormAnimationSet xs.n="formAnimationSet"><hash_map xs.n="formMapOnGlobal" count="0"/>
        <hash_map xs.n="formMapOnLocal" count="0"/><CMvTrack_Live2DModel_Source xs.n="trackSource" xs.ref="track"/>
      </FormAnimationSet>
    </CMvTrack_Live2DModel_Source>"#);
    xml = xml.replace(r#"<carray_list xs.n="_sources" count="1">"#,
        r#"<carray_list xs.n="_sources" count="2"><CMvTrack_Group_Source xs.ref="group"/>"#);
    xml = xml.replace("</CTrackSourceSet>",
        r#"</CTrackSourceSet><CMvTrack_Group_Source xs.n="rootTrack" xs.ref="group"/>"#);
    let mut definitions = r#"<CTrackGuid xs.id="track-guid-storage" uuid="track-guid"/>
      <CTrackGuid xs.id="group-guid-storage" uuid="group-guid"/>
      <CResourceGuid xs.id="resource-guid-storage" uuid="res-guid"/>
      <CParameterGroupGuid xs.id="parameter-group-guid-storage" uuid="parameter-group-guid"/>
      <CMvTrack_Group_Source xs.id="group"><ICMvTrack_Source xs.n="super">
        <CTrackGuid xs.n="guid" xs.ref="group-guid-storage"/>
        <CSceneSource xs.n="_sceneSource" xs.ref="scene"/>
      </ICMvTrack_Source><carray_list xs.n="_childTrackGuids" count="1"><CTrackGuid xs.ref="track-guid-storage"/></carray_list>
      </CMvTrack_Group_Source>
      <Opaque xs.id="keep-resource"><CResourceGuid xs.ref="resource-guid-storage"/></Opaque>
      <Opaque xs.id="keep-parameter-group"><CParameterGroupGuid xs.ref="parameter-group-guid-storage"/></Opaque>
      <CMvEffect_Live2DParameter xs.id="parameter-effect"><ICMvEffect xs.n="super">
        <CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/>
        <array xs.n="attrList" count="1" type="ICMvAttr"><CMvAttrF xs.ref="attr"/></array>
        <hash_map xs.n="attrMap" count="1"><entry><CAttrId xs.n="key" idstr="live2dParam_ParamTest"/>
          <CMvAttrF xs.n="value" xs.ref="attr"/></entry></hash_map>
      </ICMvEffect><carray_list xs.n="parameterGroupList" count="1"><CMvParameter_Group>
        <CParameterGroupGuid xs.n="guid" xs.ref="parameter-group-guid-storage"/>
        <CMvParameterGroupId xs.n="id" idstr="ParamGroupRoot"/>
      </CMvParameter_Group></carray_list></CMvEffect_Live2DParameter>"#.to_owned();
    for (tag, id, members) in [
        ("CMvEffect_VisualDefault", "visual-effect", "<CMvAttrPt xs.ref='xy-attr'/><CMvAttrI xs.ref='int-attr'/>"),
        ("CMvEffect_LipSync", "lip-effect", "<CMvAttrF xs.ref='fixed-attr'/>"), ("CMvEffect_EyeBlink", "eye-effect", ""),
    ] {
        let count = if id == "visual-effect" { 2 } else if id == "lip-effect" { 1 } else { 0 };
        definitions.push_str(&format!(r#"<{tag} xs.id="{id}"><ICMvEffect xs.n="super">
          <CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/>
          <array xs.n="attrList" count="{count}" type="ICMvAttr">{members}</array>
          <hash_map xs.n="attrMap" count="0"/></ICMvEffect></{tag}>"#));
    }
    for (tag, id, field, sequence) in [
        ("CMvAttrPt", "xy-attr", "valueDataXY", "CXY_TNSSequence"),
        ("CMvAttrI", "int-attr", "valueData", "CIntSequence"),
    ] {
        definitions.push_str(&format!(r#"<{tag} xs.id="{id}"><ICMvAttr xs.n="super">
          <CAttrId xs.n="id" idstr="{id}"/><CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/>
          </ICMvAttr><{sequence} xs.n="{field}"><array xs.n="points" count="0"/>
            <d xs.n="lastValue">NaN</d><{tag} xs.n="attr" xs.ref="{id}"/>
          </{sequence}></{tag}>"#));
    }
    definitions.push_str(r#"<CMvAttrF xs.id="fixed-attr"><ICMvAttr xs.n="super">
      <CAttrId xs.n="id" idstr="lipSyncScale"/><CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/>
      </ICMvAttr><CFixedSequence xs.n="valueData"><d xs.n="baseValue">2.0</d>
        <CMvAttrF xs.n="attr" xs.ref="fixed-attr"/></CFixedSequence></CMvAttrF>"#);
    xml.replace("</shared>", &format!("{definitions}</shared>"))
}

fn can3_form_track_xml() -> String {
    can3_grouped_native_track_xml()
        .replace(r#"<CParameterGroupGuid xs.n="guid" xs.ref="parameter-group-guid-storage"/>"#,
            r#"<CParameterGroupGuid xs.n="guid" uuid="parameter-group-guid"/>"#)
        .replace(r#"<CAnimation xs.id="animation">"#,
            r#"<CAnimation xs.id="animation"><CSceneSource xs.n="currentScene" xs.ref="scene"/>"#)
        .replace(r#"<array xs.n="effectList" count="5" type="ICMvEffect">"#,
            r#"<array xs.n="effectList" count="6" type="ICMvEffect"><CMvEffect_FormEdit xs.ref="form-effect"/>"#)
        .replace(r#"<FormAnimationSet xs.n="formAnimationSet">"#,
            r#"<CMvEffect_FormEdit xs.n="formEditEffect" xs.ref="form-effect"/><FormAnimationSet xs.n="formAnimationSet">"#)
        .replace(r#"<hash_map xs.n="formMapOnLocal" count="0"/>"#,
            r#"<hash_map xs.n="formMapOnLocal" count="1"><entry><CPartGuid xs.n="key" xs.ref="form-part"/>
            <KeyFormsForObject xs.n="value" xs.ref="form-keys"/></entry></hash_map>"#)
        .replace("</shared>", r#"
          <CMvEffect_FormEdit xs.id="form-effect"><ICMvEffect xs.n="super">
            <CEffectId xs.n="id" idstr="live2DFormEdit_"/>
            <CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/>
            <array xs.n="attrList" count="1"><CMvAttrF xs.ref="form-time"/></array>
            <hash_map xs.n="attrMap" count="1"><entry><CAttrId xs.n="key" idstr="form-time"/>
              <CMvAttrF xs.n="value" xs.ref="form-time"/></entry></hash_map>
          </ICMvEffect><carray_list xs.n="partList" count="1"><CMvPart_FormEdit>
            <CPartId xs.n="id" idstr="Part"/><CPartGuid xs.n="guid" uuid="part-id"/>
            <b xs.n="isShyMode">false</b><b xs.n="isExpanded">true</b>
          </CMvPart_FormEdit></carray_list></CMvEffect_FormEdit>
          <CPartGuid xs.id="form-part" uuid="part-id"/>
          <CFormGuid xs.id="form-guid" uuid="form-id"/>
          <KeyFormsForObject xs.id="form-keys"><array_list xs.n="framePosKeyformList" count="1">
              <FramePosAndForm xs.ref="form-frame"/></array_list>
            <hash_map xs.n="cached_framePosKeyformMap" count="1"><entry><i xs.n="key">4</i>
              <FramePosAndForm xs.n="value" xs.ref="form-frame"/></entry></hash_map>
            <CMvAttrF xs.n="attrTimeRemapping" xs.ref="form-time"/>
            <CDeformerGuid xs.n="parentDeformerGuid"/><s xs.n="parentDeformerTypeName"/>
            <CPartGuid xs.n="guid" xs.ref="form-part"/><s xs.n="nameForDebug">Part</s>
          </KeyFormsForObject>
          <CMvAttrF xs.id="form-time"><ICMvAttr xs.n="super"><CAttrId xs.n="id" idstr="form-time"/>
            <CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/></ICMvAttr>
            <CMutableSequence xs.n="valueData"><CMvAttrF xs.n="attr" xs.ref="form-time"/>
              <array xs.n="points" count="0"/><array xs.n="curveTypes" count="0"/>
              <d xs.n="baseValue">4</d></CMutableSequence>
            <KeyFormsForObject xs.n="linked_keyFormsForObject" xs.ref="form-keys"/>
          </CMvAttrF>
          <FramePosAndForm framePos="4" xs.id="form-frame">
            <CPartForm xs.n="targetForm"><ACForm xs.n="super"><CFormGuid xs.n="guid" xs.ref="form-guid"/>
              <s xs.n="notes">retained opaque payload</s></ACForm></CPartForm>
            <CPartForm xs.n="originalForm"><ACForm xs.n="super"><CFormGuid xs.n="guid" xs.ref="form-guid"/>
              <s xs.n="notes">original opaque payload</s></ACForm></CPartForm>
          </FramePosAndForm>
        </shared>"#)
}

#[test]
fn can3_form_track_delete_preserves_identities_and_native_history() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, &can3_form_track_xml());
    let original = fs::read(&source).unwrap();
    let call = can3_key_edit(&session, "live2d.animation.key.set", json!({"sceneGuid":"scene-guid",
        "trackGuid":"track-guid","curveId":"live2dParam_ParamTest","anchorFrame":0,"value":0.75}));
    result(&request(&mut session, call));
    let before = session.snapshot();
    let call = track_delete(&session, "scene-guid", "track-guid");
    result(&request(&mut session, call));
    assert!(track_guids(&session, 0).is_empty());
    let saved = directory.join("form-deleted.can3");
    result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
    let xml = saved_main_xml(&saved);
    for id in ["form-effect", "form-time", "form-keys", "form-frame"] {
        assert!(!xml.contains(&format!("xs.id=\"{id}\"")), "{id}");
    }
    for id in ["form-part", "form-guid"] { assert!(xml.contains(&format!("xs.id=\"{id}\""))); }
    result(&request(&mut session, json!({"op":"undo"})));
    assert_eq!(session.snapshot()["model"], before["model"]);
    result(&request(&mut session, json!({"op":"undo"})));
    let restored = directory.join("form-restored.can3");
    result(&request(&mut session, json!({"op":"save","path":restored,"mark_saved":false})));
    assert_eq!(fs::read(&restored).unwrap(), original);
    result(&request(&mut session, json!({"op":"redo"})));
    result(&request(&mut session, json!({"op":"redo"})));
    let expected = session.snapshot()["model"].clone();
    let saved = directory.join("form-redo.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_form_track_delete_refuses_ownership_and_cache_mismatches_atomically() {
    let xml = can3_form_track_xml();
    for xml in [
        xml.replace("</shared>", "<Opaque xs.ref='form-keys'/></shared>"),
        xml.replace("</shared>", "<Opaque xs.ref='form-frame'/></shared>"),
        xml.replace("<i xs.n=\"key\">4</i>", "<i xs.n=\"key\">5</i>"),
        xml.replace("<s xs.n=\"notes\">retained opaque payload</s>", "<CPartGuid xs.n='unknown' xs.ref='form-part'/>"),
        xml.replace("<CMvAttrF xs.n=\"attrTimeRemapping\" xs.ref=\"form-time\"/>",
            "<CMvAttrF xs.n='attrTimeRemapping' xs.ref='attr'/>"),
        xml.replace("<KeyFormsForObject xs.n=\"linked_keyFormsForObject\" xs.ref=\"form-keys\"/>",
            "<null xs.n='linked_keyFormsForObject'/>"),
        xml.replace("<hash_map xs.n=\"formMapOnGlobal\" count=\"0\"/>",
            "<hash_map xs.n='formMapOnGlobal' count='1'><entry/></hash_map>"),
        xml.replace("<CParameterGroupGuid xs.n=\"guid\" uuid=\"parameter-group-guid\"/>",
            "<CParameterGroupGuid xs.n='guid' uuid='parameter-group-guid'><Unknown/></CParameterGroupGuid>"),
    ] {
        let directory = temp_dir();
        let (mut session, source) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(&source).unwrap();
        let before = session.snapshot();
        let call = track_delete(&session, "scene-guid", "track-guid");
        assert_eq!(request(&mut session, call)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&source).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_form_track_deletion_composes_with_scene_deletion() {
    for xml in [can3_form_track_xml(), can3_inline_form_track_xml()] {
        let directory = temp_dir();
        let (mut session, _) = can3_key_fixture_session(&directory, &xml);
        let before = session.snapshot();
        let call = scene_delete(&session, "scene-guid");
        assert_eq!(request(&mut session, call)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
        result(&request(&mut session, json!({"op":"live2d.animation.scene.add", "name":"Replacement",
            "fps":24,"durationFrames":12,"expectedRevision":before["revision"]})));
        let saved = directory.join("with-replacement.can3");
        result(&request(&mut session, json!({"op":"save","path":saved})));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        let before = fs::read(&saved).unwrap();
        let call = scene_delete(&session, "scene-guid");
        result(&request(&mut session, call));
        result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
        let xml = saved_main_xml(&saved);
        assert!(!xml.contains("xs.id=\"form-keys\""));
        assert!(xml.contains("xs.id=\"form-part\""));
        assert!(!xml.contains("xs.id=\"form-dummy\""));
        result(&request(&mut session, json!({"op":"undo"})));
        result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
        assert_eq!(fs::read(&saved).unwrap(), before);
        fs::remove_dir_all(directory).unwrap();
    }
}

fn can3_inline_form_track_xml() -> String {
    let mut entries = String::new();
    let mut definitions = String::new();
    for index in 0..2 {
        entries.push_str(&format!(r#"<entry><CDrawableGuid xs.n="key" xs.ref="inline-guid-{index}"/>
          <KeyFormsForObject xs.n="value"><array_list xs.n="framePosKeyformList" count="0"/>
            <hash_map xs.n="cached_framePosKeyformMap" count="0"/>
            <CMvAttrF xs.n="attrTimeRemapping" xs.ref="inline-time-{index}"/>
            <null xs.n="parentDeformerGuid"/><null xs.n="parentDeformerTypeName"/>
            <CDrawableGuid xs.n="guid" xs.ref="inline-guid-{index}"/>
            <s xs.n="nameForDebug">Inline</s></KeyFormsForObject></entry>"#));
        definitions.push_str(&format!(r#"<CDrawableGuid xs.id="inline-guid-{index}" uuid="inline-{index}"/>
          <CMvAttrF xs.id="inline-time-{index}"><ICMvAttr xs.n="super">
            <CAttrId xs.n="id" idstr="inline-{index}"/>
            <CDrawableGuid xs.n="guid" xs.ref="inline-guid-{index}"/>
            <DummyTrackSource xs.n="track" xs.ref="form-dummy"/></ICMvAttr>
            <CMutableSequence xs.n="valueData"><CMvAttrF xs.n="attr" xs.ref="inline-time-{index}"/>
              <array xs.n="points" count="0"/><carray_list xs.n="curveTypes" count="0"/>
              <d xs.n="baseValue">0</d></CMutableSequence>
            <null xs.n="linked_keyFormsForObject"/></CMvAttrF>"#));
    }
    definitions.push_str(r#"<DummyTrackSource xs.id="form-dummy"><ICMvTrack_Source xs.n="super">
      <s xs.n="name">Dummy</s><CTrackGuid xs.n="guid" uuid="dummy-guid"/>
      <i xs.n="start">0</i><i xs.n="internalOffset">0</i><i xs.n="duration">20</i>
      <CVisualHandler xs.n="visualHandler"><DummyTrackSource xs.n="track" xs.ref="form-dummy"/></CVisualHandler>
      <CSoundHandler xs.n="soundHandler"><DummyTrackSource xs.n="track" xs.ref="form-dummy"/></CSoundHandler>
      <null xs.n="soundEffect"/><null xs.n="visualEffect"/><null xs.n="parentGuid"/>
      <null xs.n="_sceneSource"/><null xs.n="keys"/>
      <CMvEffectManager xs.n="effectManager"><array xs.n="effectList" count="0"/></CMvEffectManager>
      <hash_map xs.n="userData" count="0"/></ICMvTrack_Source></DummyTrackSource>
      <CMvTrack_Live2DModel_Source xs.id="borrowed-owner"><s xs.n="name">Retained owner</s></CMvTrack_Live2DModel_Source>
      <CMvAttrI xs.id="borrowed-step"><ICMvAttr xs.n="super"><CAttrId xs.n="id" idstr="frameStep"/>
        <CMvTrack_Live2DModel_Source xs.n="track" xs.ref="borrowed-owner"/></ICMvAttr>
        <CIntSequence xs.n="valueData"><CMvAttrI xs.n="attr" xs.ref="borrowed-step"/>
          <array xs.n="points" count="0"/><i xs.n="baseValue">1</i></CIntSequence>
      </CMvAttrI>"#);
    can3_form_track_xml()
        .replace(r#"<hash_map xs.n="cached_framePosKeyformMap" count="1"><entry><i xs.n="key">4</i>
              <FramePosAndForm xs.n="value" xs.ref="form-frame"/></entry></hash_map>"#,
            r#"<linked_map xs.n="cached_framePosKeyformMap" count="1"><entry><i xs.n="key">4</i>
              <FramePosAndForm xs.n="value" xs.ref="form-frame"/></entry></linked_map>"#)
        .replace(r#"<hash_map xs.n="formMapOnLocal" count="1">"#,
            &format!(r#"<hash_map xs.n="formMapOnLocal" count="3">{entries}"#))
        .replace(r#"<hash_map xs.n="attrMap" count="1"><entry><CAttrId xs.n="key" idstr="form-time"/>
              <CMvAttrF xs.n="value" xs.ref="form-time"/></entry></hash_map>"#,
            r#"<hash_map xs.n="attrMap" count="0"/>"#)
        .replace(r#"<CMvParameterGroupId xs.n="id" idstr="ParamGroupRoot"/>"#,
            r#"<CMvParameterGroupId xs.n="id" idstr="ParamGroupRoot"/><CMvAttrI xs.n="attrFrameStep" xs.ref="borrowed-step"/>"#)
        .replace("</shared>", &format!("{definitions}</shared>"))
}

#[test]
fn can3_inline_form_track_delete_preserves_borrowed_storage_and_history() {
    let directory = temp_dir();
    let xml = can3_inline_form_track_xml();
    let (mut session, source) = can3_key_fixture_session(&directory, &xml);
    let original = fs::read(&source).unwrap();
    let before = session.snapshot();
    let call = track_delete(&session, "scene-guid", "track-guid");
    result(&request(&mut session, call));
    let expected = session.snapshot()["model"].clone();
    let saved = directory.join("inline-deleted.can3");
    result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
    let after = saved_main_xml(&saved);
    for id in ["form-dummy", "inline-time-0", "inline-time-1", "form-keys", "form-time", "form-frame"] {
        assert!(!after.contains(&format!("xs.id=\"{id}\"")), "{id}");
    }
    let old = roxmltree::Document::parse(&xml).unwrap();
    let new = roxmltree::Document::parse(&after).unwrap();
    for id in ["borrowed-owner", "borrowed-step", "inline-guid-0", "inline-guid-1"] {
        let old = old.descendants().find(|n| n.attribute("xs.id") == Some(id)).unwrap();
        let new = new.descendants().find(|n| n.attribute("xs.id") == Some(id)).unwrap();
        assert_eq!(&xml[old.range()], &after[new.range()]);
    }
    result(&request(&mut session, json!({"op":"undo"})));
    assert_eq!(session.snapshot()["model"], before["model"]);
    let restored = directory.join("inline-restored.can3");
    result(&request(&mut session, json!({"op":"save","path":restored,"mark_saved":false})));
    assert_eq!(fs::read(&restored).unwrap(), original);
    result(&request(&mut session, json!({"op":"redo"})));
    let saved = directory.join("inline-redo.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    fs::remove_dir_all(directory).unwrap();
}

