#[test]
fn can3_inline_form_track_refuses_shared_dummies_and_cross_owner_edges() {
    let xml = can3_inline_form_track_xml();
    let mut bad_map = xml.clone();
    let map_range = {
        let document = roxmltree::Document::parse(&xml).unwrap();
        let effect = document.descendants().find(|n| n.attribute("xs.id") == Some("form-effect")).unwrap();
        effect.descendants().find(|n| n.attribute("xs.n") == Some("attrMap")).unwrap().range()
    };
    bad_map.replace_range(map_range, "<hash_map xs.n='attrMap' count='1'><entry><CAttrId xs.n='key' idstr='inline-0'/><CMvAttrF xs.n='value' xs.ref='inline-time-0'/></entry></hash_map>");
    for xml in [
        xml.replace("</shared>", "<Opaque xs.ref='form-dummy'/></shared>"),
        xml.replace("</shared>", "<Opaque xs.ref='inline-time-0'/></shared>"),
        xml.replace("<null xs.n=\"parentDeformerGuid\"/>", "<CDeformerGuid xs.n='parentDeformerGuid'/>") ,
        xml.replace("<null xs.n=\"linked_keyFormsForObject\"/>", "<KeyFormsForObject xs.n='linked_keyFormsForObject' xs.ref='form-keys'/>") ,
        xml.replace("<DummyTrackSource xs.n=\"track\" xs.ref=\"form-dummy\"/></ICMvAttr>",
            "<CMvTrack_Live2DModel_Source xs.n='track' xs.ref='track'/></ICMvAttr>"),
        xml.replace("<CMvTrack_Live2DModel_Source xs.n=\"track\" xs.ref=\"borrowed-owner\"/>",
            "<CMvTrack_Live2DModel_Source xs.n='track' xs.ref='track'/>"),
        xml.replace("<null xs.n=\"keys\"/>", "<array xs.n='keys' count='0'/>") ,
        xml.replace("<array_list xs.n=\"framePosKeyformList\" count=\"0\"/>",
            "<array_list xs.n='framePosKeyformList' count='1'><FramePosAndForm xs.ref='form-frame'/></array_list>"),
        xml.replace("<i xs.n=\"baseValue\">1</i>",
            "<i xs.n='baseValue'>1</i><CMvAttrF xs.n='future' xs.ref='form-time'/>"),
        bad_map,
    ] {
        let directory = temp_dir();
        let (mut session, source) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(&source).unwrap();
        let before = session.snapshot();
        let call = track_delete(&session, "scene-guid", "track-guid");
        assert_eq!(request(&mut session, call)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&source).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }
}

fn can3_grouped_native_scene_xml() -> String {
    let mut xml = can3_grouped_native_track_xml().replace(
        r#"<carray_list xs.n="_scenes" count="1"><CSceneSource xs.ref="scene"/></carray_list>"#,
        r#"<carray_list xs.n="_scenes" count="3"><CSceneSource xs.ref="scene"/>
          <CSceneSource xs.ref="scene-next"/><CSceneSource xs.ref="scene-last"/></carray_list>
          <CSceneSource xs.n="currentScene" xs.ref="scene"/>"#);
    let mut added = String::new();
    for id in ["scene-next", "scene-last"] {
        added.push_str(&format!(r#"<CSceneSource xs.id="{id}"><CGuid xs.n="guid" uuid="{id}-guid"/>
          <CAnimation xs.n="_animation" xs.ref="animation"/><s xs.n="sceneName">{id}</s>
          <CMovieInfo xs.n="movieInfo"><f xs.n="fps">60</f><i xs.n="duration">120</i></CMovieInfo>
          <CTrackSourceSet xs.n="trackSourceSet"><carray_list xs.n="_sources" count="0"/></CTrackSourceSet>
          </CSceneSource>"#));
    }
    xml = xml.replace("</shared>", &format!("{added}</shared>"));
    xml
}

#[test]
fn can3_deletes_grouped_current_scenes_before_the_first_save() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, &can3_grouped_native_scene_xml());
    let original = fs::read(&source).unwrap();
    let before = session.snapshot();
    let mut expected = before["model"].clone();
    expected["scenes"].as_array_mut().unwrap().remove(0);
    let call = scene_delete(&session, "scene-guid");
    result(&request(&mut session, call));
    assert_eq!(session.snapshot()["model"], expected);
    result(&request(&mut session, json!({"op":"undo"})));assert_eq!(session.snapshot()["model"], before["model"]);
    result(&request(&mut session, json!({"op":"redo"})));assert_eq!(session.snapshot()["model"], expected);
    let call = scene_delete(&session, "scene-next-guid");
    result(&request(&mut session, call));
    expected["scenes"].as_array_mut().unwrap().remove(0);
    assert_eq!(session.snapshot()["model"], expected);
    let saved = directory.join("scenes-deleted.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    let document = soul2d_core::caff::CaffDocument::parse(&fs::read(saved).unwrap()).unwrap();
    let xml = String::from_utf8(document.main_xml()).unwrap();
    let parsed = roxmltree::Document::parse(&xml).unwrap();
    let ids: std::collections::HashSet<_> = parsed.descendants().filter_map(|n| n.attribute("xs.id")).collect();
    for removed in ["scene", "scene-next", "group", "track", "track-guid-storage", "parameter-effect", "parts-effect",
        "visual-effect", "eye-effect", "lip-effect", "attr", "part-a", "part-b", "part-legacy", "xy-attr", "int-attr", "fixed-attr"] {
        assert!(!ids.contains(removed), "{removed}");
    }
    for retained in ["scene-last", "group-guid-storage", "resource", "resource-guid-storage", "keep-resource",
        "parameter-group-guid-storage", "keep-parameter-group"] { assert!(ids.contains(retained), "{retained}"); }
    let current = parsed.descendants().find(|n| n.attribute("xs.n") == Some("currentScene")).unwrap();
    assert_eq!(current.attribute("xs.ref"), Some("scene-last"));
    assert!(parsed.descendants().filter_map(|n| n.attribute("xs.ref")).all(|id| ids.contains(id)));
    assert_eq!(fs::read(source).unwrap(), original);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_deletes_an_empty_native_group_scene_after_its_track_was_saved() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, &can3_grouped_native_scene_xml());
    let original = fs::read(&source).unwrap();
    let revision = session.snapshot()["revision"].clone();
    result(&request(&mut session, json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid",
        "trackGuid":"track-guid","expectedRevision":revision})));
    let no_tracks = directory.join("no-tracks.can3");
    result(&request(&mut session, json!({"op":"save","path":no_tracks})));
    result(&request(&mut session, json!({"op":"open","path":no_tracks})));
    let mut expected = session.snapshot()["model"].clone();
    expected["scenes"].as_array_mut().unwrap().remove(0);
    let call = scene_delete(&session, "scene-guid");
    result(&request(&mut session, call));
    let saved = directory.join("empty-group-scene-deleted.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    let document = soul2d_core::caff::CaffDocument::parse(&fs::read(saved).unwrap()).unwrap();
    let xml = String::from_utf8(document.main_xml()).unwrap();
    let parsed = roxmltree::Document::parse(&xml).unwrap();
    let ids: std::collections::HashSet<_> = parsed.descendants().filter_map(|n| n.attribute("xs.id")).collect();
    assert!(!ids.contains("scene") && !ids.contains("group") && ids.contains("group-guid-storage"));
    assert!(parsed.descendants().filter_map(|n| n.attribute("xs.ref")).all(|id| ids.contains(id)));
    assert_eq!(fs::read(source).unwrap(), original);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_native_scene_selection_preserves_a_survivor_and_falls_back_to_the_previous_scene() {
    for (current, deleted, target) in [
        ("scene-next", "scene-guid", "scene-next"),
        ("scene-last", "scene-last-guid", "scene-next"),
    ] {
        let directory = temp_dir();
        let xml = can3_grouped_native_scene_xml().replace(
            r#"<CSceneSource xs.n="currentScene" xs.ref="scene"/>"#,
            &format!(r#"<CSceneSource xs.n="currentScene" xs.ref="{current}"/>"#));
        let (mut session, _) = can3_key_fixture_session(&directory, &xml);
        let mut expected = session.snapshot()["model"].clone();
        expected["scenes"].as_array_mut().unwrap().retain(|scene| scene["guid"] != deleted);
        let call = scene_delete(&session, deleted);
        result(&request(&mut session, call));
        let saved = directory.join("retargeted.can3");
        result(&request(&mut session, json!({"op":"save","path":saved})));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(session.snapshot()["model"], expected);
        let document = soul2d_core::caff::CaffDocument::parse(&fs::read(saved).unwrap()).unwrap();
        let xml = String::from_utf8(document.main_xml()).unwrap();
        let parsed = roxmltree::Document::parse(&xml).unwrap();
        let current = parsed.descendants().find(|n| n.attribute("xs.n") == Some("currentScene")).unwrap();
        assert_eq!(current.attribute("xs.ref"), Some(target));
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_native_scene_ownership_and_current_selection_refusals_are_atomic() {
    let base = can3_grouped_native_scene_xml();
    let mut cases = Vec::new();
    for (name, tag, id) in [
        ("scene", "CSceneSource", "scene"), ("group", "CMvTrack_Group_Source", "group"),
        ("attribute", "CMvAttrPt", "xy-attr"), ("track", "CMvTrack_Live2DModel_Source", "track"),
    ] {
        cases.push((name, base.replace("</shared>", &format!(r#"<Opaque><{tag} xs.ref="{id}"/></Opaque></shared>"#))));
    }
    cases.push(("unowned-child", base.replace(r#"<carray_list xs.n="_childTrackGuids" count="1">"#,
        r#"<carray_list xs.n="_childTrackGuids" count="2"><CTrackGuid xs.ref="unowned-child"/>"#)
        .replace("</shared>", r#"<CTrackGuid xs.id="unowned-child" uuid="unowned-child"/></shared>"#)));
    cases.push(("unknown-source", base.replace(r#"<carray_list xs.n="_sources" count="2">"#,
        r#"<carray_list xs.n="_sources" count="3"><UnknownSource xs.ref="unknown-source"/>"#)
        .replace("</shared>", r#"<UnknownSource xs.id="unknown-source"/></shared>"#)));
    cases.push(("nested-group-storage", base.replace(
        r#"<CMvTrack_Group_Source xs.id="group"><ICMvTrack_Source xs.n="super">"#,
        r#"<CMvTrack_Group_Source xs.id="group"><ICMvTrack_Source xs.n="super" xs.id="nested-group">"#)));
    cases.push(("root-track", base.replace(r#"xs.n="rootTrack" xs.ref="group""#,
        r#"xs.n="rootTrack" xs.ref="scene-next""#)));
    cases.push(("current-alias", base.replace(r#"xs.n="currentScene" xs.ref="scene""#,
        r#"xs.n="currentScene" xs.ref="scene-alias""#)
        .replace("</shared>", r#"<CSceneSource xs.id="scene-alias" xs.ref="scene"/></shared>"#)));
    cases.push(("current-attributes", base.replace(r#"xs.n="currentScene" xs.ref="scene""#,
        r#"xs.n="currentScene" xs.ref="scene" extra="1""#)));
    cases.push(("current-unlisted", base.replace(r#"xs.n="currentScene" xs.ref="scene""#,
        r#"xs.n="currentScene" xs.ref="unlisted-scene""#)
        .replace("</shared>", r#"<CSceneSource xs.id="unlisted-scene"/></shared>"#)));
    cases.push(("current-last-scene", can3_grouped_native_track_xml().replace(
        r#"<carray_list xs.n="_scenes" count="1"><CSceneSource xs.ref="scene"/></carray_list>"#,
        r#"<carray_list xs.n="_scenes" count="1"><CSceneSource xs.ref="scene"/></carray_list>
          <CSceneSource xs.n="currentScene" xs.ref="scene"/>"#)));
    for (name, xml) in cases {
        assert_ne!(xml, base, "{name}");
        let directory = temp_dir();
        let (mut session, source) = can3_key_fixture_session(&directory, &xml);
        let before = session.snapshot();
        let history = result(&request(&mut session, json!({"op":"history.summary"}))).clone();
        let original = fs::read(&source).unwrap();
        let call = scene_delete(&session, "scene-guid");
        let reply = request(&mut session, call);
        assert_eq!(reply["succeeded"], false, "{name}: {reply}");
        assert_eq!(session.snapshot(), before, "{name}");
        assert_eq!(result(&request(&mut session, json!({"op":"history.summary"}))), &history, "{name}");
        assert_eq!(fs::read(source).unwrap(), original, "{name}");
        fs::remove_dir_all(directory).unwrap();
    }
}

fn can3_visual_key_xml(id: &str, named: &str) -> String {
    include_str!("fixtures/can3-image-track.xml")
        .replace("idstr=\"opacity\"", &format!("idstr=\"{id}\""))
        .replace("<array xs.n=\"effectList\" count=\"1\">", "<array xs.n=\"effectList\" count=\"1\" type=\"ICMvEffect\">")
        .replace("<CMvEffect_VisualDefault xs.id=\"image-visual\">", &format!(
            "<CMvEffect_VisualDefault xs.id=\"image-visual\"><CMvAttrF xs.n=\"{named}\" xs.ref=\"image-opacity\"/>"))
        .replace(r#"<CMutableSequence xs.n="valueData"><CMvAttrF xs.n="attr" xs.ref="image-opacity"/><array xs.n="points" count="0"/><array xs.n="curveTypes" count="0"/></CMutableSequence>"#,
            r#"<CMutableSequence xs.n="valueData"><ACValueSequence xs.n="super"><CMvAttrF xs.n="attr" xs.ref="image-opacity"/><d xs.n="curMin">10.0</d><d xs.n="curMax">10.0</d><int-array xs.n="keyPts2" count="1">0</int-array><i xs.n="keyMin">0</i><i xs.n="keyMax">0</i><d xs.n="lastValue">10.0</d><i xs.n="lastPos">0</i><d xs.n="baseValue">1.0</d></ACValueSequence><array xs.n="points" count="1"><CBezierPt><CSeqPt xs.n="anchor"><i xs.n="pos">0</i><d xs.n="doubleValue">10.0</d><b xs.n="isCorner">false</b></CSeqPt><CBezierCtrlPt xs.n="prev"><i xs.n="pos">0</i><f xs.n="posF">0.0</f><d xs.n="doubleValue">10.0</d><b xs.n="isPosOptimized">false</b></CBezierCtrlPt><CBezierCtrlPt xs.n="next"><i xs.n="pos">0</i><f xs.n="posF">0.0</f><d xs.n="doubleValue">10.0</d><b xs.n="isPosOptimized">false</b></CBezierCtrlPt></CBezierPt></array><array xs.n="curveTypes" count="1"><CCurveType v="LINEAR"/></array></CMutableSequence>"#)
}

fn can3_point_xml(id: &str, named: &str, x: &str, y: &str) -> String {
    can3_visual_key_xml("opacity", "attrOpacity")
        .replace("idstr=\"xy\"", &format!("idstr=\"{id}\""))
        .replace("<CMvEffect_VisualDefault xs.id=\"image-visual\">", &format!(
            "<CMvEffect_VisualDefault xs.id=\"image-visual\"><CMvAttrPt xs.n=\"{named}\" xs.ref=\"image-xy\"/>"))
        .replace("<CXY_TNSSequence xs.n=\"valueDataXY\"><CMvAttrPt xs.n=\"attr\" xs.ref=\"image-xy\"/><array xs.n=\"points\" count=\"0\"/></CXY_TNSSequence>",
            &format!("<CXY_TNSSequence xs.n=\"valueDataXY\"><CMvAttrPt xs.n=\"attr\" xs.ref=\"image-xy\"/><array xs.n=\"points\" count=\"1\" type=\"CPtTNS\"><CPtTNS><GVector2 xs.n=\"super\"><f xs.n=\"x\">{x}</f><f xs.n=\"y\">{y}</f></GVector2><b xs.n=\"isCorner\">false</b><GVector2 xs.n=\"value\"><f xs.n=\"x\">{x}</f><f xs.n=\"y\">{y}</f></GVector2><i xs.n=\"pos\">-3</i></CPtTNS></array><GVector2 xs.n=\"basePt\"><f xs.n=\"x\">640.0</f><f xs.n=\"y\">360.0</f></GVector2></CXY_TNSSequence>"))
}

#[test]
fn can3_image_points_edit_both_coordinate_copies_and_keep_other_bytes() {
    for (id, named) in [("xy", "attrXY"), ("anchor", "attrAnchorXY")] {
        let directory = temp_dir();
        let xml = can3_point_xml(id, named, "10.0", "20.0");
        let (mut session, source) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(&source).unwrap();
        let before = session.snapshot();
        assert_eq!(before["model"]["scenes"][0]["imageTracks"][0]["pointChannels"],
            json!([{"id":id,"points":[{"frame":-3,"x":10.0,"y":20.0,"corner":false}]}]));
        let body = json!({"op":"live2d.animation.point.set","sceneGuid":"scene-guid","trackGuid":"image-track-guid",
            "curveId":id,"anchorFrame":-3,"x":0.1,"y":-25.0,"expectedRevision":before["revision"]});
        result(&request(&mut session, body));
        let expected = session.snapshot()["model"].clone();
        let saved = directory.join("points.can3");
        result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
        assert_eq!(saved_main_xml(&saved), xml.replace("<f xs.n=\"x\">10.0</f>", "<f xs.n=\"x\">0.1</f>")
            .replace("<f xs.n=\"y\">20.0</f>", "<f xs.n=\"y\">-25</f>"));
        result(&request(&mut session, json!({"op":"undo"})));
        let undone = directory.join("undone.can3");
        result(&request(&mut session, json!({"op":"save","path":undone,"mark_saved":false})));
        assert_eq!(fs::read(undone).unwrap(), original);
        result(&request(&mut session, json!({"op":"redo"})));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(session.snapshot()["model"], expected);
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_image_points_round_to_f32_and_preserve_equivalent_tokens() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory,
        &can3_point_xml("xy", "attrXY", "0.10000000149011612", "-0.0"));
    let original = fs::read(&source).unwrap();
    let before = session.snapshot();
    let body = json!({"op":"live2d.animation.point.set","sceneGuid":"scene-guid","trackGuid":"image-track-guid",
        "curveId":"xy","anchorFrame":-3,"x":0.1,"y":0.0,"expectedRevision":before["revision"]});
    result(&request(&mut session, body.clone()));
    assert_eq!(session.snapshot(), before);
    let saved = directory.join("unchanged.can3");
    result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
    assert_eq!(fs::read(saved).unwrap(), original);
    for (field, value) in [("x", json!(1e100)), ("y", Value::Null), ("curveId", json!("frameStep")),
        ("anchorFrame", json!(0)), ("expectedRevision", json!(999)), ("partOpacityMapKey", json!("unused"))] {
        let mut invalid = body.clone();
        invalid[field] = value;
        assert_eq!(request(&mut session, invalid)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
    }
    let mut changed = body;
    changed["x"] = json!(1.23456789123);
    result(&request(&mut session, changed));
    let rounded: f64 = (1.23456789123_f64 as f32).to_string().parse().unwrap();
    assert_eq!(session.snapshot()["model"]["scenes"][0]["imageTracks"][0]["pointChannels"][0]["points"][0]["x"], json!(rounded));
    fs::remove_dir_all(directory).unwrap();
}

