#[test]
fn can3_image_points_refuse_shared_or_inconsistent_storage_atomically() {
    let xml = can3_point_xml("xy", "attrXY", "10.0", "20.0");
    let start = xml.find("<CPtTNS>").unwrap();
    let end = start + xml[start..].find("</CPtTNS>").unwrap() + "</CPtTNS>".len();
    let point = &xml[start..end];
    let duplicate = xml.replace(point, &format!("{point}{point}"))
        .replace("count=\"1\" type=\"CPtTNS\"", "count=\"2\" type=\"CPtTNS\"");
    let start = xml.find("<hash_map xs.n=\"attrMap\"").unwrap();
    let end = start + xml[start..].find("</hash_map>").unwrap() + "</hash_map>".len();
    let empty = format!("{}<hash_map xs.n=\"attrMap\" count=\"0\" keyType=\"string\" />{}", &xml[..start], &xml[end..]);
    for malformed in [
        xml.replace("<CPtTNS>", "<CPtTNS xs.id=\"shared-point\">"),
        xml.replace("<GVector2 xs.n=\"value\">", "<GVector2 xs.n=\"value\" xs.id=\"shared-vector\">"),
        xml.replacen("<f xs.n=\"x\">10.0</f>", "<f xs.n=\"x\">11.0</f>", 1),
        xml.replacen("<f xs.n=\"x\">10.0</f>", "", 1),
        xml.replace("xs.n=\"attrXY\" xs.ref=\"image-xy\"", "xs.n=\"attrXY\" xs.ref=\"image-opacity\""),
        xml.replace("</shared>", "<CMvAttrPt xs.ref=\"image-xy\"/></shared>"),
        empty.replace("</shared>", "<CMvAttrPt xs.ref=\"image-xy\"/></shared>"),
        empty.replace("xs.n=\"attrMap\" count=\"0\"", "xs.n=\"attrMap\" count=\"1\""),
        empty.replace("xs.n=\"attrMap\" count=\"0\"", "xs.n=\"attrMap\""),
        empty.replace("xs.n=\"attrMap\" count=\"0\"", "xs.n=\"attrMap\" xs.id=\"shared-empty-map\" count=\"0\""),
        xml.replace("<entry><CAttrId xs.n=\"key\" idstr=\"xy\"/><CMvAttrPt xs.n=\"value\" xs.ref=\"image-xy\"/></entry>", "")
            .replace("xs.n=\"attrMap\" count=\"3\"", "xs.n=\"attrMap\" count=\"2\""),
        duplicate,
    ] {
        let directory = temp_dir();
        let (mut session, source) = can3_key_fixture_session(&directory, &malformed);
        let before = session.snapshot();
        let history = result(&request(&mut session, json!({"op":"history.summary"}))).clone();
        let original = fs::read(&source).unwrap();
        let body = json!({"op":"live2d.animation.point.set","sceneGuid":"scene-guid","trackGuid":"image-track-guid",
            "curveId":"xy","anchorFrame":-3,"x":30.0,"y":40.0,"expectedRevision":before["revision"]});
        assert_eq!(request(&mut session, body)["succeeded"], false, "{malformed}");
        assert_eq!(session.snapshot(), before);
        assert_eq!(*result(&request(&mut session, json!({"op":"history.summary"}))), history);
        assert_eq!(fs::read(source).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_image_points_and_scalar_edits_keep_copy_time_values() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, &can3_point_xml("xy", "attrXY", "10.0", "20.0"));
    let original = fs::read(source).unwrap();
    let set = |session: &mut Session, track: &str, x: f64| {
        let revision = session.snapshot()["revision"].clone();
        result(&request(session, json!({"op":"live2d.animation.point.set","sceneGuid":"scene-guid",
            "trackGuid":track,"curveId":"xy","anchorFrame":-3,"x":x,"y":20.0,"expectedRevision":revision}))).clone()
    };
    let copy = |session: &mut Session, track: &str| {
        let revision = session.snapshot()["revision"].clone();
        result(&request(session, json!({"op":"live2d.animation.track.duplicate","sceneGuid":"scene-guid",
            "trackGuid":track,"name":"Point copy","expectedRevision":revision})))["trackGuid"].as_str().unwrap().to_owned()
    };
    set(&mut session, "image-track-guid", 20.0);
    let revision = session.snapshot()["revision"].clone();
    result(&request(&mut session, json!({"op":"live2d.animation.key.set","sceneGuid":"scene-guid",
        "trackGuid":"image-track-guid","curveId":"opacity","anchorFrame":0,"value":11.0,"expectedRevision":revision})));
    let first = copy(&mut session, "image-track-guid");
    set(&mut session, "image-track-guid", 25.0);
    let second = copy(&mut session, &first);
    set(&mut session, &first, 30.0);
    let revision = session.snapshot()["revision"].clone();
    result(&request(&mut session, json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid",
        "trackGuid":"image-track-guid","expectedRevision":revision})));
    let expected = session.snapshot()["model"].clone();
    let tracks = expected["scenes"][0]["imageTracks"].as_array().unwrap();
    assert_eq!(tracks.len(), 2);
    for (guid, x) in [(&first, 30.0), (&second, 20.0)] {
        let track = tracks.iter().find(|track| track["guid"] == *guid).unwrap();
        assert_eq!(track["pointChannels"][0]["points"][0]["x"], x);
        assert_eq!(track["visualCurves"][0]["points"][0]["anchor"]["value"], 11.0);
    }
    for _ in 0..7 { result(&request(&mut session, json!({"op":"undo"}))); }
    let undone = directory.join("undone.can3");
    result(&request(&mut session, json!({"op":"save","path":undone,"mark_saved":false})));
    assert_eq!(fs::read(undone).unwrap(), original);
    for _ in 0..7 { result(&request(&mut session, json!({"op":"redo"}))); }
    let saved = directory.join("copies.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_image_scalar_keys_set_values_without_enabling_other_curve_edits() {
    for (id, named) in [("scalex", "attrScaleX"), ("scaley", "attrScaleY"), ("rotate", "attrRotate"),
        ("shear", "attrShear"), ("opacity", "attrOpacity"), ("artPathWidth", "attrArtPathWidth")] {
        let directory = temp_dir();
        let xml = can3_visual_key_xml(id, named);
        let (mut session, source) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(&source).unwrap();
        let before = session.snapshot();
        let call = |revision: Value| json!({"op":"live2d.animation.key.set","sceneGuid":"scene-guid",
            "trackGuid":"image-track-guid","curveId":id,"anchorFrame":0,"value":25.0,"expectedRevision":revision});
        let after = result(&request(&mut session, call(before["revision"].clone()))).clone();
        let mut expected = before["model"].clone();
        expected["scenes"][0]["imageTracks"][0]["visualCurves"][0]["points"][0]["anchor"]["value"] = json!(25.0);
        assert_eq!(after["model"], expected);
        let unchanged = session.snapshot();
        result(&request(&mut session, call(unchanged["revision"].clone())));
        assert_eq!(session.snapshot(), unchanged);
        for (op, extra) in [
            ("live2d.animation.handle.set", json!({"side":"next","value":26})),
            ("live2d.animation.curve_type.set", json!({"type":"BEZIER"})),
        ] {
            let mut request_body = call(unchanged["revision"].clone());
            request_body["op"] = json!(op);
            request_body.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
            assert_eq!(request(&mut session, request_body)["succeeded"], false);
            assert_eq!(session.snapshot(), unchanged);
        }
        result(&request(&mut session, json!({"op":"undo"})));
        let restored = directory.join("restored.can3");
        result(&request(&mut session, json!({"op":"save","path":restored,"mark_saved":false})));
        assert_eq!(fs::read(restored).unwrap(), original);
        result(&request(&mut session, json!({"op":"redo"})));
        let saved = directory.join("saved.can3");
        result(&request(&mut session, json!({"op":"save","path":saved})));
        let text = saved_main_xml(&saved);
        assert!(text.contains("<d xs.n=\"baseValue\">1.0</d>"));
        assert!(text.contains("<d xs.n=\"curMin\">25</d>"));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(session.snapshot()["model"], expected);
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_image_scalar_keys_insert_delete_and_preserve_retained_native_fields() {
    for (id, named) in [("scalex", "attrScaleX"), ("scaley", "attrScaleY"), ("rotate", "attrRotate"),
        ("shear", "attrShear"), ("opacity", "attrOpacity"), ("artPathWidth", "attrArtPathWidth")] {
        let directory = temp_dir();
        let xml = can3_visual_key_xml(id, named);
        let attribute = &xml[xml.find("<CMvAttrF xs.id=\"image-opacity\">").unwrap()..];
        let point_start = attribute.find("<CBezierPt>").unwrap();
        let point_end = point_start + attribute[point_start..].find("</CBezierPt>").unwrap() + "</CBezierPt>".len();
        let point_xml = &attribute[point_start..point_end];
        let (mut session, source) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(source).unwrap();
        let op = |session: &mut Session, operation: &str, frame: i64, value: Option<f64>| {
            let mut body = json!({"op":operation,"sceneGuid":"scene-guid","trackGuid":"image-track-guid",
                "curveId":id,"anchorFrame":frame,"expectedRevision":session.snapshot()["revision"]});
            if let Some(value) = value { body["value"] = json!(value); }
            result(&request(session, body)).clone()
        };
        for (frame, value) in [(-10, 5.0), (10, 15.0), (5, 12.0)] {
            op(&mut session, "live2d.animation.key.add", frame, Some(value));
        }
        let after = session.snapshot();
        let curve = &after["model"]["scenes"][0]["imageTracks"][0]["visualCurves"][0];
        assert_eq!(curve["points"].as_array().unwrap().iter().map(|p| p["anchor"]["frame"].as_i64().unwrap()).collect::<Vec<_>>(), [-10, 0, 5, 10]);
        assert_eq!(curve["curveTypes"], json!(["LINEAR", "LINEAR", "LINEAR", "LINEAR"]));
        let saved = directory.join("inserted.can3");
        result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
        let text = saved_main_xml(&saved);
        assert!(text.contains(point_xml));
        assert!(text.contains("<d xs.n=\"baseValue\">1.0</d>"));
        for _ in 0..3 { result(&request(&mut session, json!({"op":"undo"}))); }
        let restored = directory.join("restored.can3");
        result(&request(&mut session, json!({"op":"save","path":restored,"mark_saved":false})));
        assert_eq!(fs::read(restored).unwrap(), original);
        for _ in 0..3 { result(&request(&mut session, json!({"op":"redo"}))); }
        for frame in [0, -10, 10, 5] { op(&mut session, "live2d.animation.key.delete", frame, None); }
        let expected = session.snapshot()["model"].clone();
        assert_eq!(expected["scenes"][0]["imageTracks"][0]["visualCurves"][0]["points"], json!([]));
        let saved = directory.join("empty.can3");
        result(&request(&mut session, json!({"op":"save","path":saved})));
        let text = saved_main_xml(&saved);
        assert!(text.contains("<d xs.n=\"curMin\">10.0</d>"));
        assert!(text.contains("<d xs.n=\"curMax\">10.0</d>"));
        assert!(text.contains("<d xs.n=\"baseValue\">1.0</d>"));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(session.snapshot()["model"], expected);
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_image_scalar_empty_keys_restore_original_bytes_and_guard_requests() {
    let directory = temp_dir();
    let mut xml = can3_visual_key_xml("opacity", "attrOpacity");
    let owner = xml.find("<CMvAttrF xs.id=\"image-opacity\">").unwrap();
    let start = owner + xml[owner..].find("<CMutableSequence").unwrap();
    let end = start + xml[start..].find("</CMutableSequence>").unwrap() + "</CMutableSequence>".len();
    xml.replace_range(start..end, r#"<CMutableSequence xs.n="valueData"><ACValueSequence xs.n="super"><CMvAttrF xs.n="attr" xs.ref="image-opacity"/><d xs.n="curMin">0.0</d><d xs.n="curMax">1.0</d><null xs.n="keyPts2"/><i xs.n="keyMin">0</i><i xs.n="keyMax">0</i><d xs.n="lastValue">NaN</d><i xs.n="lastPos">-1</i><d xs.n="baseValue">1.0</d></ACValueSequence><array xs.n="points" count="0"/><carray_list xs.n="curveTypes" count="0"/></CMutableSequence>"#);
    let (mut session, source) = can3_key_fixture_session(&directory, &xml);
    let original = fs::read(source).unwrap();
    let before = session.snapshot();
    let call = |revision: Value| json!({"op":"live2d.animation.key.add","sceneGuid":"scene-guid",
        "trackGuid":"image-track-guid","curveId":"opacity","anchorFrame":-5,"value":0.25,"expectedRevision":revision});
    for extra in [json!({"partOpacityMapKey":"opacity"}), json!({"curveId":"xy"}), json!({"anchorFrame":2147483648_i64}),
        json!({"expectedRevision":u64::MAX}), json!({"type":"UNKNOWN"}), json!({"value":"NaN"})] {
        let mut body = call(before["revision"].clone());
        body.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
        assert_eq!(request(&mut session, body)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
    }
    result(&request(&mut session, call(before["revision"].clone())));
    let added = session.snapshot();
    assert_eq!(request(&mut session, call(added["revision"].clone()))["succeeded"], false);
    assert_eq!(session.snapshot(), added);
    let remove = |revision: Value, frame| json!({"op":"live2d.animation.key.delete","sceneGuid":"scene-guid",
        "trackGuid":"image-track-guid","curveId":"opacity","anchorFrame":frame,"expectedRevision":revision});
    assert_eq!(request(&mut session, remove(added["revision"].clone(), 99))["succeeded"], false);
    assert_eq!(session.snapshot(), added);
    result(&request(&mut session, remove(added["revision"].clone(), -5)));
    assert_eq!(session.snapshot()["model"], before["model"]);
    let restored = directory.join("inverse.can3");
    result(&request(&mut session, json!({"op":"save","path":restored,"mark_saved":false})));
    assert_eq!(fs::read(restored).unwrap(), original);
    result(&request(&mut session, json!({"op":"undo"})));
    let saved = directory.join("added.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    let revision = session.snapshot()["revision"].clone();
    result(&request(&mut session, remove(revision, -5)));
    let saved = directory.join("deleted-after-reopen.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let text = saved_main_xml(&saved);
    assert!(text.contains("<d xs.n=\"curMin\">0.25</d>"));
    assert!(text.contains("<d xs.n=\"curMax\">0.25</d>"));
    assert!(text.contains("<d xs.n=\"baseValue\">1.0</d>"));
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_image_keys_can_be_deleted_and_recreated_at_the_original_frame() {
    for copied in [false, true] {
        let directory = temp_dir();
        let xml = can3_visual_key_xml("opacity", "attrOpacity").replace(
            "<array xs.n=\"curveTypes\" count=\"1\"><CCurveType v=\"LINEAR\"/></array></CMutableSequence></CMvAttrF>",
            "<array xs.n=\"curveTypes\" count=\"1\"><CCurveType v=\"SMOOTH\"/></array></CMutableSequence></CMvAttrF>");
        let (mut session, _) = can3_key_fixture_session(&directory, &xml);
        let track = if copied {
            let body = json!({"op":"live2d.animation.track.duplicate","sceneGuid":"scene-guid",
                "trackGuid":"image-track-guid","name":"Recreate copy","expectedRevision":session.snapshot()["revision"]});
            result(&request(&mut session, body))["trackGuid"].as_str().unwrap().to_owned()
        } else { "image-track-guid".to_owned() };
        let before = session.snapshot()["model"].clone();
        for op in ["live2d.animation.key.delete", "live2d.animation.key.add", "live2d.animation.key.set"] {
            let mut body = json!({"op":op,"sceneGuid":"scene-guid","trackGuid":track,"curveId":"opacity",
                "anchorFrame":0,"expectedRevision":session.snapshot()["revision"]});
            if op.ends_with("add") { body["value"] = json!(25.0); }
            if op.ends_with("set") { body["value"] = json!(30.0); }
            result(&request(&mut session, body));
        }
        let expected = session.snapshot()["model"].clone();
        let changed = expected["scenes"][0]["imageTracks"].as_array().unwrap().iter().find(|t| t["guid"] == track).unwrap();
        let curve = &changed["visualCurves"][0];
        assert_eq!(curve["curveTypes"], json!(["LINEAR"]));
        assert_eq!(curve["points"][0]["corner"], true);
        assert_eq!(curve["points"][0]["anchor"]["value"], 30.0);
        assert_eq!(curve["points"][0]["next"]["value"], 25.0);
        result(&request(&mut session, json!({"op":"undo"})));
        result(&request(&mut session, json!({"op":"undo"})));
        result(&request(&mut session, json!({"op":"undo"})));
        assert_eq!(session.snapshot()["model"], before);
        result(&request(&mut session, json!({"op":"redo"})));
        result(&request(&mut session, json!({"op":"redo"})));
        result(&request(&mut session, json!({"op":"redo"})));
        let saved = directory.join("recreated.can3");
        result(&request(&mut session, json!({"op":"save","path":saved})));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(session.snapshot()["model"], expected);
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_image_scalar_keys_refuse_unowned_storage_atomically() {
    let xml = can3_visual_key_xml("opacity", "attrOpacity");
    for unsupported in [
        xml.replace("</shared>", "<Opaque><CMvAttrF xs.ref=\"image-opacity\"/></Opaque></shared>"),
        xml.replace("<CAttrId xs.n=\"key\" idstr=\"opacity\"/>", "<CAttrId xs.n=\"key\" idstr=\"wrong\"/>"),
        xml.replace("<CMvAttrF xs.n=\"attrOpacity\" xs.ref=\"image-opacity\"/>", "<CMvAttrF xs.n=\"attrOpacity\" xs.ref=\"image-xy\"/>"),
        xml.replace("<array xs.n=\"attrList\" count=\"3\">", "<array xs.n=\"attrList\" count=\"4\"><CMvAttrF xs.ref=\"image-opacity\"/>"),
        xml.replace("<CMutableSequence xs.n=\"valueData\"><ACValueSequence", "<CMutableSequence xs.n=\"valueData\" xs.id=\"shared-sequence\"><ACValueSequence"),
        xml.replace("<array xs.n=\"points\" count=\"1\"><CBezierPt>", "<array xs.n=\"points\" count=\"1\"><CBezierPt xs.id=\"shared-point\">"),
    ] {
        let directory = temp_dir();
        let (mut session, source) = can3_key_fixture_session(&directory, &unsupported);
        let original = fs::read(&source).unwrap();
        let before = session.snapshot();
        let history = result(&request(&mut session, json!({"op":"history.summary"}))).clone();
        for (op, frame) in [("live2d.animation.key.set", 0), ("live2d.animation.key.add", 10),
            ("live2d.animation.key.delete", 0)] {
            let mut body = json!({"op":op,"sceneGuid":"scene-guid","trackGuid":"image-track-guid",
                "curveId":"opacity","anchorFrame":frame,"expectedRevision":before["revision"]});
            if op != "live2d.animation.key.delete" { body["value"] = json!(25); }
            let reply = request(&mut session, body);
            assert_eq!(reply["succeeded"], false, "{reply}");
            assert_eq!(session.snapshot(), before);
            assert_eq!(result(&request(&mut session, json!({"op":"history.summary"}))), &history);
        }
        let saved = directory.join("unchanged.can3");
        result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
        assert_eq!(fs::read(saved).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_image_key_structure_composes_with_pending_copies_and_donor_deletion() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, &can3_visual_key_xml("opacity", "attrOpacity"));
    let original = fs::read(source).unwrap();
    let edit = |session: &mut Session, track: &str, frame, value: Option<f64>| {
        let mut body = json!({"op":if value.is_some() {"live2d.animation.key.add"} else {"live2d.animation.key.delete"},
            "sceneGuid":"scene-guid","trackGuid":track,"curveId":"opacity","anchorFrame":frame,
            "expectedRevision":session.snapshot()["revision"]});
        if let Some(value) = value { body["value"] = json!(value); }
        result(&request(session, body)).clone()
    };
    let copy = |session: &mut Session, track: &str| {
        let body = json!({"op":"live2d.animation.track.duplicate","sceneGuid":"scene-guid","trackGuid":track,
            "name":"Key copy","expectedRevision":session.snapshot()["revision"]});
        result(&request(session, body))["trackGuid"].as_str().unwrap().to_owned()
    };
    edit(&mut session, "image-track-guid", 10, Some(30.0));
    let first = copy(&mut session, "image-track-guid");
    edit(&mut session, "image-track-guid", 0, None);
    edit(&mut session, &first, 5, Some(25.0));
    let second = copy(&mut session, &first);
    edit(&mut session, &first, 10, None);
    let body = json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid","trackGuid":"image-track-guid",
        "expectedRevision":session.snapshot()["revision"]});
    result(&request(&mut session, body));
    let expected = session.snapshot()["model"].clone();
    let tracks = expected["scenes"][0]["imageTracks"].as_array().unwrap();
    assert_eq!(tracks.len(), 2);
    for (guid, frames) in [(&first, vec![0, 5]), (&second, vec![0, 5, 10])] {
        let track = tracks.iter().find(|t| t["guid"] == *guid).unwrap();
        assert_eq!(track["visualCurves"][0]["points"].as_array().unwrap().iter()
            .map(|p| p["anchor"]["frame"].as_i64().unwrap()).collect::<Vec<_>>(), frames);
    }
    for _ in 0..7 { result(&request(&mut session, json!({"op":"undo"}))); }
    let restored = directory.join("restored.can3");
    result(&request(&mut session, json!({"op":"save","path":restored,"mark_saved":false})));
    assert_eq!(fs::read(restored).unwrap(), original);
    for _ in 0..7 { result(&request(&mut session, json!({"op":"redo"}))); }
    let saved = directory.join("copies.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    fs::remove_dir_all(directory).unwrap();
}

