#[test]
fn can3_cloning_does_not_adopt_stored_guide_tracks() {
    for model_track in [true, false] {
        let directory = temp_dir();
        let mut xml = can3_guide_track_xml(1)
            .replace("<CMvTrack_GuideImage_Source xs.ref=\"guide-0\"/>", "")
            .replace("<CTrackGuid xs.ref=\"guide-guid-0\"/>", "")
            .replace("<carray_list xs.n=\"_sources\" count=\"5\">", "<carray_list xs.n=\"_sources\" count=\"4\">")
            .replace("<carray_list xs.n=\"_childTrackGuids\" count=\"4\">", "<carray_list xs.n=\"_childTrackGuids\" count=\"3\">");
        let owner = if model_track { "<CMvTrack_Live2DModel_Source xs.id=\"track\">" } else { "<CSceneSource xs.id=\"scene\">" };
        xml = xml.replace(owner, &format!("{owner}<CMvTrack_GuideImage_Source xs.n=\"storedGuide\" xs.ref=\"guide-0\"/>"));
        let (mut session, source) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(source).unwrap();
        assert_eq!(session.snapshot()["model"]["scenes"][0]["guideTracks"], json!([]));
        let mut operation = if model_track {
            json!({"op":"live2d.animation.track.add","sceneGuid":"scene-guid","resourceGuid":"res-guid","name":"Added"})
        } else {
            json!({"op":"live2d.animation.scene.add","name":"Added scene","fps":30.0,"durationFrames":60})
        };
        operation["expectedRevision"] = session.snapshot()["revision"].clone();
        result(&request(&mut session, operation));
        let saved = directory.join("cloned.can3");
        result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
        let text = saved_main_xml(&saved);
        let document = roxmltree::Document::parse(&text).unwrap();
        assert_eq!(document.descendants().filter(|node| node.has_tag_name("CMvTrack_GuideImage_Source")
            && node.attribute("xs.id").is_some()).count(), 1);
        result(&request(&mut session, json!({"op":"undo"})));
        let restored = directory.join("restored.can3");
        result(&request(&mut session, json!({"op":"save","path":restored,"mark_saved":false})));
        assert_eq!(fs::read(restored).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }
}

