#[test]
fn can3_sound_copy_preserves_native_data_and_composes_with_other_families() {
    let directory = temp_dir();
    let xml = can3_guide_track_xml(1)
        .replace("<i xs.n=\"speed\">100</i><i xs.n=\"startFrame\">0</i><d xs.n=\"defaultVolume\">1</d>",
            "<i xs.n=\"speed\">77</i><i xs.n=\"startFrame\">5</i><d xs.n=\"defaultVolume\">0.25</d>")
        .replace("<CFixedSequence xs.n=\"valueData\"><d xs.n=\"baseValue\">0</d><d xs.n=\"curMin\">0</d><d xs.n=\"curMax\">0</d>",
            "<CFixedSequence xs.n=\"valueData\"><d xs.n=\"baseValue\">0.375</d><d xs.n=\"curMin\">0.375</d><d xs.n=\"curMax\">0.375</d>");
    let (mut session, source) = can3_key_fixture_session(&directory, &xml);
    let original = fs::read(&source).unwrap();
    let copy = |session: &mut Session, donor: &str| {
        let revision = session.snapshot()["revision"].clone();
        result(&request(session, json!({"op":"live2d.animation.track.duplicate","sceneGuid":"scene-guid",
            "trackGuid":donor,"name":"Sound copy","expectedRevision":revision})))["trackGuid"]
            .as_str().unwrap().to_owned()
    };
    let first = copy(&mut session, "sound-guid-0");
    let first_save = directory.join("first.can3");
    result(&request(&mut session, json!({"op":"save","path":first_save,"mark_saved":false})));
    let text = saved_main_xml(&first_save);
    let before = roxmltree::Document::parse(&xml).unwrap();
    let after = roxmltree::Document::parse(&text).unwrap();
    let ids: std::collections::HashSet<_> = before.descendants().filter_map(|node| node.attribute("xs.id")).collect();
    let added: Vec<_> = after.descendants().filter(|node| node.attribute("xs.id").is_some_and(|id| !ids.contains(id))).collect();
    assert_eq!(added.len(), 4);
    let cloned = added.iter().find(|node| node.has_tag_name("CMvTrack_JavaSoundTrack_Source")).unwrap();
    assert!(text[cloned.range()].contains("<i xs.n=\"speed\">77</i>"));
    assert!(text[cloned.range()].contains("<i xs.n=\"startFrame\">5</i>"));
    assert!(text[cloned.range()].contains("<d xs.n=\"defaultVolume\">0.25</d>"));
    let volume = added.iter().find(|node| node.has_tag_name("CMvAttrF")).unwrap();
    for field in ["baseValue", "curMin", "curMax"] {
        assert!(text[volume.range()].contains(&format!("<d xs.n=\"{field}\">0.375</d>")));
    }
    for node in before.descendants().filter(|node| node.attribute("xs.id").is_some()) {
        if !matches!(node.attribute("xs.id"), Some("scene" | "group")) {
            assert!(text.contains(&xml[node.range()]), "{}", node.attribute("xs.id").unwrap());
        }
    }
    let second = copy(&mut session, &first);
    let cancelled = copy(&mut session, &second);
    copy(&mut session, "image-track-guid");
    copy(&mut session, "guide-guid-0");
    for guid in ["sound-guid-0", &first, &cancelled] {
        let revision = session.snapshot()["revision"].clone();
        result(&request(&mut session, json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid",
            "trackGuid":guid,"expectedRevision":revision})));
    }
    let expected = session.snapshot()["model"].clone();
    assert_eq!(expected["scenes"][0]["soundTracks"].as_array().unwrap().len(), 1);
    assert_eq!(expected["scenes"][0]["soundTracks"][0]["guid"], second);
    for _ in 0..8 { result(&request(&mut session, json!({"op":"undo"}))); }
    let restored = directory.join("restored.can3");
    result(&request(&mut session, json!({"op":"save","path":restored,"mark_saved":false})));
    assert_eq!(fs::read(restored).unwrap(), original);
    for _ in 0..8 { result(&request(&mut session, json!({"op":"redo"}))); }
    let saved = directory.join("copies.can3");
    result(&request(&mut session, json!({"op":"save","path":saved,"mark_saved":false})));
    let repeated = directory.join("repeated.can3");
    result(&request(&mut session, json!({"op":"save","path":repeated,"mark_saved":false})));
    assert_eq!(fs::read(&saved).unwrap(), fs::read(repeated).unwrap());
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    assert_eq!(fs::read(source).unwrap(), original);
    fs::remove_dir_all(directory).unwrap();
}

