#[test]
fn can3_deletes_a_complete_owned_inherited_grouped_track() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, &can3_grouped_native_track_xml());
    let original = fs::read(&source).unwrap();
    let before = session.snapshot();
    let mut expected = before["model"].clone();
    expected["scenes"][0]["tracks"] = json!([]);
    result(&request(&mut session, json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid",
        "trackGuid":"track-guid","expectedRevision":before["revision"]})));
    assert_eq!(session.snapshot()["model"], expected);
    assert_eq!(session.snapshot()["revision"].as_u64(), Some(before["revision"].as_u64().unwrap() + 1));
    result(&request(&mut session, json!({"op":"undo"})));assert_eq!(session.snapshot()["model"], before["model"]);
    result(&request(&mut session, json!({"op":"redo"})));assert_eq!(session.snapshot()["model"], expected);
    let saved = directory.join("deleted.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    let document = soul2d_core::caff::CaffDocument::parse(&fs::read(saved).unwrap()).unwrap();
    let xml = String::from_utf8(document.main_xml()).unwrap();
    let parsed = roxmltree::Document::parse(&xml).unwrap();
    let ids: std::collections::HashSet<_> = parsed.descendants().filter_map(|n| n.attribute("xs.id")).collect();
    for removed in ["track", "track-guid-storage", "parameter-effect", "parts-effect", "visual-effect", "eye-effect", "lip-effect",
        "attr", "part-a", "part-b", "part-legacy", "xy-attr", "int-attr", "fixed-attr"] { assert!(!ids.contains(removed), "{removed}"); }
    for retained in ["scene", "group", "group-guid-storage", "resource", "resource-guid-storage", "keep-resource",
        "parameter-group-guid-storage", "keep-parameter-group"] { assert!(ids.contains(retained), "{retained}"); }
    let children = parsed.descendants().find(|n| n.attribute("xs.n") == Some("_childTrackGuids")).unwrap();
    assert_eq!(children.attribute("count"), Some("0"));assert_eq!(children.children().filter(|n| n.is_element()).count(), 0);
    assert!(parsed.descendants().filter_map(|n| n.attribute("xs.ref")).all(|id| ids.contains(id)));
    assert_eq!(fs::read(source).unwrap(), original);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_deletes_multiple_grouped_tracks_before_the_first_save() {
    let mut xml = can3_grouped_native_track_xml();
    let ids = ["track", "track-guid-storage", "parameter-effect", "parts-effect", "visual-effect", "eye-effect", "lip-effect",
        "attr", "part-a", "part-b", "part-legacy", "xy-attr", "int-attr", "fixed-attr"];
    let mut copies = {
        let parsed = roxmltree::Document::parse(&xml).unwrap();
        parsed.descendants().filter(|n| n.attribute("xs.id").is_some_and(|id| ids.contains(&id)))
            .map(|n| xml[n.range()].to_owned()).collect::<Vec<_>>().join("")
    };
    for id in ids {
        for quote in ['\'', '"'] {
            for field in ["xs.id", "xs.ref"] {
                copies = copies.replace(&format!("{field}={quote}{id}{quote}"), &format!("{field}={quote}{id}-2{quote}"));
            }
        }
    }
    copies = copies.replace(r#"uuid="track-guid""#, r#"uuid="track-guid-2""#);
    xml = xml.replace(r#"<carray_list xs.n="_sources" count="2">"#,
        r#"<carray_list xs.n="_sources" count="3"><CMvTrack_Live2DModel_Source xs.ref="track-2"/>"#)
        .replace(r#"<carray_list xs.n="_childTrackGuids" count="1">"#,
            r#"<carray_list xs.n="_childTrackGuids" count="2"><CTrackGuid xs.ref="track-guid-storage-2"/>"#)
        .replace("</shared>", &format!("{copies}</shared>"));
    let directory = temp_dir();
    let (mut session, _) = can3_key_fixture_session(&directory, &xml);
    assert_eq!(session.snapshot()["model"]["scenes"][0]["tracks"].as_array().unwrap().len(), 2);
    for guid in ["track-guid", "track-guid-2"] {
        let revision = session.snapshot()["revision"].clone();
        result(&request(&mut session, json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid",
            "trackGuid":guid,"expectedRevision":revision})));
    }
    let saved = directory.join("both-deleted.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"]["scenes"][0]["tracks"], json!([]));
    let document = soul2d_core::caff::CaffDocument::parse(&fs::read(saved).unwrap()).unwrap();
    let xml = String::from_utf8(document.main_xml()).unwrap();
    let parsed = roxmltree::Document::parse(&xml).unwrap();
    let members = parsed.descendants().find(|n| n.attribute("xs.n") == Some("_childTrackGuids")).unwrap();
    assert_eq!(members.attribute("count"), Some("0"));
    assert_eq!(members.children().filter(|n| n.is_element()).count(), 0);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_native_parent_ownership_refusals_are_atomic() {
    let base = can3_grouped_native_track_xml();
    let mut cases = Vec::new();
    for (name, tag, id) in [
        ("attribute", "CMvAttrPt", "xy-attr"), ("effect", "CMvEffect_EyeBlink", "eye-effect"),
        ("group", "CMvTrack_Group_Source", "group"), ("guid", "CTrackGuid", "track-guid-storage"),
        ("track", "CMvTrack_Live2DModel_Source", "track"),
    ] {
        cases.push((name, base.replace("</shared>", &format!(r#"<Opaque><{tag} xs.ref="{id}"/></Opaque></shared>"#))));
    }
    cases.push(("unknown-effect", base.replace("CMvEffect_EyeBlink", "UnknownEffect")));
    cases.push(("unknown-attribute", base.replace("CMvAttrPt", "UnknownAttribute")));
    cases.push(("unknown-fixed-sequence", base.replace("CFixedSequence", "UnknownSequence")));
    cases.push(("fixed-sequence-keys", base.replace("</CFixedSequence>",
        r#"<array xs.n="points" count="0"/></CFixedSequence>"#)));
    cases.push(("unknown-parameter-group", base.replace("CMvParameter_Group", "UnknownParameterGroup")));
    cases.push(("parameter-group-count", base.replace(r#"xs.n="parameterGroupList" count="1""#,
        r#"xs.n="parameterGroupList" count="2""#)));
    cases.push(("aliased-parameter-group-guid", base.replace(r#"xs.n="guid" xs.ref="parameter-group-guid-storage""#,
        r#"xs.n="guid" xs.ref="parameter-group-guid-alias""#).replace("</shared>",
            r#"<CParameterGroupGuid xs.id="parameter-group-guid-alias" xs.ref="parameter-group-guid-storage"/></shared>"#)));
    cases.push(("shared-super", base.replace(r#"<ICMvTrack_Linked xs.n="super">"#,
        r#"<ICMvTrack_Linked xs.n="super" xs.id="nested-base">"#)));
    cases.push(("aliased-guid", base.replace(r#"<CTrackGuid xs.n="guid" xs.ref="track-guid-storage"/>"#,
        r#"<CTrackGuid xs.n="guid" xs.ref="guid-alias"/>"#).replace("</shared>",
            r#"<CTrackGuid xs.id="guid-alias" xs.ref="track-guid-storage"/></shared>"#)));
    cases.push(("bad-member-count", base.replace(r#"count="2" type="ICMvAttr"><CMvAttrPt"#,
        r#"count="3" type="ICMvAttr"><CMvAttrPt"#)));
    cases.push(("duplicate-member", base.replace(r#"count="2" type="ICMvAttr"><CMvAttrPt"#,
        r#"count="3" type="ICMvAttr"><CMvAttrPt"#).replace("<CMvAttrPt xs.ref='xy-attr'/>",
            "<CMvAttrPt xs.ref='xy-attr'/><CMvAttrPt xs.ref='xy-attr'/>")));
    for (name, xml) in cases {
        assert_ne!(xml, base, "{name}");
        let directory = temp_dir();
        let (mut session, source) = can3_key_fixture_session(&directory, &xml);
        let before = session.snapshot();
        let history = result(&request(&mut session, json!({"op":"history.summary"}))).clone();
        let original = fs::read(&source).unwrap();
        let reply = request(&mut session, json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid",
            "trackGuid":"track-guid","expectedRevision":before["revision"]}));
        assert_eq!(reply["succeeded"], false, "{name}: {reply}");
        assert_eq!(session.snapshot(), before, "{name}");
        assert_eq!(result(&request(&mut session, json!({"op":"history.summary"}))), &history, "{name}");
        assert_eq!(fs::read(source).unwrap(), original, "{name}");
        fs::remove_dir_all(directory).unwrap();
    }
}

