#[test]
fn can3_part_curves_follow_saved_track_and_scene_deletion() {
    for new_scene in [false, true] {
        let directory = temp_dir();
        let cmo3 = part_curves_cmo3(&directory);
        let (mut session, source) = can3_key_fixture_session(&directory, CAN3_CURVE_EDITOR_XML);
        let original = fs::read(&source).unwrap();
        let original_model = session.snapshot()["model"].clone();
        let scene = if new_scene {
            let revision = session.snapshot()["revision"].clone();
            let response = request(&mut session, json!({"op":"live2d.animation.scene.add","name":"Added",
                "fps":30.0,"durationFrames":60,"expectedRevision":revision}));
            result(&response)["sceneGuid"].as_str().unwrap().to_owned()
        } else { "scene-guid".into() };
        let call = track_add(&session, &scene, "res-guid", "Part track");
        let track = result(&request(&mut session, call))["trackGuid"].as_str().unwrap().to_owned();
        let call = part_curve_add(&session, &cmo3, "PartNewA", &scene, &track);
        result(&request(&mut session, call));
        let saved = directory.join("topology.can3");
        result(&request(&mut session, json!({"op":"save","path":saved})));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        let revision = session.snapshot()["revision"].clone();
        let call = if new_scene { json!({"op":"live2d.animation.scene.delete","sceneGuid":scene,"expectedRevision":revision}) }
            else { json!({"op":"live2d.animation.track.delete","sceneGuid":scene,"trackGuid":track,"expectedRevision":revision}) };
        result(&request(&mut session, call));
        result(&request(&mut session, json!({"op":"save","path":saved})));
        let xml = saved_main_xml(&saved);
        assert!(!xml.contains("soul2d-parts-") && !xml.contains("soul2d-part-curve-") && !xml.contains("PartNewA"));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(session.snapshot()["model"], original_model);
        assert_eq!(fs::read(&source).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_part_curve_refusals_are_atomic_and_preserve_input_files() {
    let directory = temp_dir();
    let cmo3 = part_curves_cmo3(&directory);
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_PART_OPACITY_XML);
    let files = [fs::read(&cmo3).unwrap(), fs::read(&source).unwrap()];
    let mut calls = Vec::new();
    for part in [json!(null), json!(""), json!("missing"), json!("PartArmA")] {
        let mut call = part_curve_add(&session, &cmo3, "root", "scene-guid", "track-guid");
        call["partId"] = part;
        calls.push(call);
    }
    let call = part_curve_add(&session, &cmo3, "root", "scene-guid", "track-guid");
    let mut both = call.clone();
    both["parameterId"] = json!("ParamNew");
    calls.push(both);
    let mut neither = call.clone();
    neither.as_object_mut().unwrap().remove("partId");
    calls.push(neither);
    let mut stale = call;
    stale["expectedRevision"] = json!(0);
    calls.push(stale);
    let mut wrong_selector = curve_delete(&session, "live2DPartsOpacity:legacy-attribute", "track-guid");
    wrong_selector["partOpacityMapKey"] = json!("live2DPartsOpacity_missing");
    calls.push(wrong_selector);
    for call in calls {
        let before = session.snapshot();
        assert_eq!(request(&mut session, call)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
        assert_eq!([fs::read(&cmo3).unwrap(), fs::read(&source).unwrap()], files);
    }
    let call = curve_delete(&session, "live2DPartsOpacity_PartArmA", "track-guid");
    result(&request(&mut session, call));
    let bad = directory.join("bad.cmo3");
    fs::write(&bad, authoring_bytes(&saved_main_xml(&cmo3).replace("uuid='part-guid-a'", "uuid='wrong-guid'"))).unwrap();
    let before = session.snapshot();
    let call = part_curve_add(&session, &bad, "PartArmA", "scene-guid", "track-guid");
    assert_eq!(request(&mut session, call)["succeeded"], false);
    assert_eq!(session.snapshot(), before);
    for xml in [
        CAN3_PART_OPACITY_XML.replace("</shared>", "<Opaque><CMvAttrF xs.ref='part-a'/></Opaque></shared>"),
        can3_part_storage(|text| text.replace("keep-part-a", "<Opaque xs.id='nested-owned'/>") )
            .replace("</shared>", "<Opaque xs.ref='nested-owned'/></shared>"),
        CAN3_PART_OPACITY_XML.replace("<entry><CAttrId xs.n=\"key\" idstr=\"live2DPartsOpacity:PartArmA\"/>",
            "<entry><Opaque xs.id='map-owned'/><CAttrId xs.n=\"key\" idstr=\"live2DPartsOpacity:PartArmA\"/>")
            .replace("</shared>", "<Opaque xs.ref='map-owned'/></shared>"),
    ] {
        let (mut session, path) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(&path).unwrap();
        let before = session.snapshot();
        let call = curve_delete(&session, "live2DPartsOpacity_PartArmA", "track-guid");
        assert_eq!(request(&mut session, call)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&path).unwrap(), original);
    }
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_part_curve_add_refuses_aliased_lists_and_nonplain_null_effects() {
    for xml in [
        CAN3_CURVE_EDITOR_XML.replace("<i xs.n=\"start\">", "<null xs.n='partsVisibleEffect' future='keep'/><i xs.n=\"start\">"),
        CAN3_CURVE_EDITOR_XML.replace("<i xs.n=\"start\">", "<null xs.n='partsVisibleEffect'><Opaque/></null><i xs.n=\"start\">"),
        CAN3_PART_OPACITY_XML.replace("<hash_map xs.n=\"attrMap\" count=\"3\">", "<hash_map xs.n=\"attrMap\" xs.id='shared-map' count=\"3\">"),
        CAN3_PART_OPACITY_XML.replace("<array xs.n=\"attrList\" count=\"2\"", "<array xs.n=\"attrList\" xs.id='shared-list' count=\"2\""),
    ] {
        let directory = temp_dir();
        let cmo3 = part_curves_cmo3(&directory);
        let (mut session, path) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(&path).unwrap();
        let before = session.snapshot();
        let call = part_curve_add(&session, &cmo3, "root", "scene-guid", "track-guid");
        assert_eq!(request(&mut session, call)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&path).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }
}

