#[test]
fn can3_mapped_curve_delete_uses_exact_identity_and_reparses_cumulative_counts() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, include_str!("fixtures/can3-underscore-opacity.xml"));
    let original = fs::read(&source).unwrap();
    for selector in [None, Some(json!(null)), Some(json!(7)), Some(json!("")), Some(json!("missing")),
        Some(json!("live2DPartsOpacity:PartArmB"))] {
        let mut call = curve_delete(&session, "live2DPartsOpacity_PartArmA", "track-guid");
        if let Some(key) = selector { call["partOpacityMapKey"] = key; }
        let before = session.snapshot();
        assert_eq!(request(&mut session, call)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
    }
    for (id, key, field, position) in [
        ("live2DPartsOpacity_PartArmA", Some("live2DPartsOpacity_PartArmB"), "underscorePartOpacityCurves", 1),
        ("live2DPartsOpacity:legacy-attribute", None, "legacyPartOpacityCurves", 0),
        ("live2DPartsOpacity_PartArmA", None, "underscorePartOpacityCurves", 0),
    ] {
        let before = session.snapshot();
        let mut expected = before["model"].clone();
        let track = &mut expected["scenes"][0]["tracks"][0];
        track[field].as_array_mut().unwrap().remove(position);
        track["skippedLegacyPartOpacityCount"] = json!(track["legacyPartOpacityCurves"].as_array().unwrap().len()
            + track["underscorePartOpacityCurves"].as_array().unwrap().len());
        let mut call = curve_delete(&session, id, "track-guid");
        if let Some(key) = key { call["partOpacityMapKey"] = json!(key); }
        result(&request(&mut session, call));
        let after = session.snapshot();
        assert_eq!(after["model"], expected);
        assert_eq!(after["revision"].as_u64(), before["revision"].as_u64().map(|n| n + 1));
        assert_eq!(after["history"]["count"].as_u64(), before["history"]["count"].as_u64().map(|n| n + 1));
        result(&request(&mut session, json!({"op":"undo"})));
        assert_eq!(session.snapshot()["model"], before["model"]);
        result(&request(&mut session, json!({"op":"redo"})));
        assert_eq!(session.snapshot()["model"], expected);
    }
    let expected = session.snapshot()["model"].clone();
    let saved = directory.join("mapped-deleted.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let xml = saved_main_xml(&saved);
    assert!(xml.contains("xs.id=\"parts-effect\""));
    assert!(!xml.contains("xs.id=\"part-a\"") && !xml.contains("xs.id=\"part-b\"") && !xml.contains("xs.id=\"part-legacy\""));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    assert_eq!(fs::read(&source).unwrap(), original);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_mapped_curve_delete_combines_optional_members_modern_edits_and_track_topology() {
    let fixture = include_str!("fixtures/can3-underscore-opacity.xml");
    let doc = roxmltree::Document::parse(fixture).unwrap();
    let members = doc.descendants().find(|n| n.attribute("type") == Some("ICMvAttr")).unwrap();
    let absent = fixture.replacen(&fixture[members.range()], "", 1);
    let present = fixture.replacen(&fixture[members.range()],
        "<array xs.n='attrList' count='3' type='ICMvAttr'><CMvAttrF xs.ref='part-a'/><CMvAttrF xs.ref='part-b'/><CMvAttrF xs.ref='part-legacy'/></array>", 1);
    for (xml, add_modern) in [(absent.as_str(), true), (present.as_str(), true)] {
        let directory = temp_dir();
        let cmo3 = part_curves_cmo3(&directory);
        let (mut session, source) = can3_key_fixture_session(&directory, xml);
        let original = fs::read(&source).unwrap();
        if add_modern {
            let call = part_curve_add(&session, &cmo3, "root", "scene-guid", "track-guid");
            result(&request(&mut session, call));
        }
        let mut call = curve_delete(&session, "live2DPartsOpacity_PartArmA", "track-guid");
        call["partOpacityMapKey"] = json!("live2DPartsOpacity_PartArmB");
        result(&request(&mut session, call));
        let call = curve_delete(&session, "live2DPartsOpacity:legacy-attribute", "track-guid");
        result(&request(&mut session, call));
        let call = track_add(&session, "scene-guid", "res-guid", "Added after mapped deletion");
        result(&request(&mut session, call));
        if add_modern && xml == present {
            let call = curve_delete(&session, "live2DPartsOpacity_root", "track-guid");
            result(&request(&mut session, call));
        }
        let expected = session.snapshot()["model"].clone();
        assert_eq!(expected["scenes"][0]["tracks"][0]["skippedLegacyPartOpacityCount"], 1);
        let saved = directory.join("mixed-edits.can3");
        result(&request(&mut session, json!({"op":"save","path":saved})));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(session.snapshot()["model"], expected);
        assert_eq!(fs::read(&source).unwrap(), original);
        fs::remove_dir_all(directory).unwrap();
    }
}

