#[test]
fn can3_mapped_part_parent_deletion_removes_owned_storage_and_roundtrips() {
    let underscore = include_str!("fixtures/can3-underscore-opacity.xml");
    let doc = roxmltree::Document::parse(underscore).unwrap();
    let members = doc.descendants().find(|n| n.attribute("type") == Some("ICMvAttr")).unwrap();
    let no_members = underscore.replacen(&underscore[members.range()], "", 1);
    let all_members = underscore.replacen(&underscore[members.range()],
        "<array xs.n='attrList' count='3' type='ICMvAttr'><CMvAttrF xs.ref='part-a'/><CMvAttrF xs.ref='part-b'/><CMvAttrF xs.ref='part-legacy'/></array>", 1);
    let modern_doc = roxmltree::Document::parse(CAN3_PART_OPACITY_XML).unwrap();
    let modern = modern_doc.descendants().find(|n| n.attribute("xs.id") == Some("part-a")).unwrap();
    let modern = CAN3_PART_OPACITY_XML[modern.range()].replace("part-a", "part-modern");
    let mixed = underscore.replace("</shared>", &format!("{modern}</shared>"))
        .replace("xs.n=\"attrMap\" count=\"3\">", "xs.n=\"attrMap\" count=\"4\"><entry><CAttrId xs.n='key' idstr='live2DPartsOpacity:PartArmA'/><CMvAttrF xs.n='value' xs.ref='part-modern'/></entry>")
        .replace("count=\"2\" type=\"ICMvAttr\">", "count=\"3\" type=\"ICMvAttr\"><CMvAttrF xs.ref='part-modern'/>");
    let registered = underscore.replace("<i xs.n=\"start\">", "<CMvEffectManager xs.n='effectManager'><array xs.n='effectList' count='1' type='ICMvEffect'><CMvEffect_Live2DPartsVisible xs.ref='parts-effect'/></array></CMvEffectManager><i xs.n=\"start\">");
    for xml in [CAN3_PART_OPACITY_XML, underscore, no_members.as_str(), all_members.as_str(), mixed.as_str(), registered.as_str()] {
        for scene in [false, true] {
            let directory = temp_dir();
            let (mut session, source) = can3_key_fixture_session(&directory, xml);
            let original = fs::read(&source).unwrap();
            let before = session.snapshot();
            let mut expected = before["model"].clone();
            let call = if scene {
                expected["scenes"] = json!([]);
                scene_delete(&session, "scene-guid")
            } else {
                expected["scenes"][0]["tracks"] = json!([]);
                track_delete(&session, "scene-guid", "track-guid")
            };
            result(&request(&mut session, call));
            let after = session.snapshot();
            assert_eq!(after["model"], expected);
            assert_eq!(after["revision"].as_u64(), before["revision"].as_u64().map(|n| n + 1));
            assert_eq!(after["history"]["count"].as_u64(), before["history"]["count"].as_u64().map(|n| n + 1));
            result(&request(&mut session, json!({"op":"undo"})));
            assert_eq!(session.snapshot()["model"], before["model"]);
            result(&request(&mut session, json!({"op":"redo"})));
            assert_eq!(session.snapshot()["model"], expected);
            let saved = directory.join("parent-deleted.can3");
            result(&request(&mut session, json!({"op":"save","path":saved})));
            let written = saved_main_xml(&saved);
            let doc = roxmltree::Document::parse(&written).unwrap();
            for id in ["track", "attr", "parts-effect", "part-a", "part-b", "part-legacy", "part-modern"] {
                assert!(!doc.descendants().any(|n| n.attribute("xs.id") == Some(id)), "{id}");
            }
            assert_eq!(doc.descendants().any(|n| n.attribute("xs.id") == Some("scene")), !scene);
            let ids: std::collections::HashSet<_> = doc.descendants().filter_map(|n| n.attribute("xs.id")).collect();
            assert!(doc.descendants().filter_map(|n| n.attribute("xs.ref")).all(|id| ids.contains(id)));
            assert!(written.contains("keep-root &amp; 0.1234500"));
            assert!(written.contains("fixture.cmo3"));
            result(&request(&mut session, json!({"op":"open","path":saved})));
            assert_eq!(session.snapshot()["model"], expected);
            assert_eq!(fs::read(&source).unwrap(), original);
            fs::remove_dir_all(directory).unwrap();
        }
    }
}

#[test]
fn can3_mapped_part_parent_deletion_refuses_unowned_or_aliased_storage_atomically() {
    for fixture in [CAN3_PART_OPACITY_XML, include_str!("fixtures/can3-underscore-opacity.xml")] {
        let extra_member = fixture.replace("count=\"2\" type=\"ICMvAttr\">",
            "count=\"3\" type=\"ICMvAttr\"><CMvAttrF xs.ref='foreign'/>")
            .replace("</shared>", "<Opaque xs.id='foreign'/></shared>");
        let duplicate_member = fixture.replace("count=\"2\" type=\"ICMvAttr\">",
            "count=\"3\" type=\"ICMvAttr\"><CMvAttrF xs.ref='part-a'/>");
        let extra_map = fixture.replace("xs.n=\"attrMap\" count=\"3\">",
            "xs.n=\"attrMap\" count=\"4\"><entry><CAttrId xs.n='key' idstr='future'/><CMvAttrF xs.n='value' xs.ref='part-a'/></entry>");
        let nested_id = fixture.replace("keep-part-a", "<Opaque xs.id='nested-unknown'/>");
        let nested_effect_id = fixture.replace("<hash_map xs.n=\"attrMap\"", "<Opaque xs.id='nested-effect'/><hash_map xs.n=\"attrMap\"");
        let unused_shared_super = fixture.replace("keep-part-a",
            "<Opaque><Unused xs.n='super' xs.ref='foreign'/></Opaque>")
            .replace("</shared>", "<Opaque xs.id='foreign'/></shared>");
        let outside_reference = fixture.replace("</shared>", "<Opaque xs.ref='part-a'/></shared>");
        let outside_effect = fixture.replace("</shared>", "<Opaque xs.ref='parts-effect'/></shared>");
        let aliased_member = fixture.replace("<CMvAttrF xs.ref=\"part-a\"/>", "<CMvAttrF xs.ref='part-a' future='keep'/>");
        for xml in [extra_member, duplicate_member, extra_map, nested_id, nested_effect_id,
            unused_shared_super, outside_reference, outside_effect, aliased_member] {
            for scene in [false, true] {
                let directory = temp_dir();
                let (mut session, source) = can3_key_fixture_session(&directory, &xml);
                let original = fs::read(&source).unwrap();
                let before = session.snapshot();
                let call = if scene { scene_delete(&session, "scene-guid") }
                    else { track_delete(&session, "scene-guid", "track-guid") };
                assert_eq!(request(&mut session, call)["succeeded"], false);
                assert_eq!(session.snapshot(), before);
                assert_eq!(fs::read(&source).unwrap(), original);
                fs::remove_dir_all(directory).unwrap();
            }
        }
    }
}

#[test]
fn can3_part_curve_add_accumulates_keys_and_native_roundtrips() {
    let directory = temp_dir();
    let cmo3 = curve_cmo3(&directory);
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_PART_OPACITY_XML);
    let original = fs::read(&source).unwrap();
    let add = part_curve_add(&session, &cmo3, "root", "scene-guid", "track-guid");
    result(&request(&mut session, add));
    let mut edit = can3_key_edit(&session, "live2d.animation.key.add", json!({"anchorFrame":5,"value":0.6}));
    edit["curveId"] = json!("live2DPartsOpacity_root");
    result(&request(&mut session, edit));
    let model = session.snapshot()["model"].clone();
    let curve = &model["scenes"][0]["tracks"][0]["partOpacityCurves"][2];
    assert_eq!(curve["partId"], "root");
    assert_eq!(curve["partGuid"], "part-guid");
    assert_eq!(curve["sourcePart"], json!({"type":"CPartId","value":"root"}));
    assert_eq!(curve["range"], json!([0.0,1.0]));
    assert_eq!(curve["points"][0]["anchor"], json!({"frame":5,"value":0.6}));
    let saved = directory.join("part-curve.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let xml = saved_main_xml(&saved);
    assert!(xml.contains("live2DPartsOpacity:root"));
    assert!(xml.contains("KEY_PARTS_VISIBLE_ID\" idstr=\"root\""));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], model);
    let del = curve_delete(&session, "live2DPartsOpacity_root", "track-guid");
    result(&request(&mut session, del));
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"]["scenes"][0]["tracks"][0]["partOpacityCurves"].as_array().unwrap().len(), 2);
    assert_eq!(fs::read(&source).unwrap(), original);
    fs::remove_dir_all(directory).unwrap();
}

fn can3_part_storage(change: impl FnOnce(&str) -> String) -> String {
    let doc = roxmltree::Document::parse(CAN3_PART_OPACITY_XML).unwrap();
    let range = doc.descendants().find(|n| n.attribute("xs.id") == Some("part-a")).unwrap().range();
    let mut xml = CAN3_PART_OPACITY_XML.to_owned();
    xml.replace_range(range.clone(), &change(&CAN3_PART_OPACITY_XML[range]));
    xml
}

#[test]
fn can3_part_effect_registry_is_owned_by_the_same_track_and_kept_unchanged() {
    let directory = temp_dir();
    let manager = r#"<ICMvTrack_Linked xs.n="super"><ICMvTrack_Source xs.n="super"><CMvEffectManager xs.n="effectManager"><array xs.n="effectList" count="1" type="ICMvEffect"><CMvEffect_Live2DPartsVisible xs.ref="parts-effect"/></array></CMvEffectManager></ICMvTrack_Source></ICMvTrack_Linked>"#;
    let track_start = r#"<CMvTrack_Live2DModel_Source xs.id="track">"#;
    let xml = CAN3_PART_OPACITY_XML.replace(track_start, &format!("{track_start}{manager}"));
    let (mut session, path) = can3_key_fixture_session(&directory, &xml);
    let original = fs::read(&path).unwrap();
    for curve in ["live2DPartsOpacity_PartArmA", "live2DPartsOpacity:legacy-attribute"] {
        let mut call = can3_key_edit(&session, "live2d.animation.key.set", json!({"anchorFrame":0,"value":0.25}));
        call["curveId"] = json!(curve);
        result(&request(&mut session, call));
    }
    let expected = session.snapshot()["model"].clone();
    let saved = directory.join("registry.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    assert!(saved_main_xml(&saved).contains(manager));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], expected);
    assert_eq!(fs::read(&path).unwrap(), original);
    for changed in [
        manager.replace("count=\"1\"", "count=\"2\"").replace("<CMvEffect_Live2DPartsVisible xs.ref=\"parts-effect\"/>",
            "<CMvEffect_Live2DPartsVisible xs.ref=\"parts-effect\"/><CMvEffect_Live2DPartsVisible xs.ref=\"parts-effect\"/>"),
        manager.replace("xs.ref=\"parts-effect\"", "xs.ref=\"parts-effect\" future=\"keep\""),
        manager.replace("xs.n=\"effectManager\"", "xs.n=\"effectManager\" xs.id=\"shared-manager\""),
        manager.replace("xs.n=\"effectList\"", "xs.n=\"effectList\" xs.id=\"shared-effect-list\""),
        manager.replace(" count=\"1\"", ""),
        manager.replace("count=\"1\"", "count=\"2\""),
        manager.replace("<array ", "<unknown ").replace("</array>", "</unknown>"),
        manager.replace("type=\"ICMvEffect\"", "type=\"unknown\""),
        manager.replace("<CMvEffect_Live2DPartsVisible xs.ref=\"parts-effect\"/>", "")
            .replace("count=\"1\"", "count=\"0\"") + "<Opaque xs.ref=\"parts-effect\"/>",
    ] {
        let xml = CAN3_PART_OPACITY_XML.replace(track_start, &format!("{track_start}{changed}"));
        for curve in ["live2DPartsOpacity_PartArmA", "live2DPartsOpacity:legacy-attribute"] {
            let (mut session, path) = can3_key_fixture_session(&directory, &xml);
            let original = fs::read(&path).unwrap();
            let before = session.snapshot();
            let mut call = can3_key_edit(&session, "live2d.animation.key.set", json!({"anchorFrame":0,"value":0.25}));
            call["curveId"] = json!(curve);
            assert_eq!(request(&mut session, call)["succeeded"], false);
            assert_eq!(session.snapshot(), before);
            assert_eq!(fs::read(&path).unwrap(), original);
        }
    }
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_legacy_part_key_ownership_variants_and_refusals_are_atomic() {
    let directory = temp_dir();
    let legacy_edit = |session: &Session| {
        let mut call = can3_key_edit(session, "live2d.animation.key.set", json!({"anchorFrame":0,"value":0.25}));
        call["curveId"] = json!("live2DPartsOpacity:legacy-attribute");
        call
    };
    let doc = roxmltree::Document::parse(CAN3_PART_OPACITY_XML).unwrap();
    let members = doc.descendants().find(|n| n.has_tag_name("array") && n.attribute("xs.n") == Some("attrList")).unwrap();
    for (variant, list) in ["", r#"<array xs.n="attrList" count="3" type="ICMvAttr"><CMvAttrF xs.ref="part-a"/><CMvAttrF xs.ref="part-b"/><CMvAttrF xs.ref="part-legacy"/></array>"#].into_iter().enumerate() {
        let xml = CAN3_PART_OPACITY_XML.replace(&CAN3_PART_OPACITY_XML[members.range()], list);
        let (mut session, path) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(&path).unwrap();
        let call = legacy_edit(&session);
        result(&request(&mut session, call));
        let expected = session.snapshot()["model"].clone();
        let saved = directory.join(format!("variant-{variant}.can3"));
        result(&request(&mut session, json!({"op":"save","path":saved})));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(session.snapshot()["model"], expected);
        assert_eq!(fs::read(&path).unwrap(), original);
    }
    let legacy = doc.descendants().find(|n| n.attribute("xs.id") == Some("part-legacy")).unwrap();
    let legacy_xml = &CAN3_PART_OPACITY_XML[legacy.range()];
    let shared_sequence = legacy_xml.replace(r#"<CMutableSequence xs.n="valueData">"#,
        r#"<CMutableSequence xs.n="valueData" xs.id="shared-legacy-sequence">"#);
    for xml in [
        CAN3_PART_OPACITY_XML.replace("</shared>", "<Opaque xs.ref='part-legacy'/></shared>"),
        CAN3_PART_OPACITY_XML.replace("</shared>", "<Opaque xs.ref='parts-effect'/></shared>"),
        CAN3_PART_OPACITY_XML.replace(&CAN3_PART_OPACITY_XML[members.range()],
            r#"<array xs.n="attrList" count="2"><CMvAttrF xs.ref="part-legacy"/><CMvAttrF xs.ref="part-legacy"/></array>"#),
        CAN3_PART_OPACITY_XML.replace(&CAN3_PART_OPACITY_XML[members.range()],
            r#"<array xs.n="attrList" count="1"><CMvAttrF xs.ref="part-legacy" future="keep"/></array>"#),
        CAN3_PART_OPACITY_XML.replace(&CAN3_PART_OPACITY_XML[members.range()],
            r#"<array xs.n="attrList" count="0" xs.id="shared-members"/>"#),
        CAN3_PART_OPACITY_XML.replace(legacy_xml, &shared_sequence),
    ] {
        let (mut session, path) = can3_key_fixture_session(&directory, &xml);
        let original = fs::read(&path).unwrap();
        let before = session.snapshot();
        let call = legacy_edit(&session);
        assert_eq!(request(&mut session, call)["succeeded"], false);
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&path).unwrap(), original);
    }
    fs::remove_dir_all(directory).unwrap();
}

