#[test]
fn can3_part_opacity_value_set_is_one_undo_step_and_saves_inherited_caches() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_PART_OPACITY_XML);
    let original = fs::read(&source).unwrap();
    let before = session.snapshot();
    let edit = can3_part_edit(&session, "live2d.animation.key.set", json!({"anchorFrame":0,"value":0.25}));
    result(&request(&mut session, edit));
    let after = session.snapshot();
    assert_eq!(can3_part_curve(&session)["points"][0]["anchor"], json!({"frame":0,"value":0.25}));
    assert_eq!(after["revision"].as_u64(), before["revision"].as_u64().map(|r| r + 1));
    assert_eq!(after["history"]["count"].as_u64(), before["history"]["count"].as_u64().map(|n| n + 1));
    let mut only = after["model"].clone();
    only["scenes"][0]["tracks"][0]["partOpacityCurves"][0]["points"][0]["anchor"]["value"] = json!(0.0);
    assert_eq!(only, before["model"]);
    result(&request(&mut session, json!({"op":"undo"})));
    assert_eq!(session.snapshot()["model"], before["model"]);
    result(&request(&mut session, json!({"op":"redo"})));
    assert_eq!(session.snapshot()["model"], after["model"]);
    let saved = directory.join("part-opacity.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    assert!(saved_main_xml(&saved).contains("<d xs.n=\"curMin\">0.25</d>"));
    assert!(saved_main_xml(&saved).contains("keep-sequence-part-a"));
    let expected_xml = can3_part_storage(|xml| xml
        .replacen("<d xs.n=\"doubleValue\">0</d>", "<d xs.n=\"doubleValue\">0.25</d>", 1)
        .replacen("<d xs.n=\"curMin\">0.0000</d>", "<d xs.n=\"curMin\">0.25</d>", 1));
    assert_eq!(saved_main_xml(&saved), expected_xml);
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], after["model"]);
    assert_eq!(fs::read(&source).unwrap(), original);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_part_opacity_all_key_operations_preserve_other_channels_and_reopen() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_PART_OPACITY_XML);
    let original = fs::read(&source).unwrap();
    for (op, fields) in [
        ("live2d.animation.key.set", json!({"anchorFrame":0,"value":0.25})),
        ("live2d.animation.key.add", json!({"anchorFrame":5,"value":0.6})),
        ("live2d.animation.handle.set", json!({"anchorFrame":5,"side":"next","frame":6.5,"value":0.7})),
        ("live2d.animation.curve_type.set", json!({"anchorFrame":5,"type":"BEZIER"})),
        ("live2d.animation.key.delete", json!({"anchorFrame":0})),
    ] {
        let before = session.snapshot();
        let edit = can3_part_edit(&session, op, fields);
        result(&request(&mut session, edit));
        let after = session.snapshot();
        assert_eq!(after["revision"].as_u64().unwrap(), before["revision"].as_u64().unwrap() + 1, "{op}");
        assert_eq!(after["history"]["count"].as_u64().unwrap(), before["history"]["count"].as_u64().unwrap() + 1, "{op}");
        let mut other = after["model"].clone();
        other["scenes"][0]["tracks"][0]["partOpacityCurves"][0] =
            before["model"]["scenes"][0]["tracks"][0]["partOpacityCurves"][0].clone();
        assert_eq!(other, before["model"], "{op}");
        result(&request(&mut session, json!({"op":"undo"})));
        assert_eq!(session.snapshot()["model"], before["model"]);
        result(&request(&mut session, json!({"op":"redo"})));
        assert_eq!(session.snapshot()["model"], after["model"]);
    }
    let curve = can3_part_curve(&session);
    assert_eq!(curve["points"].as_array().unwrap().iter().map(|p| p["anchor"]["frame"].as_i64().unwrap()).collect::<Vec<_>>(), [5,10]);
    assert_eq!(curve["curveTypes"], json!(["BEZIER","LINEAR"]));
    assert_eq!(curve["points"][0]["next"], json!({"frame":6.5,"integerFrame":5,"value":0.7,"positionOptimized":false}));
    let model = session.snapshot()["model"].clone();
    let saved = directory.join("edited-part.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], model);
    assert_eq!(fs::read(&source).unwrap(), original);
    for frame in [5,10] {
        let edit = can3_part_edit(&session, "live2d.animation.key.delete", json!({"anchorFrame":frame}));
        result(&request(&mut session, edit));
    }
    assert_eq!(can3_part_curve(&session)["points"], json!([]));
    assert_eq!(can3_part_curve(&session)["curveTypes"], json!([]));
    let edit = can3_part_edit(&session, "live2d.animation.key.add", json!({"anchorFrame":-5,"value":0.4,"type":"STEP"}));
    result(&request(&mut session, edit));
    let model = session.snapshot()["model"].clone();
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(session.snapshot()["model"], model);
    assert_eq!(can3_part_curve(&session)["curveTypes"], json!(["STEP"]));
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_part_opacity_noops_and_refusals_preserve_the_entire_session_and_file() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_PART_OPACITY_XML);
    for (op, fields) in [
        ("live2d.animation.key.set", json!({"anchorFrame":0,"value":0})),
        ("live2d.animation.handle.set", json!({"anchorFrame":0,"side":"next","frame":3,"value":0.5})),
        ("live2d.animation.curve_type.set", json!({"anchorFrame":0,"type":"LINEAR"})),
    ] {
        let before = session.snapshot();
        let edit = can3_part_edit(&session, op, fields);
        result(&request(&mut session, edit));
        assert_eq!(session.snapshot(), before, "{op}");
    }
    let original = fs::read(&source).unwrap();
    for (op, fields) in [
        ("live2d.animation.key.set", json!({"anchorFrame":0,"value":0.25,"expectedRevision":0})),
        ("live2d.animation.key.add", json!({"anchorFrame":0,"value":0.25})),
        ("live2d.animation.key.delete", json!({"anchorFrame":50})),
        ("live2d.animation.handle.set", json!({"anchorFrame":0,"side":"bad","value":0.25})),
        ("live2d.animation.curve_type.set", json!({"anchorFrame":0,"type":"bad"})),
        ("live2d.animation.key.set", json!({"anchorFrame":0,"value":0.25,"curveId":"live2DPartsOpacity:missing-legacy-attribute"})),
    ] {
        let before = session.snapshot();
        let mut edit = can3_part_edit(&session, op, fields.clone());
        for key in ["expectedRevision","curveId"] {
            if let Some(value) = fields.get(key) { edit[key] = value.clone(); }
        }
        assert_eq!(request(&mut session, edit)["succeeded"], false, "{op}");
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&source).unwrap(), original);
    }
    fs::remove_dir_all(directory).unwrap();
}

