#[test]
fn can3_key_structure_accumulated_edits_save_once_and_reopen() {
    let directory = temp_dir();
    let (mut session, _) = can3_key_fixture_session(&directory, CAN3_KEY_EDITOR_XML);
    let saved = directory.join("grown.can3");
    let edit = can3_key_edit(&session, "live2d.animation.key.add", json!({"anchorFrame":5,"value":2}));
    result(&request(&mut session, edit));
    let edit = can3_key_edit(&session, "live2d.animation.key.set",
        json!({"anchorFrame":5,"value":1.2345678901234567}));
    result(&request(&mut session, edit));
    let edit = can3_key_edit(&session, "live2d.animation.handle.set",
        json!({"anchorFrame":5,"side":"next","frame":6.5,"value":1.75}));
    result(&request(&mut session, edit));
    let edit = can3_key_edit(&session, "live2d.animation.key.add",
        json!({"anchorFrame":7,"value":0.75,"type":"STEP"}));
    result(&request(&mut session, edit));
    assert_eq!(can3_frames(&session), [0, 5, 7, 10]);
    assert_eq!(can3_curve(&session)["curveTypes"], json!(["LINEAR", "LINEAR", "STEP", "LINEAR"]));
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(can3_frames(&session), [0, 5, 7, 10]);
    assert_eq!(can3_curve(&session)["curveTypes"], json!(["LINEAR", "LINEAR", "STEP", "LINEAR"]));
    let point = &can3_curve(&session)["points"][1];
    assert_eq!(point["anchor"], json!({"frame":5,"value":1.2345678901234567}));
    assert_eq!(point["corner"], true);
    assert_eq!(point["previous"],
        json!({"frame":5.0,"integerFrame":5,"value":2.0,"positionOptimized":false}));
    assert_eq!(point["next"],
        json!({"frame":6.5,"integerFrame":5,"value":1.75,"positionOptimized":false}));
    assert_eq!(can3_curve(&session)["points"][2]["anchor"], json!({"frame":7,"value":0.75}));
    fs::remove_dir_all(directory).unwrap();
}

