#[test]
fn can3_key_structure_empties_then_refills_with_template_caches() {
    let directory = temp_dir();
    let (mut session, _) = can3_key_fixture_session(&directory, CAN3_KEY_EDITOR_XML);
    let empty = directory.join("empty.can3");
    let refill = directory.join("refill.can3");
    let edit = can3_key_edit(&session, "live2d.animation.key.delete", json!({"anchorFrame":0}));
    result(&request(&mut session, edit));
    let edit = can3_key_edit(&session, "live2d.animation.key.delete", json!({"anchorFrame":10}));
    result(&request(&mut session, edit));
    assert_eq!(can3_curve(&session)["points"], json!([]));
    assert_eq!(can3_curve(&session)["curveTypes"], json!([]));
    result(&request(&mut session, json!({"op":"save","path":empty})));
    let empty_xml = saved_main_xml(&empty);
    assert!(empty_xml.contains(r#"<d xs.n="curMin">0.0000</d>"#), "{empty_xml}");
    assert!(empty_xml.contains(r#"<d xs.n="curMax">1.0000</d>"#), "{empty_xml}");
    let edit = can3_key_edit(&session, "live2d.animation.key.add", json!({"anchorFrame":-5,"value":-0.25}));
    result(&request(&mut session, edit));
    assert_eq!(can3_frames(&session), [-5]);
    result(&request(&mut session, json!({"op":"save","path":refill})));
    let refilled = saved_main_xml(&refill);
    assert!(refilled.contains(r#"<d xs.n="curMin">-0.25</d>"#), "{refilled}");
    assert!(refilled.contains(r#"<d xs.n="curMax">-0.25</d>"#), "{refilled}");
    result(&request(&mut session, json!({"op":"undo"})));
    assert_eq!(can3_curve(&session)["points"], json!([]));
    result(&request(&mut session, json!({"op":"undo"})));
    assert_eq!(can3_frames(&session), [10]);
    result(&request(&mut session, json!({"op":"redo"})));
    assert_eq!(can3_curve(&session)["points"], json!([]));
    result(&request(&mut session, json!({"op":"redo"})));
    assert_eq!(can3_frames(&session), [-5]);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_key_structure_inserts_into_originally_empty_self_closing_lists() {
    let directory = temp_dir();
    let mut xml = CAN3_KEY_EDITOR_XML.to_owned();
    let open = xml.find("<array xs.n=\"points\"").unwrap();
    let close = xml.find("</array>").unwrap() + "</array>".len();
    xml.replace_range(open..close, "<array xs.n=\"points\" count=\"0\" type=\"CBezierPt\"/>");
    let tstart = xml.find("<carray_list xs.n=\"curveTypes\"").unwrap();
    let tend = xml[tstart..].find("</carray_list>").unwrap() + tstart + "</carray_list>".len();
    xml.replace_range(tstart..tend, "<carray_list xs.n=\"curveTypes\" count=\"0\"/>");
    let (mut session, _) = can3_key_fixture_session(&directory, &xml);
    assert_eq!(can3_curve(&session)["points"], json!([]));
    let saved = directory.join("empty-source.can3");
    let edit = can3_key_edit(&session, "live2d.animation.key.add", json!({"anchorFrame":-5,"value":-0.25}));
    result(&request(&mut session, edit));
    assert_eq!(can3_frames(&session), [-5]);
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let xml_saved = saved_main_xml(&saved);
    assert!(xml_saved.contains(r#"count="1""#), "{xml_saved}");
    assert!(xml_saved.contains(r#"<d xs.n="curMin">-0.25</d>"#), "{xml_saved}");
    assert!(xml_saved.contains(r#"<d xs.n="curMax">-0.25</d>"#), "{xml_saved}");
    assert!(xml_saved.contains("keep-root &amp; 0.1234500"), "{xml_saved}");
    result(&request(&mut session, json!({"op":"open","path":saved})));
    let point = &can3_curve(&session)["points"][0];
    assert_eq!(point["anchor"], json!({"frame":-5,"value":-0.25}));
    assert_eq!(point["corner"], true);
    for side in ["previous", "next"] {
        assert_eq!(point[side],
            json!({"frame":-5.0,"integerFrame":-5,"value":-0.25,"positionOptimized":false}), "{side}");
    }
    assert_eq!(can3_curve(&session)["curveTypes"], json!(["LINEAR"]));
    fs::remove_dir_all(directory).unwrap();
}

