#[test]
fn can3_key_structure_refusals_leave_the_whole_document_unchanged() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_KEY_EDITOR_XML);
    let original_bytes = fs::read(&source).unwrap();
    for (op, fields, message) in [
        ("live2d.animation.key.add", json!({"anchorFrame":5,"value":2,"bogus":1}), "unknown key"),
        ("live2d.animation.key.add", json!({"anchorFrame":5}), "value"),
        ("live2d.animation.key.add", json!({"anchorFrame":5,"value":2,"type":null}), "type"),
        ("live2d.animation.key.add", json!({"anchorFrame":5,"value":2,"type":"smooth"}), "type"),
        ("live2d.animation.key.add", json!({"anchorFrame":5,"value":"x"}), "finite"),
        ("live2d.animation.key.add", json!({"anchorFrame":5.5,"value":2}), "integer"),
        ("live2d.animation.key.add", json!({"anchorFrame":2147483648_i64,"value":2}), "32-bit"),
        ("live2d.animation.key.add", json!({"anchorFrame":0,"value":2}), "already"),
        ("live2d.animation.key.delete", json!({"anchorFrame":5}), "was not found"),
        ("live2d.animation.key.delete", json!({"anchorFrame":0.5}), "integer"),
        ("live2d.animation.key.add", json!({"sceneGuid":"no-such","anchorFrame":5,"value":2}), "was not found"),
        ("live2d.animation.key.add", json!({"trackGuid":"no-such","anchorFrame":5,"value":2}), "was not found"),
        ("live2d.animation.key.add", json!({"curveId":"no-such","anchorFrame":5,"value":2}), "was not found"),
    ] {
        let before = session.snapshot();
        let history = result(&request(&mut session, json!({"op":"history.summary"}))).clone();
        let edit = can3_key_edit(&session, op, fields.clone());
        let response = request(&mut session, edit);
        assert_eq!(response["succeeded"], false, "{op} {fields}");
        assert!(response["message"].as_str().unwrap().contains(message), "{response}");
        assert_eq!(session.snapshot(), before, "{op} {fields}");
        assert_eq!(result(&request(&mut session, json!({"op":"history.summary"}))).clone(), history);
        assert_eq!(fs::read(&source).unwrap(), original_bytes);
    }
    let before = session.snapshot();
    let stale = json!({"op":"live2d.animation.key.add","sceneGuid":"scene-guid","trackGuid":"track-guid",
        "curveId":"live2dParam_ParamTest","anchorFrame":5,"value":2,"expectedRevision":999});
    let response = request(&mut session, stale);
    assert_eq!(response["succeeded"], false);
    assert_eq!(session.snapshot(), before);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_key_structure_refuses_shared_or_referenced_storage() {
    let directory = temp_dir();
    let source = directory.join("keys.can3");
    let mut session = Session::new();
    let point0 = r#"<CBezierPt>
            <CSeqPt xs.n="anchor"><i xs.n="pos">0</i><d xs.n="doubleValue">0</d><b xs.n="isCorner">false</b></CSeqPt>
            <CBezierCtrlPt xs.n="prev"><i xs.n="pos">-7</i><d xs.n="posF">-2</d><d xs.n="doubleValue">-0.5</d><b xs.n="isPosOptimized">true</b></CBezierCtrlPt>
            <CBezierCtrlPt xs.n="next"><i xs.n="pos">7</i><d xs.n="posF">3</d><d xs.n="doubleValue">0.5</d><b xs.n="isPosOptimized">true</b></CBezierCtrlPt>
            <s xs.n="futurePointData">opaque-key-data &amp; 0.12345678901234567890</s>
          </CBezierPt>"#;
    let point10 = r#"<CBezierPt>
            <CSeqPt xs.n="anchor"><i xs.n="pos">10</i><d xs.n="doubleValue">1</d><b xs.n="isCorner">true</b></CSeqPt>
            <CBezierCtrlPt xs.n="prev"><i xs.n="pos">10</i><d xs.n="posF">10</d><d xs.n="doubleValue">1</d><b xs.n="isPosOptimized">false</b></CBezierCtrlPt>
            <CBezierCtrlPt xs.n="next"><i xs.n="pos">10</i><d xs.n="posF">10</d><d xs.n="doubleValue">1</d><b xs.n="isPosOptimized">false</b></CBezierCtrlPt>
          </CBezierPt>"#;
    for (xml, op, fields, message) in [
        (CAN3_KEY_EDITOR_XML.replace(r#"<CMutableSequence xs.n="valueData">"#,
            r#"<CMutableSequence xs.n="valueData" xs.id="sequence">"#),
            "live2d.animation.key.add", json!({"anchorFrame":5,"value":2}), "shared"),
        (CAN3_KEY_EDITOR_XML.replace(point0, r#"<CBezierPt xs.ref="point0"/>"#)
            .replace("</shared>",
                &(point0.replace("<CBezierPt>", r#"<CBezierPt xs.id="point0">"#) + "</shared>")),
            "live2d.animation.key.add", json!({"anchorFrame":5,"value":2}), "shared"),
        (CAN3_KEY_EDITOR_XML.replace(r#"<s xs.n="futurePointData">opaque-key-data &amp; 0.12345678901234567890</s>"#,
            r#"<s xs.n="futurePointData" xs.id="opaque">opaque-key-data &amp; 0.12345678901234567890</s>"#),
            "live2d.animation.key.delete", json!({"anchorFrame":0}), "shared"),
        (CAN3_KEY_EDITOR_XML.replace(r#"<d xs.n="curMax">1.0000</d>"#, r#"<d xs.n="curMax">2.0000</d>"#),
            "live2d.animation.key.add", json!({"anchorFrame":5,"value":2}), "cache differs"),
        (CAN3_KEY_EDITOR_XML.replace(r#"<d xs.n="curMin">0.0000</d>"#, ""),
            "live2d.animation.key.add", json!({"anchorFrame":5,"value":2}), "curMin"),
        (CAN3_KEY_EDITOR_XML.replacen(r#"<CCurveType v="LINEAR"/>"#, r#"<CCurveType v="BOUNCE"/>"#, 1),
            "live2d.animation.key.add", json!({"anchorFrame":5,"value":2}), "type"),
        (CAN3_KEY_EDITOR_XML.replace(&format!("{point0}\n          {point10}"),
            &format!("{point10}\n          {point0}")),
            "live2d.animation.key.add", json!({"anchorFrame":5,"value":2}), "increasing"),
    ] {
        fs::write(&source, authoring_bytes(&xml)).unwrap();
        result(&request(&mut session, json!({"op":"open","path":source})));
        let before = session.snapshot();
        let edit = can3_key_edit(&session, op, fields.clone());
        let response = request(&mut session, edit);
        assert_eq!(response["succeeded"], false, "{op} {fields}: {response}");
        assert!(response["message"].as_str().unwrap().contains(message), "{response}");
        assert_eq!(session.snapshot(), before, "{op} {fields}");
    }
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_key_structure_preserves_unknown_count_attribute_spelling() {
    for (index, (source_xml, marker)) in [
        (CAN3_KEY_EDITOR_XML.replace(r#"<array xs.n="points" count="2""#,
            r#"<array xs.n="points" discount="999" count="2""#), "discount=\"999\""),
        (CAN3_KEY_EDITOR_XML.replace(r#"<array xs.n="points" count="2""#,
            r#"<array xs.n="points" count = '2'"#), "count = '3'"),
    ]
    .into_iter()
    .enumerate()
    {
        let directory = temp_dir();
        let (mut session, _) = can3_key_fixture_session(&directory, &source_xml);
        let saved = directory.join(format!("variant-{index}.can3"));
        let edit = can3_key_edit(&session, "live2d.animation.key.add", json!({"anchorFrame":5,"value":2}));
        result(&request(&mut session, edit));
        result(&request(&mut session, json!({"op":"save","path":saved})));
        let saved_xml = saved_main_xml(&saved);
        assert!(saved_xml.contains(marker), "{saved_xml}");
        result(&request(&mut session, json!({"op":"open","path":saved})));
        assert_eq!(can3_frames(&session), [0, 5, 10]);
        assert_eq!(can3_curve(&session)["curveTypes"], json!(["LINEAR", "LINEAR", "LINEAR"]));
        fs::remove_dir_all(directory).unwrap();
    }
}

#[test]
fn can3_key_structure_delete_refuses_a_merged_invalid_segment() {
    let directory = temp_dir();
    let xml = CAN3_KEY_EDITOR_XML
        .replacen(r#"<CCurveType v="LINEAR"/>"#, r#"<CCurveType v="SMOOTH"/>"#, 1);
    let (mut session, source) = can3_key_fixture_session(&directory, &xml);
    let source_bytes = fs::read(&source).unwrap();
    let edit = can3_key_edit(&session, "live2d.animation.key.add", json!({"anchorFrame":5,"value":0.5}));
    result(&request(&mut session, edit));
    assert_eq!(can3_frames(&session), [0, 5, 10]);
    assert_eq!(can3_curve(&session)["curveTypes"], json!(["SMOOTH", "LINEAR", "LINEAR"]));
    let edit = can3_key_edit(&session, "live2d.animation.handle.set",
        json!({"anchorFrame":10,"side":"previous","frame":2.0}));
    result(&request(&mut session, edit));
    let before = session.snapshot();
    let history = result(&request(&mut session, json!({"op":"history.summary"}))).clone();
    let edit = can3_key_edit(&session, "live2d.animation.key.delete", json!({"anchorFrame":5}));
    let response = request(&mut session, edit);
    assert_eq!(response["succeeded"], false, "{response}");
    assert!(response["message"].as_str().unwrap().contains("out of frame order"), "{response}");
    assert_eq!(session.snapshot(), before);
    assert_eq!(result(&request(&mut session, json!({"op":"history.summary"}))).clone(), history);
    assert_eq!(fs::read(&source).unwrap(), source_bytes);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_curve_add_reads_parameter_identity() {
    let directory = temp_dir();
    let cmo3 = curve_cmo3(&directory);
    let mut source_session = Session::default();
    let scene = result(&request(&mut source_session,
        json!({"op":"live2d.authoring.read","path":cmo3}))).clone();
    let parameter = |id: &str| {
        scene["parameters"].as_array().unwrap().iter()
            .find(|p| p["id"].as_str() == Some(id)).cloned().unwrap()
    };
    assert_eq!(parameter("ParamNew")["guid"], json!("new-parameter-guid"));
    assert_eq!(parameter("ParamNew")["minimum"], json!(-2.0));
    assert_eq!(parameter("ParamNew")["maximum"], json!(2.0));
    assert_eq!(parameter("ParamNew")["default"], json!(0.25));
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_CURVE_EDITOR_XML);
    let _ = source;
    let before = session.snapshot()["revision"].clone();
    { let call = curve_add(&session, &cmo3, "ParamNew", "track-guid"); result(&request(&mut session, call)); }
    let snap = session.snapshot();
    assert_eq!(snap["revision"].as_u64().unwrap(), before.as_u64().unwrap() + 1);
    let curves = &snap["model"]["scenes"][0]["tracks"][0]["parameterCurves"];
    assert_eq!(curves.as_array().unwrap().len(), 2);
    let curve = &curves[1];
    assert_eq!(curve["id"], json!("live2dParam_ParamNew"));
    assert_eq!(curve["parameterId"], json!("ParamNew"));
    assert_eq!(curve["parameterGuid"], json!("new-parameter-guid"));
    assert_eq!(curve["sourceParameter"], json!({"type":"CParameterId","value":"ParamNew"}));
    assert_eq!(curve["range"], json!([-2.0, 2.0]));
    assert_eq!(curve["points"], json!([]));
    assert_eq!(curve["curveTypes"], json!([]));
    assert_eq!(curve["baseValue"], json!(0.25));
    assert!(curves[0].get("baseValue").is_none(), "{}", curves[0]);
    fs::remove_dir_all(directory).unwrap();
}

