#[test]
fn can3_curve_delete_first_edit_second_saves() {
    let directory = temp_dir();
    let cmo3 = curve_cmo3(&directory);
    let (mut session, _) = can3_key_fixture_session(&directory, CAN3_CURVE_EDITOR_XML);
    { let call = curve_add(&session, &cmo3, "ParamNew", "track-guid"); result(&request(&mut session, call)); }
    { let call = curve_delete(&session, "live2dParam_ParamTest", "track-guid"); result(&request(&mut session, call)); }
    let edit = can3_key_edit(&session, "live2d.animation.key.add",
        json!({"anchorFrame":5,"value":0.5,"curveId":"live2dParam_ParamNew"}));
    result(&request(&mut session, edit));
    let saved = directory.join("saved.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let xml = saved_main_xml(&saved);
    assert!(!xml.contains(r#"xs.id="attr""#), "test curve definition should be removed");
    assert!(xml.contains(r#"xs.id="attr-t2""#), "track 2 curve definition stays");
    assert!(xml.contains(r#"xs.id="attr-opaque""#));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(curve_ids(&session, 0), vec!["live2dParam_ParamNew".to_string()]);
    let curve = &session.snapshot()["model"]["scenes"][0]["tracks"][0]["parameterCurves"][0];
    assert_eq!(curve["points"].as_array().unwrap().len(), 1);
    assert_eq!(curve["points"][0]["anchor"]["value"], json!(0.5));
    assert!(xml.contains(r#"xs.ref="attr-opaque"/>"#));
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_curve_readd_orders_new_first_and_keeps_literal_count() {
    let directory = temp_dir();
    let cmo3 = curve_cmo3(&directory);
    let (mut session, _) = can3_key_fixture_session(&directory, CAN3_CURVE_EDITOR_XML);
    { let call = curve_delete(&session, "live2dParam_ParamTest", "track-guid"); result(&request(&mut session, call)); }
    { let call = curve_add(&session, &cmo3, "ParamNew", "track-guid"); result(&request(&mut session, call)); }
    { let call = curve_add(&session, &cmo3, "ParamTest", "track-guid");
    result(&request(&mut session, call)); }
    let saved = directory.join("saved.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    let xml = saved_main_xml(&saved);
    let new_ref = r#"<CMvAttrF xs.ref="soul2d-curve-track-guid-live2dParam_ParamNew"/>"#;
    let test_ref = r#"<CMvAttrF xs.ref="attr"/>"#;
    let opaque_ref = r#"<CMvAttrF xs.ref="attr-opaque"/>"#;
    let at = |needle: &str| xml.find(needle).unwrap_or(usize::MAX);
    assert!(at(new_ref) < at(test_ref) && at(test_ref) < at(opaque_ref),
        "expected New ref before Test ref before opaque entry: {xml}");
    result(&request(&mut session, json!({"op":"open","path":saved})));
    assert_eq!(curve_ids(&session, 0),
        vec!["live2dParam_ParamNew".to_string(), "live2dParam_ParamTest".to_string()]);
    let test = &session.snapshot()["model"]["scenes"][0]["tracks"][0]["parameterCurves"][1];
    assert_eq!(test["points"], json!([]));
    assert_eq!(test["range"], json!([-1.0, 1.0]));
    assert_eq!(test["parameterGuid"], json!("parameter-guid"));
    // The original stored no baseValue and the re-added curve keeps it so; the new one takes the default.
    assert!(test.get("baseValue").is_none(), "{test}");
    assert_eq!(session.snapshot()["model"]["scenes"][0]["tracks"][0]["parameterCurves"][0]["baseValue"], json!(0.25));
    assert!(xml.contains("discount=\"999\""));
    assert!(xml.contains("futureCurveData"));
    fs::remove_dir_all(directory).unwrap();
}

