#[test]
fn can3_track_invalid_requests_are_atomic() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_CURVE_EDITOR_XML);
    let file = fs::read(&source).unwrap();
    let mut refuses = |mut call: Value| {
        let before = session.snapshot();
        call["expectedRevision"] = before["revision"].clone();
        let response = request(&mut session, call);
        assert_eq!(response["succeeded"], json!(false), "{response}");
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&source).unwrap(), file);
    };
    refuses(json!({"op":"live2d.animation.track.add","sceneGuid":"none","resourceGuid":"res-guid","name":"x"}));
    refuses(json!({"op":"live2d.animation.track.add","sceneGuid":"scene-guid","resourceGuid":"none","name":"x"}));
    refuses(json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid","trackGuid":"none"}));
    refuses(json!({"op":"live2d.animation.track.add","sceneGuid":"scene-guid","resourceGuid":"res-guid","name":"x","bogus":1}));
    refuses(json!({"op":"live2d.animation.track.delete","sceneGuid":"scene-guid","trackGuid":"track-guid","extra":true}));
    refuses(json!({"op":"live2d.animation.track.add","sceneGuid":"scene-guid","resourceGuid":"res-guid","name":"bad\u{0}name"}));
    refuses(json!({"op":"live2d.animation.track.add","sceneGuid":"scene-guid","resourceGuid":"res-guid","name":null}));
    fs::remove_dir_all(directory).unwrap();
}

