#[test]
fn can3_track_shared_or_inherited_set_and_nonbare_owner_refuse() {
    let directory = temp_dir();
    let effect_start = CAN3_CURVE_EDITOR_XML
        .find(r#"<CMvKeyParamEffect xs.n="keyParamEffect">"#).unwrap();
    let effect_end = CAN3_CURVE_EDITOR_XML[effect_start..]
        .find("</CMvKeyParamEffect>").unwrap() + effect_start + "</CMvKeyParamEffect>".len();
    let effect = &CAN3_CURVE_EDITOR_XML[effect_start..effect_end];
    for (label, variant) in [
        ("shared-set", CAN3_CURVE_EDITOR_XML
            .replace(
                r#"<CTrackSourceSet xs.n="trackSourceSet">
        <carray_list xs.n="_sources" count="2"><CMvTrack_Live2DModel_Source xs.ref="track"/><CMvTrack_Live2DModel_Source xs.ref="track2"/></carray_list>
      </CTrackSourceSet>"#,
                r#"<CTrackSourceSet xs.n="trackSourceSet" xs.ref="shared-set"/>"#,
            )
            .replace(
                "</shared>",
                r#"<CTrackSourceSet xs.id="shared-set"><carray_list xs.n="_sources" count="2"><CMvTrack_Live2DModel_Source xs.ref="track"/><CMvTrack_Live2DModel_Source xs.ref="track2"/></carray_list></CTrackSourceSet></shared>"#,
            )),
        ("inherited-effect", CAN3_CURVE_EDITOR_XML.replace(
            effect,
            r#"<CMvKeyParamEffect xs.n="keyParamEffect"><CMvKeyParamEffect xs.n="super" xs.ref="attr"/><CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/><carray_list xs.n="attrList" count='1'><CMvAttrF xs.ref="attr"/></carray_list></CMvKeyParamEffect>"#,
        )),
        ("nonbare-owner", CAN3_CURVE_EDITOR_XML.replace(
            r#"<CMvTrack_Live2DModel_Source xs.ref="track"/>"#,
            r#"<CMvTrack_Live2DModel_Source xs.ref="track" extra="1"/>"#,
        )),
        ("nested-id", CAN3_CURVE_EDITOR_XML.replacen(
            r#"<i xs.n="start">0</i><i xs.n="internalOffset">0</i><i xs.n="duration">120</i>
    </CMvTrack_Live2DModel_Source>"#,
            r#"<i xs.n="start">0</i><i xs.n="internalOffset">0</i><i xs.n="duration">120</i><Nested xs.id="nested"/>
    </CMvTrack_Live2DModel_Source>"#,
            1,
        )),
    ] {
        let sub = directory.join(label);
        fs::create_dir(&sub).unwrap();
        let wrapped = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            can3_key_fixture_session(&sub, &variant)
        }));
        let (mut session, source) = match wrapped {
            Ok(pair) => pair,
            Err(payload) => panic!("{label} failed to open: {payload:?}"),
        };
        let file = fs::read(&source).unwrap();
        let before = session.snapshot();
        let call = track_delete(&session, "scene-guid", "track-guid");
        let response = request(&mut session, call);
        assert_eq!(response["succeeded"], json!(false), "{label}: {response}");
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&source).unwrap(), file);
        fs::remove_dir_all(sub).unwrap();
    }
}

