#[test]
fn can3_scene_add_populate_delete_cancellation() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_SCENE_EDITOR_XML);
    let original = fs::read(&source).unwrap();
    let revision = session.snapshot()["revision"].clone();
    let response = request(&mut session, json!({
        "op":"live2d.animation.scene.add","name":"Temp","fps":30.0,
        "durationFrames":45,"expectedRevision":revision}));
    let guid = response["result"]["sceneGuid"].as_str().unwrap().to_owned();
    {
        let call = track_add(&session, &guid, "res-guid", "T");
        result(&request(&mut session, call));
    }
    let track_guid = session.snapshot()["model"]["scenes"][2]["tracks"][0]["guid"]
        .as_str().unwrap().to_owned();
    let cmo3 = curve_cmo3(&directory);
    {
        let call = json!({"op":"live2d.animation.curve.add","sceneGuid":guid,
            "trackGuid":track_guid,"modelPath":cmo3,"parameterId":"ParamTest",
            "expectedRevision":session.snapshot()["revision"]});
        result(&request(&mut session, call));
    }
    {
        let call = can3_key_edit(&session, "live2d.animation.key.add",
            json!({"sceneGuid":guid,"trackGuid":track_guid,
                "curveId":"live2dParam_ParamTest","anchorFrame":4,"value":0.5,"type":"BEZIER"}));
        result(&request(&mut session, call));
    }
    {
        let call = can3_key_edit(&session, "live2d.animation.handle.set",
            json!({"sceneGuid":guid,"trackGuid":track_guid,
                "curveId":"live2dParam_ParamTest","anchorFrame":4,"side":"next","frame":2.0,"value":1.0}));
        result(&request(&mut session, call));
    }
    {
        let call = scene_delete(&session, &guid);
        result(&request(&mut session, call));
    }
    result(&request(&mut session, json!({"op":"undo"})));
    assert_eq!(session.snapshot()["model"]["scenes"].as_array().unwrap().len(), 3);
    result(&request(&mut session, json!({"op":"redo"})));
    assert_eq!(session.snapshot()["model"]["scenes"].as_array().unwrap().len(), 2);
    result(&request(&mut session, json!({"op":"save","path":source})));
    assert_eq!(fs::read(&source).unwrap(), original);
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_scene_delete_discards_pending_children() {
    let directory = temp_dir();
    let cmo3 = curve_cmo3(&directory);
    let (mut session, _) = can3_key_fixture_session(&directory, CAN3_SCENE_EDITOR_XML);
    {
        let call = can3_key_edit(&session, "live2d.animation.key.set",
            json!({"sceneGuid":"scene-guid","trackGuid":"track-guid",
                "curveId":"live2dParam_ParamTest","anchorFrame":0,"value":0.9}));
        result(&request(&mut session, call));
    }
    {
        let call = curve_add(&session, &cmo3, "ParamNew", "track-guid");
        result(&request(&mut session, call));
    }
    {
        let call = track_delete(&session, "scene-guid", "track2-guid");
        result(&request(&mut session, call));
    }
    {
        let call = track_add(&session, "scene-guid", "res-guid", "Pending");
        result(&request(&mut session, call));
    }
    let pending_track = session.snapshot()["model"]["scenes"][0]["tracks"]
        .as_array().unwrap().last().unwrap()["guid"].as_str().unwrap().to_owned();
    {
        let call = json!({"op":"live2d.animation.curve.add","sceneGuid":"scene-guid",
            "trackGuid":pending_track,"modelPath":cmo3,"parameterId":"ParamNew",
            "expectedRevision":session.snapshot()["revision"]});
        result(&request(&mut session, call));
    }
    {
        let call = can3_key_edit(&session, "live2d.animation.key.add",
            json!({"sceneGuid":"scene-guid","trackGuid":pending_track,
                "curveId":"live2dParam_ParamNew","anchorFrame":1,"value":0.25}));
        result(&request(&mut session, call));
    }
    {
        let call = scene_delete(&session, "scene-guid");
        result(&request(&mut session, call));
    }
    let saved = directory.join("saved.can3");
    result(&request(&mut session, json!({"op":"save","path":saved})));
    result(&request(&mut session, json!({"op":"open","path":saved})));
    let scenes = &session.snapshot()["model"]["scenes"];
    assert_eq!(scenes.as_array().unwrap().len(), 1);
    let xml = saved_main_xml(&saved);
    assert!(!xml.contains("ParamNew"));
    assert!(xml.contains("scene-kept-guid"));
    fs::remove_dir_all(directory).unwrap();
}

#[test]
fn can3_scene_delete_invalid_is_atomic() {
    let directory = temp_dir();
    let (mut session, source) = can3_key_fixture_session(&directory, CAN3_SCENE_EDITOR_XML);
    let file = fs::read(&source).unwrap();
    let refuses = |session: &mut Session, call: Value| {
        let before = session.snapshot();
        let response = request(session, call);
        assert_eq!(response["succeeded"], json!(false), "{response}");
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&source).unwrap(), file);
    };
    let revision = session.snapshot()["revision"].clone();
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":"none","expectedRevision":revision}));
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":"","expectedRevision":revision}));
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":null,"expectedRevision":revision}));
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":42,"expectedRevision":revision}));
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":"scene-guid","extra":1,"expectedRevision":revision}));
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":"scene-guid"}));
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":"scene-guid","expectedRevision":null}));
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":"scene-guid","expectedRevision":-1}));
    refuses(&mut session, json!({"op":"live2d.animation.scene.delete","sceneGuid":"scene-guid","expectedRevision":0}));
    let mut noncan3 = Session::new();
    let response = request(&mut noncan3, json!({
        "op":"live2d.animation.scene.delete","sceneGuid":"x","expectedRevision":0}));
    assert_eq!(response["succeeded"], json!(false));
    fs::remove_dir_all(directory).unwrap();
}

