#[test]
fn can3_scene_delete_unsafe_storage_is_atomic() {
    let directory = temp_dir();
    let name_field = r#"<s xs.n="sceneName">Scene</s>"#;
    for (label, variant) in [
        ("shared-scenes", CAN3_SCENE_EDITOR_XML
            .replace(r#"<carray_list xs.n="_scenes" count='0002' discount="999">"#,
                     r#"<carray_list xs.n="_scenes" xs.ref="shared-list"/>"#)
            .replace("</shared>",
                     r#"<carray_list xs.id="shared-list"><CSceneSource xs.ref="scene"/><CSceneSource xs.ref="scene-kept"/></carray_list></shared>"#)),
        ("nonbare-owner", CAN3_SCENE_EDITOR_XML.replace(
            r#"<CSceneSource xs.ref="scene"/>"#,
            r#"<CSceneSource xs.ref="scene" extra="1"/>"#)),
        ("shared-scenename", CAN3_SCENE_EDITOR_XML
            .replace(name_field, r#"<s xs.n="sceneName" xs.ref="shared-name"/>"#)
            .replace("</shared>", r#"<s xs.id="shared-name">Scene</s></shared>"#)),
        ("shared-fps", CAN3_SCENE_EDITOR_XML
            .replacen(r#"<f xs.n="fps">60</f>"#, r#"<f xs.n="fps" xs.ref="shared-fps"/>"#, 1)
            .replace("</shared>", r#"<f xs.id="shared-fps">60</f></shared>"#)),
        ("inherited-effect", CAN3_SCENE_EDITOR_XML.replacen(
            r#"<CMvKeyParamEffect xs.n="keyParamEffect">"#,
            r#"<CMvKeyParamEffect xs.n="keyParamEffect"><CMvKeyParamEffect xs.n="super" xs.ref="attr"/>"#,
            1,
        ).replacen(
            r#"<CMvTrack_Live2DModel_Source xs.n="track" xs.ref="track"/><carray_list xs.n="attrList" count='1'><CMvAttrF xs.ref="attr"/></carray_list></CMvKeyParamEffect>"#,
            r#"</CMvKeyParamEffect>"#,
            1,
        )),
        ("super-member", CAN3_SCENE_EDITOR_XML.replacen(
            r#"<i xs.n="start">0</i>"#,
            r#"<Nested xs.n="super" xs.ref="attr"/><i xs.n="start">0</i>"#,
            1,
        )),
        ("nested-id", CAN3_SCENE_EDITOR_XML.replacen(
            r#"<i xs.n="start">0</i>"#,
            r#"<Nested xs.id="nested"/><i xs.n="start">0</i>"#,
            1,
        )),
        ("outside-scene-ref", CAN3_SCENE_EDITOR_XML.replace(
            r#"<s xs.n="futureRootData">keep-root &amp; 0.1234500</s>"#,
            r#"<s xs.n="futureRootData">keep-root &amp; 0.1234500</s><Extra xs.n="friend" xs.ref="scene"/>"#,
        )),
        ("outside-track-ref", CAN3_SCENE_EDITOR_XML.replacen(
            r#"<s xs.n="futureRootData">keep-root &amp; 0.1234500</s>"#,
            r#"<s xs.n="futureRootData">keep-root &amp; 0.1234500</s><Extra xs.n="friend" xs.ref="track"/>"#,
            1,
        )),
        ("outside-curve-ref", CAN3_SCENE_EDITOR_XML.replacen(
            r#"<s xs.n="futureRootData">keep-root &amp; 0.1234500</s>"#,
            r#"<s xs.n="futureRootData">keep-root &amp; 0.1234500</s><Extra xs.n="friend" xs.ref="attr"/>"#,
            1,
        )),
        ("opaque-in-doomed-scene", CAN3_SCENE_EDITOR_XML.replace(
            r#"<carray_list xs.n="_sources" count="2"><CMvTrack_Live2DModel_Source xs.ref="track"/><CMvTrack_Live2DModel_Source xs.ref="track2"/></carray_list>"#,
            r#"<carray_list xs.n="_sources" count="3"><ExtraOpaque xs.ref="attr-opaque"/><CMvTrack_Live2DModel_Source xs.ref="track"/><CMvTrack_Live2DModel_Source xs.ref="track2"/></carray_list>"#,
        )),
    ] {
        let sub = directory.join(label);
        fs::create_dir(&sub).unwrap();
        let session_result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            can3_key_fixture_session(&sub, &variant)
        }));
        let Ok((mut session, source)) = session_result else {
            panic!("{label} failed to open");
        };
        let file = fs::read(&source).unwrap();
        let before = session.snapshot();
        let call = scene_delete(&session, "scene-guid");
        let response = request(&mut session, call);
        assert_eq!(response["succeeded"], json!(false), "{label}: {response}");
        assert_eq!(session.snapshot(), before);
        assert_eq!(fs::read(&source).unwrap(), file);
        fs::remove_dir_all(sub).unwrap();
    }
}

#[test]
fn can3_scene_add_keeps_retained_inline_and_aliased_scene_storage() {
    let directory = temp_dir();
    let scene_def_start = CAN3_SCENE_EDITOR_XML
        .find(r#"<CSceneSource xs.id="scene-kept">"#).unwrap();
    let scene_def_end = CAN3_SCENE_EDITOR_XML[scene_def_start..]
        .find("</CSceneSource>").unwrap() + scene_def_start + "</CSceneSource>".len();
    let scene_def = &CAN3_SCENE_EDITOR_XML[scene_def_start..scene_def_end];
    for (label, variant) in [
        ("inline-scene", CAN3_SCENE_EDITOR_XML
            .replace(r#"<CSceneSource xs.ref="scene-kept"/>"#, "INLINE-KEPT-MARKER")
            .replace(scene_def, "")
            .replace("INLINE-KEPT-MARKER", scene_def)),
        ("aliased-scene-guid", CAN3_SCENE_EDITOR_XML
            .replace(
                r#"<CSceneGuid xs.n="guid" uuid="scene-kept-guid"/>"#,
                r#"<CGuid xs.n="guid" xs.ref="scene-kept-guid-storage"/>"#,
            )
            .replace(
                "</shared>",
                r#"<CGuid xs.id="scene-kept-guid-storage" uuid="scene-kept-guid"/></shared>"#,
            )),
    ] {
        let sub = directory.join(label);
        fs::create_dir(&sub).unwrap();
        let (mut session, _) = can3_key_fixture_session(&sub, &variant);
        let before = session.snapshot()["model"].clone();
        let revision = session.snapshot()["revision"].clone();
        let response = request(&mut session, json!({
            "op":"live2d.animation.scene.add","name":"Added","fps":24.0,
            "durationFrames":30,"expectedRevision":revision}));
        assert_eq!(response["succeeded"], json!(true), "{label} add: {response}");
        let model = session.snapshot()["model"].clone();
        let scenes = model["scenes"].as_array().unwrap();
        assert_eq!(scenes.len(), before["scenes"].as_array().unwrap().len() + 1);
        assert_eq!(scenes[..scenes.len()-1], before["scenes"].as_array().unwrap()[..]);
        assert_eq!(model["resources"], before["resources"]);
        {
            let call = scene_delete(&session, "scene-guid");
            let response = request(&mut session, call);
            assert_eq!(response["succeeded"], json!(true), "{label} delete: {response}");
        }
        let saved = sub.join("saved.can3");
        result(&request(&mut session, json!({"op":"save","path":saved})));
        result(&request(&mut session, json!({"op":"open","path":saved})));
        let reopened = session.snapshot()["model"].clone();
        assert_eq!(reopened["scenes"].as_array().unwrap().len(), 2);
        assert_eq!(reopened["scenes"][0]["guid"], json!("scene-kept-guid"));
        assert_eq!(reopened["resources"], before["resources"]);
        fs::remove_dir_all(sub).unwrap();
    }
}

